local _, ns = ...

ns.EnsureClassGuide = function()
if ns.ClassGuide then return ns.ClassGuide end
ns.ClassGuide = {
    meta = {
        patch = "1.60.1",
        level = 30,
        updated = "2026/10/05",
    },

    specs = {
        WARRIOR = {
            arms = {
                updated = "2026/09/23",
                sections = {
                    { key = "changes", flow = {
                        { t = "p", v = "武器战士在 PvE 和 PvP 方面都获得了一些广受欢迎的变化。它并未被彻底重做，而是对一些不太实用的技能进行了增强，使它们也得以派上用场。|s11573|现在已成为武器战的更核心组成部分，它会随攻击强度提升而增强，并且现在可以造成伤害。|s1289682|，割裂现在有一定几率激活|s11585|，持续 6 秒。|s1310222|并祈求造成昏迷效果了。|s1715|无法翻译" },
                        { t = "tb", v = { { "|s1310222|", "一个强制下马的实用技能。对所有目标造成 40% 武器伤害，对巨人、龙类以及骑乘坐骑的目标额外造成 80% 武器伤害。该技能为武器战专属，可在武器天赋树深处解锁。" }, { "|s402927|", "胜利冲锋是《魔兽世界：无限》中新增的技能。所有战士专精都可使用，施放时回复 10% 最大生命值。在你击杀一个非微不足道的敌人后，可以施放胜利冲锋。" }, { "|s1290261|", "传统的斧类专精，剑类专精，长柄武器专精，以及锤类专精现已合并为单一天赋，并加入了法杖！锤类和法杖现在无视护甲，而此前锤类有一定几率击晕目标。这一改动让你在升级过程中可以更自由地切换武器类型。" }, { "|s1289682|", "血之狂热是一项新天赋，旨在让|s11573|更成为武器输出循环中的核心技能。血之狂热使割裂有一定几率激活|s11585|，持续6秒。激活几率随投入的点数增加而提升血之狂热." }, { "|s12862|", "《无限》版本中新增的另一个天赋是强化猛击。该天赋每投入一点可使|s1464|的施法时间缩短，更重要的是使你的猛击施放时不再中断近战攻击节奏！" } } },
                        { t = "tb", v = { { "|s1464|", "猛击现在拥有15秒冷却时间。" }, { "|s11573|", "割裂获得了加强，现在能更好地随攻击强度提升而成长，并且随着《无限》版本中对周期性伤害的改动，它现在也能造成暴击。" }, { "|s11580|", "雷霆一击的降低攻击速度效果从10%提升至20%。" }, { "|s12834|", "深重伤口现在也可以造成暴击。" }, { "|s11550|", "战斗怒吼的持续时间从2分钟延长至3分钟。" }, { "|s1160|", "挫志怒吼的持续时间从30秒延长至45秒。" }, { "|s20230|", "反击的冷却时间从30分钟缩短至15分钟。同时不再与以下技能共享冷却时间：|s871|或|s1719|." }, { "|s871|", "盾墙的冷却时间从30分钟缩短至15分钟，但减伤效果从75%下调至60%。同时不再与以下技能共享冷却时间：|s20230|或|s1719|." } } },
                    } },
                    { key = "viability", flow = {
                        { t = "p", v = "《魔兽世界：无限》的目标是确保每个职业和天赋专精都具备可用性。武器天赋此前主要以 PvP 为核心，因此进行了调整，使其在 PvE 和 PvP 中都更具可用性。例如|s1290261|的调整使锤类和法杖类武器无视护甲。护甲穿透是 PvE 中极为重要的属性，因为它能提升怒气获取速度。" },
                    } },
                    { key = "sw", flow = {
                        { t = "good", v = { "机动性- 凭借冲锋和拦截，在战场上拥有出色的机动性。", "爆发群体伤害- 配合横扫攻击和顺劈斩积攒怒气时，能打出强力的爆发群体伤害。", "控制- 可通过强化断筋轻松限制敌人。" } },
                        { t = "bad", v = { "怒气依赖- 攻击未命中或被招架时，容易陷入怒气匮乏。", "持续群体伤害- 由于怒气获取有限，难以维持长时间的群体伤害。", "自我治疗- 相比其他专精，被动续航能力有限。" } },
                    } },
                    { key = "beginner", flow = {
                        { t = "p", v = "在《魔兽世界：无限》中，武器战士现在是新玩家的绝佳选择。此前，武器专精一直被视为对新玩家很不友好的专精，原因在于该专精缺乏怒气生成，且过度依赖平砍计时器。当你刚接触魔兽世界时，平砍计时器的概念可能很难理解，尤其是在没有插件的情况下无法准确追踪，而你还有一大堆其他事情要关注。在《无限》中，现在有了内置的平砍计时器，这对新玩家来说至关重要。除此之外，新加入的天赋|s12862|消除了重置平砍计时器|s1464|带来的惩罚性影响。" },
                    } },
                    { key = "systems", flow = {
                        { t = "p", v = "在《魔兽世界：无限》中，战士有一个基础系统：姿态。作为武器战士，你会频繁切换姿态；这被称为姿态舞.姿态舞指的是当你能够施放需要某个姿态的法术时，快速切换到该姿态，然后迅速切回原来的姿态。例如，从|s2458|切换到|s2457|以便在|s11585|可用时立即施放，然后立刻切回|s2458|." },
                        { t = "p", v = "你也可以为了获得某个姿态的效果而切换姿态。例如，如果你需要在副本里坦克一个怪物，你可以选择|s71|来减少受到的敌人伤害。" },
                    } },
                    { key = "races", flow = {
                        { t = "p", v = "战士的独特之处在于，游戏中每个种族都可以选择战士。这让你在选择种族时有很大的自由度，取决于你的偏好或你想要的种族特长。" },
                        { t = "races", v = { { race = "人类", side = "alliance", mark = "tick" }, { race = "矮人", side = "alliance", mark = "tick" }, { race = "暗夜精灵", side = "alliance", mark = "tick" }, { race = "侏儒", side = "alliance", mark = "tick" }, { race = "兽人", side = "horde", mark = "tick" }, { race = "亡灵", side = "horde", mark = "tick" }, { race = "牛头人", side = "horde", mark = "tick" }, { race = "巨魔", side = "horde", mark = "tick" } } },
                        { t = "p", v = "无限服新增的职业-种族组合" },
                        { t = "p", v = "在选择种族时没有绝对的差选项。虽然有些种族会比其他种族更强，但这些差距非常微小。对联盟来说，根据你是更倾向于 PVE 还是 PVP，种族选择会更有讲究；而部落方面，最佳选择相对比较直接。" },
                        { t = "p", v = "新种族" },
                        { t = "p", v = "天裔战士是随《魔兽世界：无限》一同推出的新种族，联盟和部落均可选择。可惜的是，天裔的种族特长更侧重于改善升级体验，对于追求最强终局表现的玩家来说会稍显逊色。天裔可以使用|s1259416|，让他们能够从高处跳下、在空中快速移动，并在空中改变方向。天裔还可以在主题区域使用|s1259686|，在元素汇聚点附近使用可获得持续 15 分钟的 10% 移动速度加成；否则只能持续 30 秒。天裔拥有两项伤害类种族特长|s1259707|和|s1259710|。他们还拥有一个名为的自疗种族特长|s1259705|." },
                        { t = "h4", v = "联盟" },
                        { t = "p", v = "夜精灵战士 尽管联盟种族的优劣较为主观，但夜精灵似乎是《无限》中联盟武器战最佳的 PVE 种族。|s1259799|非常强力，在15秒内提升暴击10%。由于武器天赋的重新调整，暴击的收益更高了，|s11573|和|s12834|现在可以造成暴击。此外，暴击属性与饰品组合在一起非常强力。除此之外，夜精灵还可以使用|s20580|，|s20582|，以及|s20585|." },
                        { t = "p", v = "侏儒战士 侏儒战士是联盟的另一个绝佳选择，在 PvE 和 PvP 中都是更为全面的选择。侏儒可以使用|s1259812|，激活后使你接下来施放的3个法术造成的伤害提高，同时怒火值降低10%。其种族特长|s1259802|现在还加入了怒气值，提高了武器战的最大怒气上限。此外，他们的种族特长|s20589|现在还能免疫移动受限类效果。侏儒还可以使用|s20593|." },
                        { t = "p", v = "人类战士人类也是联盟战士的强力种族选择，但在《魔兽世界：无限》中更偏向 PvP 导向。人类现在拥有著名的种族特长|s1259718|，立即解除所有昏迷效果。人类还非常擅长对付潜行目标，依靠|s20600|人类不仅在 PvP 方面表现出色，因为他们可以|s20597|，在装备剑类武器时暴击提高2%。他们还可以使用|s20598|，这是一个很实用的种族特长。" },
                        { t = "p", v = "矮人战士 矮人战士是战士职业的稳健之选。他们的|s1259719|使他们的锤类武器暴击几率提高1%，并且他们的|s1259721|对野兽造成的伤害提高5%。他们还可以使用|s20594|，立即移除流血、中毒和疾病效果并免疫这些效果，同时使受到的所有物理伤害降低10%，持续8秒。此外，矮人还可以使用|s2481|." },
                        { t = "h4", v = "部落" },
                        { t = "p", v = "兽人战士 兽人通常是部落的最佳选择。它提供|s20572|，这在PVE和PVP中都非常出色。它还有|s20574|，使斧类武器的暴击几率提高1%。除此之外，它还有|s20573|，使昏迷持续时间缩短20%，以及|s1299026|，使你对诅咒和灾祸免疫，并使受到的魔法伤害降低15%，持续8秒。" },
                        { t = "p", v = "巨魔战士 巨魔是部落战士的第二佳选择。它可以使用|s20554|，使你的近战攻击速度提高10%，持续10秒。它还有另一个进攻性种族特长，通过|s20557|使对野兽类型敌人造成的伤害提高5%。巨魔还有2个治疗性种族特长。它们是|s20555|和|s1260270|." },
                        { t = "p", v = "牛头人战士 牛头人战士的伤害输出较低，但更注重生存能力和群体控制。牛头人还可以使用|s20549|，眩晕8码范围内的5个敌人0.5秒。其种族特长|s20550|提供5%最大生命值和1%的额外命中加成。除此之外，牛头人现在还可以使用|s12566|，在40级之前练级时非常好用，以及|s20552|，可以赚取一些额外的金币。" },
                        { t = "p", v = "亡灵战士 亡灵可以说是战士较差的选择之一，对PvE或PvP都没有实际增益。|s7744|还不错，但战士已经有了名为|s18499|的恐惧免疫技能。亡灵还可以使用|s20577|和|s5227|，练级时很实用。他们还有一个新天赋|s1260189|" },
                        { t = "p", v = "无限服中武器战士的专业" },
                        { t = "p", v = "每种专业都有各自的利弊，不存在糟糕的专业搭配。你可以选择两项采集专业来赚取更多金币，或选择两项制造专业。无论选择哪种，只要符合你的目标即可。以下列出的专业是我推荐给大多数战士的，因为在我看来，它们在练级和后期的终局玩法中都能提供最佳的路线。" },
                        { t = "p", v = "工程学对于武器战而言在经典旧世版本中，工程学通常是终局PvE和PvP的最佳专业选择，这一点在无限版中并未改变。在终局内容里，工程学凭借各种小道具和炸弹能带来巨大的实用性和伤害加成。不过我不建议在升级过程中选择它，因为它的营火增益效果价值有限，而且炸弹若经常使用成本也不低。升级时我更倾向于选择下面提到的另外两个专业，待满级后再放弃其中一个转而学习工程学。" },
                        { t = "p", v = "采矿对于武器战而言采矿在无限版中有了几项关键改动。最大的改动是地图上矿点的数量。以前，你的等级提升速度往往快于采矿技能的提升，这迫使你不得不返回旧区域练采矿技能，才能在新升级区域采集矿点。在无限版中，这个问题基本得到了解决。矿点数量大幅增加，以至于我经常直接跳过一些矿点，技能依然跟得上进度。不过如果你仍然遇到这个问题，熔炼的新改动也能解决它。现在你可以从1一直熔炼到300点技能，所以即便你跳过了矿点，也可以通过熔炼来提升技能，而不必返回旧区域花时间采矿。" },
                        { t = "p", v = "升级时选择采矿的另一个重要原因是它的营火增益效果。它是战士可用的最佳营火增益之一，前提是你不是与圣骑士组队升级，因为该增益无法与圣骑士的叠加。|s19838|." },
                        { t = "p", v = "锻造对于武器战而言在无限版中，无论是为了终局内容还是升级过程，锻造都是战士的绝佳选择。锻造新增了多种配方，让你在升级过程中就能打造更精良的装备。资料片上线时，锻造也会很容易练，因为你可以将武器等制品以高于成本的价格出售。锻造搭配采矿是升级期间的稳健组合，你可以在采集矿石熔炼后，回到主城利用熔炼所得来制作装备升级。" },
                        { t = "p", v = "锻造的营火增益同样是战士可用增益中的佼佼者，前提是你不是与萨满祭司组队升级，因为该增益无法与萨满祭司的叠加。|s25361|." },
                    } },
                },
            },
            fury = {
                updated = "2026/09/21",
                sections = {
                    { key = "changes", flow = {
                        { t = "p", v = "狂怒战士在《魔兽世界：无限》中经历了多项重大改动，既有直接的也有间接的。其中最重要的是怒气生成的改动；《魔兽世界：无限》中的怒气现在已被标准化，与当年《大灾变》所做的改动类似。这意味着攻击会根据公式在固定范围内生成固定数量的怒气；怒气不再与直接自动攻击造成的伤害挂钩，暴击也不会产生额外怒气。因此，我们的怒气生成不随装备而提升，增加怒气获取的唯一方式就是受到更多伤害。这会导致我们的怒气生成相比其他版本的经典狂怒战士大幅降低，进而减少我们可以使用的技能数量。我们现在必须更加谨慎地管理怒气，无法再像以前那样频繁地使用技能。" },
                        { t = "p", v = "此外，敌人的护甲无法再被削减到之前的程度，|s9907|并且|s11717|不再与它们的护甲削减效果叠加。这进一步大幅降低了我们的伤害，尤其因为我们完全依赖物理伤害，并不具备任何基础的神力伤害技能。" },
                        { t = "tb", v = { { "|s1310315|", "一项源自《燃烧的远征》的新天赋，让我们的旋风斩能够同时命中主副手武器，使我们的副手也能参与群体伤害输出，同时让我们可以选择的副手武器种类更加丰富。" }, { "|s402927|", "另一项来自《燃烧的远征》的技能，在20级时可习得，会在击杀触发时激活，允许施放该技能，造成中等伤害并根据生命百分比回复少量生命值。" }, { "|s1310185|", "一项新的基础冷却能力，让你在切换姿态时保留少量怒气。" } } },
                        { t = "tb", v = { { "|s23881|", "该技能的伤害加成被大幅下调，从攻击强度的45%降至40%，但获得了一个随等级增加的小幅且几乎可以忽略不计的固定伤害加成。" }, { "|s12317|", "狂暴现在会在受到任何直接伤害时触发，而不再仅限于受到暴击时。" }, { "|s23584|", "现在为副手提供10%的命中率加成，作为移除\\\"下次攻击未命中惩罚\\\"漏洞的补偿。" } } },
                    } },
                    { key = "viability", flow = {
                        { t = "p", v = "乍看之下，狂怒战士似乎与基础经典版中的对应天赋相当相似——它保持着相同的输出循环，使用类似的天赋构筑，技能套装的变化或新增也非常少。然而，深入观察后会发现，在副本及团队副本的末期内容中，狂怒战士的处境相当艰难。" },
                        { t = "p", v = "世界增益的移除对狂怒战士是一个巨大打击，它曾是游戏中成长性最强的天赋之一。此外，怒气标准化严重限制了我们的爆发技能使用频率，而首领护甲的提高进一步削减了我们的伤害。如今队伍配置比以往任何时候都更加重要——关键的团队增益如|s10614|并且|s17007|其重要性比以往更高，由于其他属性的缺失，它们的相对威力被大幅提升，因此务必将其加入输出循环。" },
                        { t = "p", v = "我们的技能也有一些显著改动——|s23881|遭到了削弱，尽管它本就因我们可获得的攻击强度较低而处于疲软状态。强化战斗怒吼天赋也已被移除，这降低了我们的团队增益能力。或许最值得注意的是，我们标志性的输出爆发技能，|s1719|的冷却时间没有发生任何改动，依然为30分钟，而类似的冷却技能例如|s417141|拥有3分钟的冷却时间。" },
                    } },
                    { key = "sw", flow = {
                        { t = "p", v = "在战士强势的领域，即低目标顺劈场合，战士表现出色，无可匹敌。但在长时间的单体战斗中，尤其是几乎没有承受伤害时，表现会较差。" },
                        { t = "good", v = { "强化顺劈斩- 对低血量目标有强大的群体伤害能力，技能如|s20569|并且|s1680|.", "强力爆发- 强力的爆发技能，例如|s12328|让我们在关键时刻打出爆发伤害。", "生存能力强- 高基础生命值加上穿戴板甲的能力，让狂怒战士能够硬抗伤害。" } },
                        { t = "bad", v = { "依赖装备- 需要大量装备才能达到特定属性上限", "主要爆发技能冷却时间长-|s1719|的冷却时间为30分钟。" } },
                    } },
                    { key = "beginner", flow = {
                        { t = "p", v = "狂怒专精表面上相对简单——即便要打出高水平表现，其输出循环也不算特别复杂，而且身板够硬，犯错也能存活。不过，它对怒气管理的要求有时颇为复杂，而且出了名的算不上最强的练级专精。在单人内容中可能会比较吃力，有他人支援时表现最佳，同时也适合参与团队内容。" },
                    } },
                    { key = "races", flow = {
                        { t = "p", v = "乍看之下，战士的可选种族竞争相当激烈，兽人显著领跑，但巨魔、暗夜精灵和亡灵紧随其后。不过，随着未来的数值调整，这一格局可能会发生变化。新种族天裔双方阵营均可选择战士。" },
                        { t = "races", v = { { race = "人类", side = "alliance", mark = "tick" }, { race = "矮人", side = "alliance", mark = "tick" }, { race = "暗夜精灵", side = "alliance", mark = "tick" }, { race = "侏儒", side = "alliance", mark = "tick" }, { race = "兽人", side = "horde", mark = "tick" }, { race = "亡灵", side = "horde", mark = "tick" }, { race = "牛头人", side = "horde", mark = "tick" }, { race = "巨魔", side = "horde", mark = "tick" } } },
                        { t = "p", v = "无限服新增的职业-种族组合" },
                        { t = "h4", v = "联盟" },
                        { t = "p", v = "对联盟的狂怒战士来说，暗夜精灵似乎是首选，其种族特长提供强力的主动暴击提升和额外移动速度。侏儒看起来也是个稳妥的选择，其新种族特长可以与我们的爆发技能搭配，打出高额的伤害爆发，还附带一些脱离控制的实用功能。人类和天裔或许各有小众用途，但似乎弱于其他选项。矮人则看起来完全不占优势。" },
                        { t = "h4", v = "部落" },
                        { t = "p", v = "兽人似乎是狂怒战士整体最强的种族，拥有两种强大的伤害增益种族特长，还有昏迷时间缩短和强力的魔法防御。巨魔和亡灵同样相当强力，他们都拥有强力的种族特长，可能不如兽人那样全面，但能在其他方面有所补足。天裔在以急速为核心价值的首领战中可能会有用武之地，取决于急速的价值。牛头人的命中加成相对较弱，其昏迷技能在PvP中可能有用武之地。" },
                    } },
                    { key = "prof", flow = {
                        { t = "p", v = "初步发现表明，工程学将再次成为狂怒战士最强的专业——其提供的强力道具和爆炸物能增强狂怒战士的优势与机动性，尤其是在单刷内容中。炼金术似乎也是个强力选择，其合剂与药剂的持续时间和效果增强可能带来可观的属性提升。" },
                    } },
                },
            },
            prot = {
                updated = "2026/10/03",
                sections = {
                    { key = "changes", flow = {
                        { t = "p", v = "防护战士一直是经典旧世里首选的坦克，因为他们拥有最完整的工具箱。也就是说，进入《魔兽世界：无限》后，防护战士是改动最小的坦克。话虽如此，防护战士这次的更新也足够多，足以改变我们玩这个专精的思路。" },
                        { t = "p", v = "经典旧世坦克的一个问题在于：当输出玩家随装备成长时，坦克未必以同样的速度成长，坦克与输出之间的仇恨鸿沟会随时间越拉越大。结果就是，团本环境里的战士坦克大多选择玩一种输出型坦克，人称狂暴坦（Fury-prot）——毕竟承受的伤害低，而仇恨需求又高。" },
                        { t = "p", v = "《魔兽世界：无限》为解决这个问题做了不少努力：在防护天赋树里直接加入了仇恨系数（例如|s12792|），并给|s11601|这类技能追加了额外的攻击强度加成。我们还预计伤害构成与战斗时长会与以往不同，因此剑盾流派很可能回归——即便创意_builds依然有发挥空间。" },
                        { t = "p", v = "在《无限》里，防护战士只通过|s402927|获得一个新技能，但它似曾相识。话虽如此，几乎整个防护天赋树都被重做了，我们的工具箱比以前宽了不少。" },
                        { t = "tb", v = { { "|s402927|", "立即攻击目标，造成 (1 + 攻击强度 * 15 / 100) 点伤害，并为你恢复最大生命值的10%。只能在击杀非普通敌人后的20秒内使用。这让战士在练级路上获得了急需的续航。" }, { "|s1310317|", "你的冲锋技能现在可以在防御姿态下使用。" }, { "|s16538|", "装备盾牌时，你所造成的所有伤害提高10%。" }, { "|s23602|", "装备盾牌时，你每闪避或招架一次就产生5点怒气。" }, { "|s29787|", "使你的进攻类技能的怒气消耗降低3点。" } } },
                        { t = "p", v = "防护 Warrior 的改动虽然多，但有一点值得单独一提：|s11581|现在可以在|s71|下使用，冷却也从4秒延长到6秒。再加上大量新增的怒气生成天赋，以及受到伤害（包括吸收效果）就能回怒的机制，防护战士终于有了同时拉住 1-2 个以上目标的能力，而不必在怪物之间疯狂切换目标。防御姿态下可用的雷霆一击（因此享受姿态的仇恨加成），加上不会怒气枯竭的|s20569|额外施放机会，战士在地下城和团本里的体验应该会舒服不少。" },
                        { t = "tb", v = { { "|s11581|", "需要战斗姿态。用雷霆震击附近的敌人，使他们的攻击间隔延长10%，持续30秒，并对其造成103点伤害。最多影响4个目标。", "需要战斗姿态、防御姿态。用雷霆震击附近的敌人，使他们的攻击间隔延长20%，持续30秒，并对其造成伤害。最多影响4个目标。" }, { "|s2565|", "使你的格挡几率提高75%，持续5秒，但只能格挡1次攻击。", "使你的格挡几率提高75%，持续7秒，且可以格挡2次攻击。" }, { "|s871|", "使你受到的近战、远程攻击和法术伤害降低75%，持续10秒。30分钟冷却。", "使你受到的所有伤害降低60%，持续12秒。15分钟冷却，且可通过天赋进一步缩短。" }, { "|s1310185|", "天赋：改变姿态时最多保留25点怒气。", "基础技能：改变姿态时最多保留10点怒气。" }, { "|s12298|", "使你用盾牌格挡攻击的几率提高5%，并在格挡发生时有100%的几率产生1点怒气。", "使你用盾牌格挡攻击的几率提高5%，并在你格挡时有100%的几率产生5点怒气。" }, { "|s12297|", "使你的防御技能提高10点。", "使你的防御技能提高20点。" }, { "|s12301|", "使你的血性狂怒技能即时产生的怒气提高2点。", "使你的血性狂怒技能产生的所有怒气提高50%。" }, { "|s12797|", "使你的复仇技能有15%的几率击晕目标3秒。", "使你的复仇技能造成的伤害提高60%。" }, { "|s12792|", "在防御姿态下，使你的攻击产生的威胁值提高15%。", "在防御姿态下，使你产生的所有威胁值提高30%，并使你的攻击强度提高10%。" } } },
                    } },
                    { key = "beginner", flow = {
                        { t = "p", v = "防护战士本身并不是特别难上手的专精，但在学习拉怪、尤其是多目标仇恨管理时，可能还是会遇到一些痛点。" },
                        { t = "p", v = "《魔兽世界：无限》让战士坦克变得更宽容了：即使不玩姿态舞（在不同姿态之间来回切换以使用|s71|下无法使用的技能），你也能发挥这个专精的大部分价值。姿态舞是你随着对职业理解的加深应该去掌握的系统，但由于|s11581|和|s11578|（天赋支持）都可以在防御姿态下使用，不玩姿态舞你依然能当一个称职的坦克。" },
                        { t = "p", v = "一个基本的经验法则：除非怒气严重溢出，否则不要用|s78|。在练级过程中随着怒气生成天赋增多，这点会越来越不重要——一般来说，用|s11597|和|s25288|这类技能能打出更高的伤害和仇恨。|s78|的另一个问题在于它绑定你的近战挥击：不仅使用要花怒气，还让你失去这一次挥击本该产生的怒气。" },
                    } },
                    { key = "systems", flow = {
                        { t = "ul", v = { { text = "|s2457|- 产生的威胁值降低20%。\n该姿态下的关键技能：|s20230|、|s11585|、|s20662|，以及|s100|（除非有天赋支持）。" }, { text = "|s2458|- 爆击几率提高3%，受到的所有伤害提高10%。\n该姿态下的关键技能：|s1719|、|s1680|、|s20252|，以及|s20662|。" }, { text = "|s71|- 受到的伤害降低10%，造成的伤害降低10%，产生的所有威胁值提高30%。这是防护战士坦克的基准姿态。\n该姿态下的关键技能：|s871|、|s2565|，以及|s676|。" } } },
                        { t = "p", v = "战士用怒气作为资源系统。怒气来自：用普通近战挥击造成伤害、承受伤害、|s11578|和|s2687|这类技能，以及通过天赋|s12298|和|s1310316|在格挡、闪避或招架攻击时产生。在《魔兽世界：无限》里，怒气会根据你打的内容不同而成为相当大的制约，所以一个合格的战士，关键就在于你如何分配这些怒气。" },
                        { t = "p", v = "此外，战士有3种姿态：|s2457|、|s2458|和|s71|。这些姿态各自带有专属效果，但部分技能只能在特定姿态下使用。" },
                        { t = "p", v = "设置好在不同姿态之间来回切换以释放特定技能的宏，对你玩好防护战士至关重要。|s1310185|成为基础被动让这件事变容易了一些，武器系天赋里的|s12295|还提供了额外的怒气保留。" },
                    } },
                    { key = "races", flow = {
                        { t = "p", v = "战士需要好好琢磨选什么种族——因为游戏里的所有种族都能当战士。由于最近的种族平衡调整，哪个种族的整体收益最高还不好说。更准确地说，每个种族都有自己的细分定位，即便在同一个细分里（比如高端团本），不同种族也会因首领类型不同而互有胜负。总之，《魔兽世界：无限》里没有经典旧世那种一枝独秀的选择，所以只要你不追求极限优化，选一个你喜欢的审美和幻想设定的种族就好。" },
                        { t = "races", v = { { race = "人类", side = "alliance", mark = "tick" }, { race = "矮人", side = "alliance", mark = "tick" }, { race = "暗夜精灵", side = "alliance", mark = "tick" }, { race = "侏儒", side = "alliance", mark = "tick" }, { race = "兽人", side = "horde", mark = "tick" }, { race = "亡灵", side = "horde", mark = "tick" }, { race = "牛头人", side = "horde", mark = "tick" }, { race = "巨魔", side = "horde", mark = "tick" } } },
                        { t = "p", v = "《无限》新增的职业-种族组合" },
                        { t = "h4", v = "联盟" },
                        { t = "p", v = "人类战士" },
                        { t = "p", v = "在最初的《魔兽世界》里，人类是事实上的最优种族，因为他们拥有价值极高的武器专精加成。在《魔兽世界：无限》中，种族加成经过重做，|s20597|现在改为使所有攻击和法术的爆击几率提高2%。由于滚动型持续伤害与目标身上的减益不再有数量上限，|s23255|如今成了可用的天赋，人类因此变成一个非常有趣的选择。" },
                        { t = "p", v = "|s1259718|也加入了游戏，每3分钟可以解除一次昏迷效果。这在PvP里的价值显而易见，在PvE中同样大有用处。" },
                        { t = "p", v = "假设你最好的武器里剑类随手可得，人类很可能就是你的最佳选择。" },
                        { t = "p", v = "矮人战士" },
                        { t = "p", v = "矮人同样能通过种族特长获得大量实用功能：|s1259719|提供1%爆击几率加成，虽然只有人类版本的一半强度。" },
                        { t = "p", v = "为了弥补强度差，矮人拥有|s20594|——由于流血效果无法被驱散，它的特定使用场景相当强力。" },
                        { t = "p", v = "此外，|s1259721|对野兽的伤害提高5%。世界上野兽类敌人的数量出乎意料地多，这让它成为练级神器。团本环境里野兽通常不多，但《魔兽世界：无限》后续还会有新团本，这个种族特长的完整价值还无法评估。" },
                        { t = "p", v = "总而言之，矮人是一个很棒的备选，在特定场景下甚至可能优于人类。" },
                        { t = "p", v = "侏儒战士" },
                        { t = "p", v = "侏儒在《无限》里其实变得有趣起来，但主要是作为PvP选项。作为新增内容，侏儒获得了|s1259817|，使你的下3次攻击提高10%，与|s12328|这类技能配合极佳。此外，|s20589|被改为不仅能解除移动限制效果，还会在使用后让你免疫这些效果3秒，与|s1044|的机制类似。" },
                        { t = "p", v = "在PvE环境里，侏儒不会是我的第一或第二选择。" },
                        { t = "p", v = "暗夜精灵战士" },
                        { t = "p", v = "暗夜精灵凭借重做后的种族特长在《无限》里强得出人意料。你现在拥有一个和侏儒一样的3分钟冷却技能，但效果是通过|s1259799|获得15秒的10%爆击增益。它与|s12328|这类技能配合得不错，但往防护深处加点时协同有限。你的主攻冷却技能|s1719|本身就把爆击率拉到100%，所以这两个技能绝不应该同时开。" },
                        { t = "p", v = "|s20582|现在除了1%闪避还带来2%移动速度，这可不是小数目；而且能用上|s20585|对团队氛围也很友好——毕竟你死后跑尸的时间越短，你骂治疗的时间就越少。" },
                        { t = "h4", v = "部落" },
                        { t = "p", v = "兽人战士" },
                        { t = "p", v = "对防护战士来说，兽人在攻防两端看起来都特别强。|s20574|只要你装备斧类武器就提供1%的固定爆击提升，虽然我们还得看看毕业武器里有几把是斧子，但可以假定它有不小的价值。" },
                        { t = "p", v = "|s20572|现在改为2分钟冷却、15秒内提高10%攻击强度。我们没有任何能与它对齐的冷却技能，但它依然是一个强力爆发。值得一提的是，部分技能不吃攻击强度加成，比如按格挡值成长的|s23925|。" },
                        { t = "p", v = "|s1299026|已成为一个小型法伤防御冷却技能，现在还能解除诅咒与灾厄效果。|s20573|带来的20%昏迷时长缩减，在经典式环境里同样不容小觑。" },
                        { t = "p", v = "兽人看起来是战士最全面的备选种族。" },
                        { t = "p", v = "牛头人战士" },
                        { t = "p", v = "|s20550|经过重做，为防护战士提供了极强的功能性——因为我们非常看重生命值和命中。虽然还没见到满级阶段的配装风格，但可以放心假设：这1%命中总能给你带来大量价值，无论是凑近战命中上限，还是给|s355|提供额外的命中几率。" },
                        { t = "p", v = "|s20549|也能派上用场，尤其是在练级和刷地下城时；但要注意面对多个怪物时的施法推后——施法过程中你无法格挡、闪避或招架。" },
                        { t = "p", v = "|s1259918|经过重做，改为提高移动速度（尤其是在脱战状态下），最高可叠加到30%。这在野外练级时好用到离谱，尤其是在 40 级之前——经典式练级体验里有大把的路要赶。" },
                        { t = "p", v = "对防护战士来说这是一个非常强的选择，特别适合偏好防御型打法的玩家。" },
                        { t = "p", v = "巨魔战士" },
                        { t = "p", v = "巨魔保留了原有的种族特长，新增了|s1260270|：6秒内回复50%生命值，战斗内外均可使用。任何移动、动作或受到伤害都会打断该效果，但它依然有相当不错的实用性，尤其是在PvP中对阵非持续伤害职业时——你可以在施放|s5246|之后回血。在PvE中也有用，但在团本环境里价值较低。" },
                        { t = "p", v = "此外，|s20557|对野兽的伤害提高5%。世界上野兽类敌人的数量出乎意料地多，这让它成为练级神器。团本环境里野兽通常不多，但《魔兽世界：无限》后续还会有新团本，这个种族特长的完整价值还无法评估。" },
                        { t = "p", v = "由于怒气的标准化，|s20554|同样不容小觑，它提供的价值可能超出我们的预期。" },
                        { t = "p", v = "亡灵战士" },
                        { t = "p", v = "亡灵种族获得了一些看起来对战士很有价值的新种族技能。攻击敌人时，|s1260189|有5%的几率抽取目标，最多为你回复自身最大生命值的5%。目前来看它的内置冷却似乎只有1秒，触发会相当频繁。不过，具体哪些技能能触发该效果、低伤害技能能抽到多少血，仍不明确。" },
                        { t = "p", v = "此外，亡灵还有|s7744|，在PvP和PvE里都有强力使用场景。|s20577|对战士来说也非常受欢迎，练级期间尤其如此。" },
                        { t = "h4", v = "联盟与部落通用" },
                        { t = "p", v = "天裔战士" },
                        { t = "p", v = "新种族天裔对防护战士来说相当平淡：|s1259707|只提供场景性的功能。世界里的元素生物出现频率不算高，但根据后续更新的新内容类型，我们也许会在新团本里见到更多。" },
                        { t = "p", v = "|s1259416|可以当作缓落类技能使用，在开放世界里（尤其是想从高处跳下来的时候）相当实用。" },
                        { t = "p", v = "|s1259710|的价值还有待观察，但急速历来对防护战士的收益都很低。" },
                    } },
                    { key = "prof", flow = {
                        { t = "p", v = "目前还不清楚哪些专业技能对防护战士收益最大。纵观各个经典资料片，工程学一直是最强选项。坦克一直面临「够不着远处怪物、拉不到仇恨」的问题，而工程师造的手雷正好能解决这个问题。" },
                        { t = "p", v = "不过，除工程学外的所有专业都能通过属性获得一项特殊加成。这些属性加成能否胜过工程学的收益，还有待观察。" },
                        { t = "p", v = "开局选工程学搭配锻造或珠宝加工，大概率是稳妥的组合。" },
                    } },
                },
            },
        },
        PALADIN = {
            holy = {
                updated = "2026/09/21",
                sections = {
                    { key = "changes", flow = {
                        { t = "p", v = "神圣圣骑士的新增内容主要专注于补齐此前工具集中的短板，并简化一些繁琐的操作。整体效果是一套更加均衡的技能体系，让你能够专注于战斗本身，而不是不停地维护增益。" },
                        { t = "p", v = "其中最核心的就是|s1311595|，这是神圣天赋树的新终极技能。它是一项全新的群体治疗手段，同时与|s20930|有大量联动，甚至可以用于造成伤害。" },
                        { t = "tb", v = { { "|s1311595|", "为目标施加光明警戒，持续30秒。你对其施放的下一记圣光闪现不进入冷却时间，并使友方目标治疗其小队成员，或使敌方目标受到神圣伤害，同时返还光明警戒75%的法力值。同一圣骑士对同一小队同时只能存在1个光明警戒。" }, { "|s10333|", "一次瞬发打击，造成40%武器伤害，并附加额外神圣伤害。" }, { "|s1310897|", "使你免疫沉默和打断效果，持续6秒。" } } },
                        { t = "p", v = "现有技能方面最重要的改动是祝福类增益的持续时间延长至1小时。这意味着过去每5分钟就要为小队刷新增益的操作已经不复存在。" },
                        { t = "tb", v = { { "像|s25290|", "祝福的持续时间由5分钟延长至1小时。" }, { "|s20271|", "使用时不再消耗当前已激活的圣印增益。" } } },
                    } },
                    { key = "beginner", flow = {
                        { t = "p", v = "神圣圣骑士的核心循环相当简单，新玩家也能轻松上手。原本那些令人烦躁、不顺畅的地方在《魔兽世界：无限》都得到了改善；该专精自给自足，拥有强力的治疗能力、非常优秀的防御技能和可观的伤害输出，练级体验会非常顺畅。" },
                        { t = "p", v = "唯一可能稍显复杂的地方在于你最终会掌握相当多的技能。随着等级提升，你会解锁各种不同的祝福、增益、光环和圣印，可能需要花点时间才能学会每种情况下最好用哪个。" },
                    } },
                    { key = "systems", flow = {
                        { t = "p", v = "圣骑士玩法的一部分就是管理你的圣印。这些效果包括|s20349|和|s20357|等，它们会给你不同的增益，而你同一时间只能激活一种圣印效果。此外，使用|s20271|会根据你当前激活的圣印对目标造成不同效果。例如，被光明圣印审判的敌人有几率治疗攻击它的人，而被智慧圣印审判的敌人则会偶尔恢复法力值。对当前带有你某个圣印审判效果的敌人进行自动攻击，会刷新该效果的持续时间。" },
                        { t = "p", v = "你对目标施加的审判效果不必与你当前激活的圣印一致：你可以先激活|s20349|，然后对首领使用|s20271|，这样你的队伍攻击它时就能获得治疗，紧接着切换到|s20357|，这样你自己的自动攻击就能恢复法力值，并刷新首领身上的光明圣印效果。为了输出伤害，你可以用|s20308|对敌人施放审判，使其承受额外的神圣伤害，然后切换到|s20293|，让你的攻击造成神圣伤害，而这一伤害会因十字军圣印的效果而提高。" },
                    } },
                    { key = "races", flow = {
                        { t = "p", v = "《魔兽世界：无限》引入了前所未有的新种族/职业组合，包括让部落也能拥有圣骑士。" },
                        { t = "races", v = { { race = "人类", side = "alliance", mark = "tick" }, { race = "矮人", side = "alliance", mark = "tick" } } },
                        { t = "p", v = "无限服新增的职业-种族组合" },
                        { t = "h4", v = "联盟" },
                        { t = "p", v = "联盟圣骑士的选择有 和 。这两者中 更有优势，因为其种族特长组合|s20597|提供了比 更多的暴击|s1259719|并且还拥有|s20598|。 则拥有|s20594|，这是一个强大的效果，但圣骑士已经有其他方式解除自身所有这类效果。" },
                        { t = "h4", v = "部落" },
                        { t = "p", v = "如果你打算玩部落，其实没有太多选择，因为 是在无限服中唯一拥有该职业的种族。" },
                    } },
                    { key = "prof", flow = {
                        { t = "p", v = "神圣圣骑士最好的专业是 和 。 提供各种实用和生活质量物品，而 则能让你制作一些自己的装备。这两个专业都需要通过 获取材料，所以如果你不打算购买所有矿石，就需要只选其中一个，并将采矿作为第二专业。" },
                    } },
                },
            },
            prot = {
                updated = "2026/09/18",
                sections = {
                    { key = "changes", flow = {
                        { t = "p", v = "防护圣骑士一直以来都拥有一套相当完善的坦克工具包，但总有一个问题阻碍了他们在团队副本中的广泛出场，那就是缺少一个类似|s355|的技能。如今这个问题已经通过引入|s20423|得到了解决，它允许你的|s20271|。此外，过往的痛点，比如战斗中缺乏法力回复，也通过天赋树得到了解决，玩防护圣骑士的手感应该比以往任何时候都好。" },
                        { t = "p", v = "在《魔兽世界：无限》中，我们获得了前所未有的新技能，填补了防护圣骑士此前工具包中的空白。防护圣骑士也成为了唯一没有专门百分比减伤爆发技能的坦克，转而依赖|s1311015|，一个持续8秒的超大吸收盾。" },
                        { t = "tb", v = { { "|s20423|", "使圣骑士充满神圣之怒，持续30秒，使近战攻击额外造成（法术强度的10%）神圣伤害。装备盾牌时，每次攻击还会获得一个吸收盾，数值等于所造成神圣伤害的50%。同一时间圣骑士只能激活一个圣印。释放该圣印的能量会对敌人造成（法术强度的45%）神圣伤害，并嘲讽目标攻击你，持续4秒。" }, { "|s1311015|", "激活后，该技能为你提供一个吸收盾，数值等于你最大生命值的100%，持续8秒。施加1分钟的自律。自律激活期间无法施放。" }, { "|s17143|", "一次瞬发打击，造成42.0%武器伤害外加额外神圣伤害。" }, { "|s1224697|", "使你的总耐力提高4%，并使你的圣盾术、神圣保护和保护者壁垒的冷却时间缩短60秒。" }, { "|s1314104|", "当狂怒圣印的护盾被完全吸收时，恢复60点法力值，攻击者每比你高一级则提高15%，最多提高45%。" }, { "|s1310994|", "结束你审判技能的剩余冷却时间，并使你下一次审判的法力消耗降低100%。" }, { "|s1311034|", "使你的神圣震击产生的威胁值提高30%。当正义之怒激活时，神圣震击还会使你承受的伤害降低15%，持续6秒。" } } },
                        { t = "p", v = "虽然防护圣骑士的改动很多，但有一个重要的技能需要特别说明，那就是|s20923|的改动。这个标志性技能是防护圣骑士成为强力AOE坦克的原因所在，虽然现在依然如此，但效果会大打折扣。该技能现在对效果范围内的所有目标只造成极低的伤害，但有一个加成效果，会提高对进入区域的前4个目标的伤害。这将使该技能更接近防护战士和野性德鲁伊那种目标数限制在3-4的AOE。" },
                        { t = "tb", v = { { "|s20923|", "在圣骑士脚下的大地施加神圣之力，进入该区域的敌人每8秒受到280点神圣伤害。", "在圣骑士脚下的大地施加神圣之力，进入该区域的敌人每8秒受到64点神圣伤害。进入该区域的前4个敌人额外受到[(法术强度的9.5%) * 8]点伤害，持续8秒。" }, { "|s20928|", "使你的盾牌格挡几率提高30%，持续10秒，且在激活期间每成功格挡一次攻击便造成130点神圣伤害。神圣之盾造成的伤害额外产生20%的威胁值。每次格挡消耗一次充能。最多4次充能。", "使你的盾牌格挡几率提高20%，持续10秒，且在激活期间每成功格挡一次攻击便造成221点神圣伤害。神圣之盾造成的伤害额外产生20%的威胁值。" }, { "|s20127|", "你在受到一次暴击攻击后，使你的盾牌格挡几率提高30%。持续10秒或5次格挡。", "近战伤害性攻击命中你时，有10%的几率使你的盾牌格挡几率提高30%。持续10秒或5次格挡。" }, { "|s20096|", "防御技能提高10点。", "防御技能提高20点。" }, { "|s20189|", "使用近战武器时的命中率提高1%。", "使你的命中几率提高1%。" }, { "|s20468|", "使你的正义之怒法术产生的威胁值提高50%。", "正义之怒激活期间，你受到的所有伤害降低6%。" }, { "|s20148|", "使你的盾牌吸收的伤害提高30%", "使你的盾牌吸收的伤害提高30%，并使你的格挡有100%的几率恢复6%的最大法力值。该效果每3秒只能触发一次。" }, { "|s20196|", "使你使用单手近战武器造成的伤害提高6%。", "使你使用单手近战武器造成的伤害提高10%。" }, { "|s20177|", "使你在受到暴击之后有100%的几率获得一次额外攻击。", "使你在格挡一次近战攻击之后有40%的几率获得一次额外攻击，并在受到非周期性暴击之后有100%的几率获得一次额外攻击。" } } },
                    } },
                    { key = "beginner", flow = {
                        { t = "p", v = "防护圣骑士的操作难度并不算特别高，但你既要摸索坦克的基本门道，又要学会应对法力值方面的难题，过程中难免会遇到一些坎。" },
                        { t = "p", v = "防护圣骑士是较为容易上手的坦克之一，虽然有几处交互可能不太直观，但当你初入这个世界时，重点应放在学习不同圣印与|s20271|，并充分利用你的整套技能，尤其是诸如|s17143|,|s26573|，以及|s20925|(等你达到40级后)。在整个攻略过程中会包含大量优化建议，你可以在对游戏核心机制有一定了解后再去关注这些内容。" },
                    } },
                    { key = "systems", flow = {
                        { t = "p", v = "圣骑士作为坦克的独特之处在于使用法力值，而其他坦克则使用怒气作为资源。因此，圣骑士处于一种利弊参半的境地。" },
                        { t = "tb", v = { { "优势：圣骑士在战斗开始时绝不会缺资源，可以毫无资源压力地打出整套技能。", "", "劣势：在持久战中，圣骑士必须谨慎管理法力，以免资源枯竭，而且往往需要等待法力恢复后才能迎战新的敌人。" } } },
                        { t = "ul", v = { { text = "|s20357|- 每次攻击获得法力值。\n审判效果：攻击该目标的每名玩家每次攻击时获得少量法力值。" }, { text = "|s20349|- 每次攻击获得生命值。\n审判效果：攻击该目标的每名玩家每次攻击时获得少量生命值。" }, { text = "|s20308|- 提高攻击速度和攻击强度，但降低每次攻击的伤害。\n审判效果：受到的圣光伤害提高，影响队伍中的每名成员。" }, { text = "|s20164|- 偶尔使目标昏迷。\n审判效果：阻止目标在低血量时逃跑。" }, { text = "|s20453|- 每次挥砍造成伤害并获得吸收效果。\n审判效果：造成伤害并嘲讽目标。" }, { text = "|s20293|- 每次挥砍造成伤害\n审判效果：对目标造成伤害。" } } },
                        { t = "p", v = "此外，骑士还要管理圣印和圣印造成的减益，这对队伍/团队至关重要，并需要考虑如何管理圣印以平衡仇恨、法力值、治疗以及目标身上的减益。" },
                        { t = "p", v = "虽然某些圣印比其他更实用，但根据实际战况灵活切换圣印至关重要，同时还要与队友协调，确保目标身上有合适的审判效果。" },
                    } },
                    { key = "races", flow = {
                        { t = "p", v = "骑士在种族选择上不必纠结太多，因为只有2个联盟种族和1个部落种族可选。各种族能力的真正价值还有待观察，但无论选哪个都不会错。" },
                        { t = "races", v = { { race = "人类", side = "alliance", mark = "tick" }, { race = "矮人", side = "alliance", mark = "tick" } } },
                        { t = "p", v = "无限服新增的职业-种族组合" },
                        { t = "h4", v = "联盟" },
                        { t = "p", v = "人类骑士" },
                        { t = "p", v = "人类之所以能在早期《魔兽世界》中成为事实上的首选种族，是因为他们极为强力的武器专精加成。在《魔兽世界：无限》中，种族天赋已被重新设计，|s20597|现在改为对所有攻击和法术提供 2% 暴击几率。由于|s26573|等技能现在可以暴击，这项加成变得尤为强力。" },
                        { t = "p", v = "|s1259718|也已加入游戏，它能让你每 3 分钟解除一次昏迷效果。这在 PVP 中用途不言而喻，在 PVE 中同样有很高的实用价值。" },
                        { t = "p", v = "假设你能轻松获取剑类武器作为最佳装备，那么人类很可能是你的最优选择。" },
                        { t = "p", v = "矮人圣骑士" },
                        { t = "p", v = "矮人同样能通过种族天赋获得大量实用效果，例如通过|s1259719|获得 1% 的暴击加成，尽管其强度只有人类对应天赋的一半。" },
                        { t = "p", v = "为了弥补这部分强度差距，矮人拥有|s20594|，这一天赋在特定情况下非常强力，因为持续流血效果无法被驱散。" },
                        { t = "p", v = "此外，|s1259721|能对所有野兽造成 5% 的额外伤害。世界上存在数量惊人的野兽类敌人，这使得该天赋在练级阶段表现出色。在团队副本环境中通常野兽较少，但由于《魔兽世界：无限》将推出新的副本，我们无法对该天赋的完整价值做出评估。" },
                        { t = "p", v = "总的来说，矮人是很好的备选，特定场景下甚至优于人类。" },
                        { t = "h4", v = "部落" },
                        { t = "p", v = "亡灵圣骑士" },
                        { t = "p", v = "亡灵是圣骑士的新可选种族，而且作为部落目前唯一的选择，如果你想扛起那面猩红色的战旗，基本没什么其他可选的。" },
                        { t = "p", v = "幸运的是，亡灵种族获得了一些新的种族技能，对圣骑士来说价值颇高。当攻击敌人时，|s1260189|有 5% 的概率吸取目标生命值，最多为你最大生命值上限的 5%。目前该效果仅有 1 秒的内部冷却时间，因此触发相当频繁。不过具体哪些技能可以触发此效果，以及低伤害法术究竟能吸到多少，仍不明确。" },
                        { t = "p", v = "此外，亡灵还拥有|s7744|在 PvP 和 PvE 中都有很强的应用场景。|s20577|现在还会恢复法力值，对我们圣骑士来说是个好消息。" },
                    } },
                    { key = "prof", flow = {
                        { t = "p", v = "目前尚不清楚哪些专业对防护圣骑士收益最大。在整个经典怀旧服的每个资料片中，始终是最强的备选。圣骑士一直以来都面临一个问题：在距离较远时难以建立仇恨，而工程学制造的炸弹可以很好地解决这个问题。" },
                        { t = "p", v = "除工程学以外的所有专业都能通过属性获得专属加成。这些属性收益能否超过工程学的优势，仍有待观察。" },
                        { t = "p", v = "在资料片初期选 和 或 是一个比较稳妥的选择。" },
                    } },
                },
            },
            ret = {
                updated = "2026/09/21",
                sections = {
                    { key = "changes", flow = {
                        { t = "p", v = "此前，惩戒圣骑士曾是相当弱势的职业，缺乏职业特色，能为团队和队伍成员提供的支援也较为有限。《魔兽世界：无限》将通过引入焕然一新的天赋树、新法术与新技能，并对现有技能进行重制，使其更加强大且更具分量，力求解决这些问题。" },
                        { t = "p", v = "在所有新技能和新天赋中，最有趣且影响最大的当属神圣打击——我们的新瞬发攻击，造成神圣伤害——以及光明之旋，这是惩戒天赋树当前的终极天赋，使你可以通过在两个圣印之间来回切换，让同一次自动攻击同时享受两个圣印的加成。" },
                        { t = "tb", v = { { "|s10333|", "一项基于武器伤害和法术强度造成神圣伤害的新瞬发攻击，类似于十字军打击。这是全新的主力输出技能。" }, { "|s1310735|", "惩戒天赋树的新终极天赋；允许你在两个圣印之间“交替切换”，以同时享受两者对近战攻击的加成效果。当你切换圣印时，之前的圣印会变为一个“回响”，在你的下一次攻击中触发该圣印的效果。" }, { "|s20423|", "一项全新的防御向圣印，根据法术强度为近战攻击附加额外的神圣伤害。装备盾牌时，你还将获得一个吸收护盾，数值等于此圣印造成的神圣伤害的50%。审判此圣印会使目标被嘲讽4秒，并造成额外神圣伤害。" } } },
                        { t = "p", v = "除了新的天赋和技能之外，我们还对大量现有技能进行了调整，任何在经典魔兽中体验过惩戒的玩家都会对其中部分改动感到熟悉。在这些改动中，比较重要的内容包括抗性光环作用于团队成员，祝福持续1小时，并且审判使用时不再消耗你的圣印。" },
                        { t = "tb", v = { { "|s25290|", "现在持续1小时。" }, { "|s25291|", "现在持续1小时。" }, { "|s20217|", "现在持续1小时；现在通过训练习得，而非从防护天赋树中获得。" }, { "|s10310|", "使用时不再打断法力回复。" }, { "|s20924|", "现在对站在其中的前4个敌人造成额外伤害；现在通过训练习得，而非从神圣天赋树中获得。" }, { "|s10318|", "现在使其击中的亡灵和恶魔敌人昏迷2秒。" }, { "|s25780|", "现在使威胁值生成提高90%，而非60%。" }, { "|s19896|", "现在为所有团队成员提供抗性，而非仅小队成员。" }, { "|s19898|", "现在为所有团队成员提供抗性，而非仅小队成员。" }, { "|s19900|", "现在为所有团队成员提供抗性，而非仅小队成员。" }, { "|s20271|", "使用时不再消耗你的圣印。" } } },
                    } },
                    { key = "viability", flow = {
                        { t = "p", v = "《魔兽世界：无限》的目标之一是让每个职业和专精都有一席之地。虽然目前关于惩戒在满级时的表现我们掌握的信息不多，但可以做出一些合理推测。与经典怀旧服的其他许多分支类似，乍看之下，惩戒在PvE内容中将拥有中等的伤害输出能力，同时为团队和队伍成员提供强大的支援与功能增益，并且可以轻松以副专精或在紧急情况下担任坦克或治疗。" },
                        { t = "p", v = "在PvP内容中，惩戒很可能延续其爆发前置的输出定位，拥有中等的机动性和强大的支援与功能增益，但缺乏主要的伤害爆发技能。" },
                    } },
                    { key = "sw", flow = {
                        { t = "p", v = "惩戒圣骑士的主要定位是一名输出者，能在打出中等DPS的同时，用祝福、光环和功能法术支援团队——我们的优劣势也将围绕这一主要定位展开。遗憾的是，我们的主要职责并不是登顶伤害统计，因为我们缺乏能实现这一点的强力伤害爆发技能。" },
                        { t = "good", v = { "中等的单体伤害- 一名称职的输出者。", "扎实的群体伤害- 适合同时应对多个敌人。", "强大的功能与支援能力- 祝福、光环和功能法术是我们的核心优势。", "高机动性- 得益于清洁术和自由祝福。", "应急技能- 用圣疗术或保护祝福力挽狂澜，绝境翻盘。" } },
                        { t = "bad", v = { "无主要爆发技能- 目前缺少主要伤害爆发技能。", "法力值较少- 最大法力值非常有限，很容易耗尽。", "严重依赖装备- 目前非常依赖通过装备堆叠法术强度。", "治疗与坦克能力较弱- 若想有效地担任坦克或治疗角色，需要更换天赋。" } },
                    } },
                    { key = "beginner", flow = {
                        { t = "p", v = "与其它职业相比，高阶惩戒玩法会有中等复杂的输出循环，但对新手来说仍然比较容易上手和适应，尤其是在低级阶段。职业设计目前非常直白，学习门槛有限，即便是从未玩过的玩家也能轻松驾驭。总的来说，《魔兽世界：无限》中的惩戒玩法对新玩家相当友好，容易入门。" },
                        { t = "p", v = "圣骑士也是一个在辅助他人时最强的职业，能让新手为队友提供诸多强力增益，例如驱散或祝福，队友们会对此非常受用。" },
                    } },
                    { key = "systems", flow = {
                        { t = "p", v = "《魔兽世界：无限》中惩戒圣骑士的核心职业体系是终极天赋：|s1310735|因此，我会用一小节来解释它的运作方式。无需担心，其实相当简单。" },
                        { t = "p", v = "该|s1310735|机制是其他《魔兽世界》经典旧世版本中“圣印切换”的简化版，能让你在一次普通攻击中享受多重圣印的效果。由于圣印是为近战附加伤害的技能，这个终极天赋允许你切换到新的圣印时，仍然通过这个“回响”机制保留上一个圣印的增益——你的下一次近战攻击将同时受益于新施放的圣印以及上一个圣印的“回响”，相当于让一次攻击同时拥有两个圣印的效果。" },
                        { t = "p", v = "根据目前的理解，这将成为高等级惩戒玩法背后的核心机制。与其他版本的“圣印切换”相比，它要简单得多，但不再具有挥砍节奏或时机把控的要素，因此玩家对此看法不一。好在暴雪已在基础界面中加入了挥砍计时器，以便更好地支持这种玩法。我们希望尽快开始测试该天赋，并在之后带来更多消息。" },
                    } },
                    { key = "races", flow = {
                        { t = "p", v = "下面是我们首次整理出的职业与种族搭配，以及对应的种族特长。" },
                        { t = "races", v = { { race = "人类", side = "alliance", mark = "tick" }, { race = "矮人", side = "alliance", mark = "tick" } } },
                        { t = "ul", v = { { text = "|s1259718|- 立即解除所有昏迷效果。" }, { text = "|s20600|- 大幅提升潜行侦测能力，持续20秒。" }, { text = "|s20597|- 使用剑类武器时，所有法术和攻击的暴击几率提高2%。" }, { text = "|s20598|- 精神提高5%。" }, { text = "|s20594|- 移除并免疫所有流血、中毒和疾病效果，并使承受的伤害降低10%，持续8秒。" }, { text = "|s2481|- 在小地图上感知附近的宝箱位置。" }, { text = "|s1259719|- 使用锤类武器时，所有法术和攻击的暴击几率提高1%。" }, { text = "|s1259721|- 对野兽造成的伤害提高 5%。" }, { text = "|s1260189|- 有 5% 的几率从敌人目标身上偷取生命值，偷取量最多为你最大生命值的 5%。" }, { text = "|s5227|- 在水下呼吸的时间延长至原来的 300%。" }, { text = "|s20577|- 通过吞噬倒下的敌人尸体来回复生命值。" }, { text = "|s7744|- 立刻解除自身受到的魅惑、恐惧或睡眠效果。" } } },
                        { t = "p", v = "无限服新增的职业-种族组合" },
                        { t = "h4", v = "联盟" },
                        { t = "p", v = "对于联盟来说，你有两种选择人类和矮人。个人建议坚持选择人类由于其种族特长过于强大，例如解除昏迷效果以及额外的1%暴击几率。" },
                        { t = "p", v = "人类种族特长：" },
                        { t = "p", v = "矮人种族特长：" },
                        { t = "h4", v = "部落" },
                        { t = "p", v = "部落圣骑士的唯一选择是亡灵。" },
                        { t = "p", v = "亡灵种族特长：" },
                    } },
                    { key = "prof", flow = {
                        { t = "p", v = "虽然我们仍在调查和收集信息，但目前的共识似乎是采矿和锻造是当前惩戒圣骑士的强力副业选择。" },
                    } },
                },
            },
        },
        HUNTER = {
            bm = {
                updated = "2026/09/25",
                sections = {
                    { key = "changes", flow = {
                        { t = "p", v = "在《魔兽世界：无限》中，暴雪对兽王猎人的改动并不大。几个天赋被合并为一个，我们还获得了一个新版本的技能，也就是之前正式服中大家熟知的“群鸦盛宴”：|s1293241|这些鹰隼算是某种“伪”第二宠物，因为其他几个天赋也能提高它们的伤害。不过，兽王猎人最重要的改动还是体现在宠物方面。宠物现在会受益于猎人的部分属性，虽然相比其他版本的《魔兽世界》稍弱一些。部分宠物种类还获得了新技能，让更多宠物变得可用。" },
                        { t = "tb", v = { { "|s1293241|- 天赋", "命令一只鹰隼俯冲轰炸你指定的敌人，造成物理伤害并持续攻击18秒。同时只能有2只鹰隼处于激活状态。召唤鹰隼与奥术射击共享冷却时间。冷却时间6秒。" }, { "|s1223755|- 天赋", "你的宠物处于激活状态时，你和你宠物造成的所有伤害提高2%。" } } },
                        { t = "p", v = "一个非常重要的改动似乎是移除了0.5秒的施法时间，涉及|s75|，此外还有其他改进。这会让猎人成为更强大的风筝高手。" },
                        { t = "tb", v = { { "|s75|", "自动射击目标，直到取消。现在没有隐藏的0.5秒施法时间，并且可以在施放其他技能期间持续进行。这让你只要武器就绪并且停止移动，就能立刻射击。" }, { "|s20904|- 技能", "一次瞄准射击，使远程伤害提高166。瞄准射击与多重射击共享冷却时间。重要的新内容是它与|s2643|共享冷却时间。它现在也是基础技能，而非天赋。" }, { "|s2643|- 技能", "发射多枚导弹，命中3个目标。多重射击与瞄准射击共享冷却时间。似乎不再有额外等级来提升伤害。" }, { "|s19583|- 天赋", "使你的宠物生命值和护甲提高15%。" }, { "|s19549|- 天赋", "使你的猴子守护提供的闪避加成提高6%。此外，你的宠物获得你的猴子守护技能50%的效果。" }, { "|s19577|- 天赋", "命令你的宠物在下次成功攻击时击昏目标3秒，该次攻击的暴击几率提高100%。产生大量威胁值。" }, { "|s19590|- 天赋", "使你的宠物集中值回复速度提高20%，并允许施法时保留50%的法力值回复。" } } },
                    } },
                    { key = "viability", flow = {
                        { t = "p", v = "《魔兽世界：无限》的目标之一是让每个职业和专精都具备可玩性。对于兽王猎人而言，他们在无限服中是否达到了这一标准值得商榷。兽王猎人无法为团队提供任何增益，最多只能通过高岭陆行鸟的新技能提供一些护甲削减|s1265904|. 唯一的亮点在于拥有（极高的）基础伤害,只要能冲上伤害榜首就足以让你在团队中占有一席之地。" },
                        { t = "p", v = "在 PvP 中,兽王猎人有一定的潜力,前提是我们的宠物不会一受到伤害就倒下。移除|s75|的施法时间在 PvP 场景中非常强力,但很难成功施放出一次|s20904|。部分宠物系获得了一些强力的 PvP 技能。双倍|s1293241|搭配一只|s19574|强化后的宠物,可以构成非常致命的爆发连击。" },
                    } },
                    { key = "sw", flow = {
                        { t = "good", v = { "高爆发- 兽王猎人在其|s19574|爆发窗口期间应当具备较高的爆发伤害。", "强大的风筝能力- 无论是在 PvE 还是 PvP 场景中,只要目标没有远程控制或突进技能,你都可以轻松风筝小怪或玩家。", "拥有功能的宠物随着新宠物技能的加入，让所有宠物都有机会大放异彩，猎人能够根据当时的需求灵活调整。|s1265904|在PvE中很强，|s1264933|在PvP中能压制治疗，|s1265058|在盗贼偷袭你时能反制他们，等等。" } },
                        { t = "bad", v = { "无团队辅助能力- 猎人目前无法为小队或团队提供任何有用的增益。这使得你在竞争环境中只能依靠高基础伤害来获得位置。", "盲区- 任何进入你8码范围内的怪物或玩家都无法被你的远程伤害技能命中。由于兽王猎人仍然偏好远程射击，这会对你造成不利影响。" } },
                    } },
                    { key = "beginner", flow = {
                        { t = "p", v = "猎人上手简单，适合任何玩家，而在《魔兽世界：无限》的三个专精中，兽王大概率是最容易上手的。但这并不意味着兽王完全不需要思考。正确地保持两层|s1293241|持续刷新且不过早重新施加，是成为优秀兽王猎人的关键。猎人的一大乐趣在于其极高的操作上限，尤其是在单人内容和PvP中。如果你足够熟练地掌握穿插近战（即进出近战范围使用近战技能的操作），你会发现总伤害有所提升。对陷阱和钉刺的良好控制会让你在PvP中很强。最后，良好的宠物和环境控制让你在单人内容中非常强大，使你能够单刷其他职业无法单刷的内容。这对猎人的三个专精都适用。" },
                    } },
                    { key = "systems", flow = {
                        { t = "h4", v = "子弹与箭矢" },
                        { t = "p", v = "目前，弹药系统似乎没有明显改动。你仍然需要箭袋来装箭矢，或用弹药袋来装子弹。这意味着我们仍然比大多数其他职业少一个背包。" },
                        { t = "h4", v = "宠物" },
                        { t = "ul", v = { { text = "耐力：玩家每 1 点耐力为宠物提供 2 点生命值" }, { text = "护甲：宠物获得玩家护甲值的 30%" }, { text = "攻击强度：宠物获得玩家最高攻击强度来源的 10%" }, { text = "暴击：宠物获得玩家暴击率的 100%" } } },
                        { t = "p", v = "宠物在《魔兽世界：无限》中获得了一些显著改动。所有的宠物类型现在都拥有至少一个独特技能，其中一些在 PvE 场景中非常实用，另一些则更适合 PvP。猎人宠物的属性还会按比例受到玩家属性的影响，具体如下：" },
                        { t = "p", v = "所有这些信息同样在角色界面的宠物面板中展示并说明。宠物现在也拥有闪避属性，并且不再能被其他职业的增益效果加成。" },
                    } },
                    { key = "races", flow = {
                        { t = "p", v = "各个种族在种族特长方面进行了大量改动，旨在让所有种族同样强力。目前来看，一些种族整体表现更优，而另一些则可能在某一特定玩法中大放异彩。在《魔兽世界：无限》中，人类现在也可以选择猎人，同时新增了天裔这一可选种族。" },
                        { t = "races", v = { { race = "矮人", side = "alliance", mark = "tick" }, { race = "暗夜精灵", side = "alliance", mark = "tick" }, { race = "兽人", side = "horde", mark = "tick" }, { race = "牛头人", side = "horde", mark = "tick" }, { race = "巨魔", side = "horde", mark = "tick" } } },
                        { t = "p", v = "无限服新增的职业-种族组合" },
                        { t = "p", v = "天裔只要队伍里有元素法系存在，天裔凭借其种族被动技能|s1259707|几乎稳居榜首。虽然暴雪试图让所有种族的种族能力都具有竞争力，但他们并没有取消针对特定怪物类型的种族特长。另一个能显著提升你 DPS 的种族被动是|s1259710|。在经典服中急速属性十分稀有，因此这可能比你想象的更强。" },
                        { t = "h4", v = "联盟" },
                        { t = "p", v = "暗夜精灵 暗夜精灵可能是猎人最强的联盟种族，因为他们拥有全新的主动技能|s1259799|。该技能冷却时间为3分钟，但若与|s3045|和/或|s19574|搭配使用，你的伤害会在短时间内大幅提升。战斗时间越短，该技能的效果越显著。注意，由于全新的宠物继承规则，在此期间你的宠物还会额外获得10%的暴击几率。" },
                        { t = "p", v = "矮人" },
                        { t = "p", v = "目前，矮人在PvE场合唯一的收益是|s1259721|，而且仅在你与野兽作战时才有效。|s20594|则是相当不错的PvP种族特长，所以如果你想成为盗贼的克星，不妨选择矮人。" },
                        { t = "p", v = "人类" },
                        { t = "p", v = "目前，人类对远程猎人几乎没有助益，因为|s20597|只对你的近战攻击和技能生效。不过宠物依然能获得暴击提升，因为它们会复制猎人的近战和法术暴击几率。这也确实意味着人类能为使用剑的生存猎人提供不错的增益。而在PvP中，人类则拥有一个强力技能：|s1259718|其作用基本上和大家熟悉的PvP饰品相同。" },
                        { t = "h4", v = "部落" },
                        { t = "p", v = "兽人" },
                        { t = "p", v = "兽人大概无论PvE还是PvP都远是部落最好的种族。|s20572|提供强力的攻击强度加成，同时也能小幅强化你的宠物。它现在是瞬发，并且冷却时间只有2分钟，而大多数其他种族特长的冷却时间都是3分钟。生存猎人可以额外获得|s20574|装备斧时的加成。在PvP中，你还有|s20573|来降低昏迷的效果，以及|s1299026|来反制任何施法者（尤其是术士）。" },
                        { t = "p", v = "巨魔" },
                        { t = "p", v = "和矮人一样，巨魔通过种族被动获得对野兽的额外伤害|s20557|。不过巨魔确实有一个非常强力的PvE主动技能，那就是|s20554|。该技能不再根据已损失生命值提升效果，因此比经典旧世时更弱，但仍然提供相当不错的攻击速度加成。" },
                        { t = "p", v = "牛头人" },
                        { t = "p", v = "牛头人猎人可以获得额外的 1% 命中率加成，来源是|s20550|。在后期命中难以达标的情况下，这一加成非常强力；而额外的生命值在开荒期团本中也相当有用。|s1259918|会与|s5118|产生竞争，但使用它可以在不切猎豹的情况下风筝某些怪物，从而在使用雄鹰守护时打出更高伤害。|s20549|依然是非常强力的群体昏迷技能，无论在 PvP 还是 PvE 中都很好用。" },
                    } },
                    { key = "prof", flow = {
                        { t = "p", v = "制皮 随着制皮的改动与新增内容，这项专业看起来已成为猎人的必备专业。许多配方被改动或新增，制作的装备为拾取绑定。这些装备在对应等级往往非常强力。如果当前已知的专业内容在满级时保持不变，那么学习制皮几乎是必选。" },
                        { t = "p", v = "工程学 工程学让猎人获取到非常强力的装备，尤其是枪械与头部附魔道具，还有强力的消耗品，例如各种手雷和地雷。目前还不清楚该专业在后续阶段的完整内容，但如果加入类似工程附件的额外内容，也不会令人意外。" },
                    } },
                },
            },
            mm = {
                updated = "2026/09/25",
                sections = {
                    { key = "changes", flow = {
                        { t = "p", v = "在《魔兽世界：无限》中，暴雪正在强化射击猎人的设定，使其成为孤身作战的弓箭手（或枪手），使用高伤害的远程技能进行射击，就像我们当前在正式服看到的那样。随着|s415370|加入天赋树，你很可能在副本或团队副本中不会使用宠物。" },
                        { t = "tb", v = { { "|s1310687|- 天赋", "一次稳定的狙击，使远程伤害提高160点。施法时间为4(!)秒，冷却时间为15秒。它是射击天赋树的终极天赋。" }, { "|s415370|- 天赋", "当你没有激活的宠物时，所有攻击造成的伤害提高20%。" }, { "|s1223987|- 天赋", "用毒蛇钉刺击中目标可使你在接下来的15秒内施法时获得50%的法力值回复，消耗急速杀戮则可获得100%的法力值回复。开发者为几乎所有天赋和职业提供了法力值回复天赋，因此可以减少战斗中的空档期。" }, { "|s1223984|- 天赋", "攻击强度提高智力的100%。这个天赋可能会带来一些有趣的装备属性搭配选择。" }, { "|s1310661|- 天赋", "毒蛇钉刺的伤害提高20%，蝰蛇钉刺的冷却时间缩短6秒，蝎毒钉刺的持续时间延长45秒。" } } },
                        { t = "p", v = "一个非常重要的改动似乎是移除了|s75|的0.5秒施法时间，以及其他改进。这会让猎人的风筝能力更加强大。" },
                        { t = "tb", v = { { "|s75|", "自动射击目标直至取消。现在没有隐藏的0.5秒施法时间，并且可以在施放其他技能期间继续射击。这让你在武器就绪且停止移动时可以立即射击。" }, { "|s20904|- 技能", "一个瞄准射击，使远程伤害提高166。瞄准射击与多重射击共享冷却时间。重要的新改动是与|s2643|共享冷却时间。它现在也是基础技能，而非天赋。" }, { "|s2643|- 技能", "发射数枚导弹，命中3个目标。多重射击与瞄准射击共享冷却时间。似乎不再有额外等级，伤害提高。" }, { "|s20906|- 天赋", "使45码内小队成员的远程攻击强度提高50。持续30分钟。不再显著提高近战攻击强度，并且被大幅削弱。" }, { "|s24293|- 天赋", "在追踪野兽、恶魔、龙类、元素生物、巨人、人型生物或亡灵时，你对所追踪生物类型造成的所有伤害提高5%。" } } },
                    } },
                    { key = "viability", flow = {
                        { t = "p", v = "《魔兽世界：无限》的目标之一是让每个职业和专精都可行。对于射击猎人来说，他们在无限服中是否达到了这个标准值得怀疑。移除了近战攻击强度后，|s20906|显著降低了在物理伤害队伍中拥有猎人的实用性。再加上（很可能）缺少能提供任何有用减益效果的宠物，射击猎人将无法为任何队伍或团队提供显著的增益。其弥补因素将是（极其）高的基础伤害。" },
                        { t = "p", v = "在PvP中，射击猎人是否能够表现出色也仍然值得怀疑。移除了|s75|的施法时间在PvP场景中非常强大，但很难施放任何|s20904|或|s1310687|。不过，如果无人关注且被放任不管，射击猎人将极其致命。" },
                    } },
                    { key = "sw", flow = {
                        { t = "good", v = { "高爆发- 射击猎人在长施法时间技能下能打出高爆发。特别是配合|s1310687|。", "强大的风筝能力- 无论是在PvE还是PvP场景中，只要目标没有远程控制或突进技能，你就可以轻松地风筝怪物或玩家。" } },
                        { t = "bad", v = { "没有团队增益- 缺少|s20906|上的近战攻击强度加成，以及没有宠物，会让你不受欢迎，除非你能提供足够高的伤害。", "近战盲区- 任何进入你8码范围内的怪物或玩家都无法被你的远程伤害技能命中。作为射击猎人，这一点尤其致命。" } },
                    } },
                    { key = "beginner", flow = {
                        { t = "p", v = "猎人是任何玩家都能轻松上手的职业，但在《魔兽世界：无限》中，射击很可能是三个专精中最难操作的。这并不意味着射击是一个非常难的专精，至少在团队内容中不是。猎人的乐趣在于上限很高，尤其是在单人和PvP中。如果你足够熟练地掌握走位（在近战范围内来回移动以使用近战技能），你会发现自己的总伤害会提高。良好的陷阱和钉刺控制能力会让你在PvP中更加强大。最后，良好的宠物和环境控制能力让你在单人内容中非常强力，并允许你完成其他职业无法完成的单刷内容。三个猎人专精都适用这一点。" },
                    } },
                    { key = "systems", flow = {
                        { t = "h4", v = "弹药" },
                        { t = "p", v = "目前，弹药系统似乎没有重大改动。你仍然会使用箭袋装箭矢或弹药袋装子弹。这意味着我们仍然比其他大多数职业少一个背包格。" },
                        { t = "h4", v = "宠物" },
                        { t = "ul", v = { { text = "耐力：每1点玩家耐力为宠物提供2点生命值" }, { text = "护甲：宠物获得玩家护甲的30%" }, { text = "攻击强度：宠物获得玩家最高攻击强度来源的10%" }, { text = "暴击：宠物获得玩家暴击几率的100%" } } },
                        { t = "p", v = "宠物在《魔兽世界：无限》中经历了一些显著改动。现在所有宠物种类都至少拥有一个独特技能，有些在PvE场合非常实用，有些则在PvP中表现出色。猎人宠物现在也会随我们的属性成长，具体如下：" },
                        { t = "p", v = "所有这些信息也会在角色界面的宠物面板中显示和说明。宠物现在还将拥有规避。它们不再能受到其他职业增益的加成。" },
                    } },
                    { key = "races", flow = {
                        { t = "p", v = "各族的种族特长都经历了大量改动，力求让它们同样优秀。目前来看，有些整体上更强，而另一些可能在特定的玩法中更为出色。在《魔兽世界：无限》中，人类现在可以成为猎人，同时还有新加入的天裔。" },
                        { t = "races", v = { { race = "矮人", side = "alliance", mark = "tick" }, { race = "暗夜精灵", side = "alliance", mark = "tick" }, { race = "兽人", side = "horde", mark = "tick" }, { race = "牛头人", side = "horde", mark = "tick" }, { race = "巨魔", side = "horde", mark = "tick" } } },
                        { t = "p", v = "无限服新增的职业-种族组合" },
                        { t = "p", v = "天裔只要有元素存在，天裔必定凭借其|s1259707|种族被动占据榜首。虽然暴雪曾试图让所有种族都拥有具竞争力的种族特长，但他们并未摆脱针对特定怪物类型的那些。另一个能显著提升你DPS的种族被动是|s1259710|。急速在经典旧世中尤为难得，所以这可能比你想象的更强。" },
                        { t = "h4", v = "联盟" },
                        { t = "p", v = "暗夜精灵 暗夜精灵或许是联盟中最强的猎人种族，这得益于他们的新主动技能|s1259799|。该技能冷却时间为3分钟，但与|s3045|和/或|s19574|配合使用时，能在短时间内大幅提升你的伤害。战斗越短，该技能的影响就越显著。需要注意的是，由于新的宠物继承机制，你的宠物在此期间也会获得10%的额外暴击率。" },
                        { t = "p", v = "矮人" },
                        { t = "p", v = "目前，矮人在PvE场景下唯一的优势在于|s1259721|，且仅在对抗野兽时有效果。|s20594|是一个不错的PvP种族技能，所以如果你想成为盗贼的克星，可以考虑选择矮人。" },
                        { t = "p", v = "人类" },
                        { t = "p", v = "人类当前对远程猎人几乎没有增益，因为|s20597|只作用于你的近战攻击和技能。不过宠物仍会获得暴击加成，因为它们继承猎人的近战和法术暴击率。这也意味着人类能为使用剑的生存猎人提供不错的增益。而在PvP中，人类则拥有一个强力技能|s1259718|，其效果与大家熟悉的PvP饰品基本相同。" },
                        { t = "h4", v = "部落" },
                        { t = "p", v = "兽人" },
                        { t = "p", v = "兽人可能是无论PVP（还是PvE）中最好的部落种族。|s20572|提供强力的攻击强度加成，这反过来也会略微增强你的宠物。它现在是瞬发技能，冷却时间只有2分钟，而大多数其他种族特长的冷却时间是3分钟。生存猎人会获得额外的加成，|s20574|，当装备斧类武器时。并且在PvP中，你拥有|s20573|来降低昏迷效果，以及|s1299026|来对抗任何施法者（特别是术士）。" },
                        { t = "p", v = "巨魔" },
                        { t = "p", v = "就像矮人一样，巨魔通过其种族被动技能对野兽造成额外伤害，|s20557|。不过，巨魔在PvE中确实拥有一个非常强力的主动技能，形式为|s20554|。该技能不再根据缺失的生命值缩放，因此在经典版本中效果较弱，但仍能提供可观的攻击速度加成。" },
                        { t = "p", v = "牛头人" },
                        { t = "p", v = "牛头人猎人可以通过以下种族特长获得额外的 1% 命中|s20550|。如果后期内容中命中属性较难获取，这会显得非常强力；而额外的生命值在开荒团队副本时也相当实用。|s1259918|确实会与以下技能产生竞争|s5118|，但它能让你在某些怪物战中保持风筝走位而不必切换猎豹守护，从而通过雄鹰守护打出更高的伤害。|s20549|仍然是一个极强的群体昏迷技能，无论在 PvP 还是 PvE 中都表现强劲。" },
                    } },
                    { key = "prof", flow = {
                        { t = "p", v = "制皮 随着制皮专业的改动与新增，该专业已成为猎人的必备选择。许多配方经过调整或新增，使所制造的装备变为拾取绑定。这些装备通常在你可装备的等级下非常强力。如果该专业目前已知的内容一路持续到满级都保持不变，那么学习制皮几乎是显而易见的选择。" },
                        { t = "p", v = "工程学 工程学为猎人提供了非常强力的装备，包括枪械和头部附魔物品，以及各种手雷和地雷等强力消耗品。目前尚不清楚该专业在更高阶段会如何发展，但如果加入类似工程学附件的内容也毫不令人意外。" },
                        { t = "p", v = "专业总览指南" },
                    } },
                },
            },
            surv = {
                updated = "2026/09/27",
                sections = {
                    { key = "changes", flow = {
                        { t = "p", v = "在《魔兽世界：无限》中，生存专精的身份被重新定位——从以干扰为主，转型为结合近战技能与陷阱的近战专精。几个天赋被合并为一个，天赋树后半段也加入了一大批以近战为导向的天赋。另一项可能影响生存猎人的重要改动来自宠物系统。宠物现在会按猎人部分属性的一定比例获得强化（比《魔兽世界》其他版本略弱）。部分宠物种类还获得了新技能，使更多宠物变得可用。" },
                        { t = "tb", v = { { "|s1317257|- 天赋", "一个简单的近战\\\"踢击\\\"技能，造成等同于你近战伤害100%的伤害，并使你的移动速度提高3秒。冷却时间8秒。无法打断目标。" }, { "|s1310627|- 天赋", "使你的近战暴击伤害提高30%，副手武器伤害提高50%。相比其他双持职业，这个副手伤害加成看起来非常强力。" }, { "|s1310532|- 天赋", "你对带有猎人印记的目标攻击时，有10%的几率触发5秒的猫鼬撕咬。这是让|s14271|可以在输出循环里使用而无需躲避的关键。" }, { "|s440529|- 天赋", "该天赋使你的陷阱和近战技能的法力值消耗降低60%，且暴击有一定几率使你的法力值回复提高30秒。这基本上是维持法力值的主要天赋。" }, { "|s1310496|- 天赋", "使你的陷阱和威慑技能的冷却时间缩短40%。简单有效，因为陷阱的冷却时间在《无限》中被提升至30秒的基础水平。" }, { "|s1310533|- 天赋", "生存的新终极天赋。使你的|s14271|（对目标）造成持续较长时间的流血伤害。" } } },
                        { t = "tb", v = { { "|s14271|- 技能", "对敌人造成近战武器伤害加固定数值。仅在躲闪后才可使用，除非获得|s1310532|。伤害不再是一个固定数值，而是使用武器伤害。" }, { "|s24293|- 天赋", "怪物追踪和人形生物追踪合并为一个天赋。满级时对被追踪生物类型造成的所有伤害提高5%。现在对猎人的所有追踪技能都生效。" }, { "|s19184|- 天赋", "现在陷阱触发时总会定身所有受影响的目标，满级时定身时间最长为5秒。" }, { "|s19376|- 天赋", "经典版中的陷阱命中率和假死命中率天赋合并为一个。" }, { "|s19306|- 天赋", "在招架对手攻击后激活的一击。现在会随着武器伤害而变化，而不是造成固定数值的伤害。" } } },
                    } },
                    { key = "viability", flow = {
                        { t = "p", v = "《魔兽世界：无限》的一个目标是让每个职业和每个天赋都能登场。生存猎或许已经达到了这一点，只要它的伤害能冲上榜首，因为生存猎不会给团队提供任何增益，最多只能通过高鸟的新能力提供一些破甲效果|s1265904|或是已经被其他职业提供的其他增益/减益效果。" },
                        { t = "p", v = "在PvP中，生存猎或许有一定的潜力，只要我们的宠物不会一碰就倒。有几个宠物家族获得了一些强力的PvP技能。|s1317257|是一个对技能组合很好的补充，尤其是它的移速加成效果，而且一些以陷阱为核心的天命也变得更强了。" },
                    } },
                    { key = "sw", flow = {
                        { t = "good", v = { "强大的持续伤害- 生存猎应该拥有强大的持续伤害，因为他们几乎可以一直按键。在经典版魔兽中没有任何空窗期是非常强力的。", "强大的风筝能力无论在 PvE 还是 PvP 场景中，只要目标没有远程控制或突进技能，你都可以轻松地风筝怪物或玩家。", "宠物的功能性随着新宠物技能的加入，所有宠物都有发挥的空间，猎人可以根据当前需要灵活应对。|s1265904|在 PvE 中表现出色，|s1264933|在 PvP 中压制治疗，|s1265058|在盗贼先手时反制他们，等等。" } },
                        { t = "bad", v = { "没有团队增益猎人当前无法为队伍或团队提供任何有用的增益。在竞争激烈的环境中，你只能凭借高额的基础伤害才能被选中。", "装备竞争你需要与战士、盗贼甚至圣骑士争夺武器。" } },
                    } },
                    { key = "beginner", flow = {
                        { t = "p", v = "猎人对任何玩家来说都容易上手，在《魔兽世界：无限》中生存专精也不例外，不过由于天赋要求，该专精要等到大约 32 级左右才会真正发光发热。你几乎总会按键可按，只是偶尔需要选择先按哪一个。作为生存猎人，你可以选择带宠物或不带宠物。猎人的乐趣在于其上限很高，尤其是在单人和 PvP 内容中。如果你能够熟练运用远程和近战技能的全部组合，你会变得非常难以对付。良好的陷阱和钉刺控制会让你在 PvP 中变强。最后，优秀的宠物和场地控制能力会让你在单人内容中非常强力，能够单刷其他职业无法单刷的内容。三个猎人专精都是如此。" },
                    } },
                    { key = "systems", flow = {
                        { t = "h4", v = "弹药与箭矢" },
                        { t = "p", v = "目前弹药系统似乎没有重大改动，你仍然需要使用箭袋来装箭矢，或者使用弹药袋来装子弹。这意味着我们的背包数量依然比其他职业少一个。" },
                        { t = "h4", v = "宠物" },
                        { t = "ul", v = { { text = "耐力：玩家每 1 点耐力为宠物提供 2 点生命值" }, { text = "护甲：宠物获得玩家护甲值的 30%" }, { text = "攻击强度：宠物获得玩家最高攻击强度来源的 10%" }, { text = "暴击：宠物获得玩家暴击率的 100%" } } },
                        { t = "p", v = "宠物在《魔兽世界：无限》中获得了值得注意的改动。如今所有宠物种类都至少拥有一个独特技能，其中一些在 PvE 场景中非常实用，另一些则在 PvP 中大放异彩。猎人宠物现在也会随我们的属性成长，具体如下：" },
                        { t = "p", v = "所有这些信息也可以在角色界面的宠物面板中查看和了解。宠物现在还会拥有闪避属性，并且无法再享受其他职业的增益效果。" },
                    } },
                    { key = "races", flow = {
                        { t = "p", v = "为了让所有种族特长都同样出色，各种族的种族特长都经历了不少改动。就目前而言，有些种族总体上似乎更强，而另一些则可能在某种特定玩法中大放异彩。在《魔兽世界：无限》中，人类现在可以成为猎人，还可以选择新增的天裔种族。" },
                        { t = "races", v = { { race = "矮人", side = "alliance", mark = "tick" }, { race = "暗夜精灵", side = "alliance", mark = "tick" }, { race = "兽人", side = "horde", mark = "tick" }, { race = "牛头人", side = "horde", mark = "tick" }, { race = "巨魔", side = "horde", mark = "tick" } } },
                        { t = "p", v = "无限服新增的职业-种族组合" },
                        { t = "p", v = "|s1259707|天裔如果战斗中存在任何元素生物，天裔的种族天赋必定能让他们占据榜首位置。虽然暴雪试图让所有种族的种族天赋具备竞争力，但他们仍未放弃针对特定怪物类型的专属加成。另一个能为你的 DPS 提供可观加成的，是|s1259710|. 急速在经典服中非常稀有，因此这个效果可能比你想象中更强。" },
                        { t = "h4", v = "联盟" },
                        { t = "p", v = "暗夜精灵 暗夜精灵可能是猎人最强的联盟种族，原因在于他们新增的主动技能|s1259799|。该技能冷却时间为3分钟，但当它与|s3045|和/或|s19574|搭配使用时，你的伤害会临时获得巨大提升。战斗时间越短，这一技能的影响就越大。需要注意的是，在此期间你的宠物也会因新的宠物属性继承规则获得额外的10%暴击率。" },
                        { t = "p", v = "人类" },
                        { t = "p", v = "人类为使用剑的生存猎人提供了不错的增益，同时也会提升你的宠物暴击率。在PvP中，人类获得了强力技能|s1259718|，其效果基本与大家熟悉的PvP饰品相同。" },
                        { t = "p", v = "矮人" },
                        { t = "p", v = "目前，矮人在PvE场景中唯一的好处就是|s1259721|，而且这仅在面对野兽类型敌人时才会生效。|s20594|是一个不错的PvP种族技能,所以如果你想成为盗贼的克星,可以选择矮人。" },
                        { t = "h4", v = "部落" },
                        { t = "p", v = "兽人" },
                        { t = "p", v = "兽人可能是部落在PvE和PvP中最强的种族。|s20572|能提供强力的攻击强度加成,这也会略微增强你的宠物。它现在是瞬发技能,冷却时间也仅为2分钟,而大多数其他种族技能的冷却时间为3分钟。生存猎人在使用|s20574|时还能获得斧专精加成。而在PvP中,你拥有|s20573|以降低昏迷效果|s1299026|来应对那些施法者(尤其是术士)。" },
                        { t = "p", v = "巨魔" },
                        { t = "p", v = "和矮人一样,巨魔通过种族被动技能|s20557|对野兽造成额外伤害。不过巨魔在PvE中拥有一个非常强力的主动技能,也就是|s20554|。该技能不再根据已损失生命值提升威力,比经典旧世版本更弱,但仍然能提供不错的攻击速度加成。" },
                        { t = "p", v = "牛头人" },
                        { t = "p", v = "牛头人猎人可以通过种族特长获得额外的 1% 命中|s20550|。在后期命中难以堆叠时，这个加成非常强力，额外的生命值在开荒团本中也很有用。|s1259918|确实会与之竞争|s5118|，但它能让你在不开猎豹的情况下风筝部分怪物，从而在使用雄鹰守护时提高伤害。|s20549|仍然是非常强力的群体昏迷技能，无论是 PvP 还是 PvE 都很好用。" },
                    } },
                    { key = "prof", flow = {
                        { t = "p", v = "制皮 随着制皮的改动与新增内容，这项专业看起来已经成为猎人的标配。许多配方被改动或新增，制作的装备变为拾取绑定。这些部件通常在你可装备的等级就已经非常强力。如果目前已知的关于该专业的内容在满级之前都保持不变的话，学习制皮是理所当然的选择。" },
                        { t = "p", v = "工程学 工程学让猎人能用到非常强力的装备，例如枪械和头部附魔，以及强力的消耗品，例如手雷和地雷。虽然目前还不清楚该专业在更高阶段会带来什么，但如果后续加入类似附魔宝石之类的内容，也不会令人意外。" },
                    } },
                },
            },
        },
        ROGUE = {
            assa = {
                updated = "2026/10/05",
                sections = {
                    { key = "changes", flow = {
                        { t = "p", v = "从标准经典旧世到《魔兽世界：无限》，盗贼迎来了大量改动，有的影响巨大，有的只是小幅微调。其中影响最大的两处是：毒药现在随攻击强度成长，以及能量改用了巫妖王之怒及之后版本的平滑回复机制，取代了旧版按跳回复的模式。此外值得一提的还有，毒药现在可以与风怒图腾以及磨刀石叠加生效。" },
                        { t = "p", v = "奇袭盗贼获得了一些亮眼的新技能，比如|s1329|和|s1310703|。我们从毒药的改动中获益最多，而我们的天赋也在方方面面利用并强化毒药。" },
                        { t = "tb", v = { { "|s1329|", "毁伤已加入天赋树，为我们提供了一个专属于本专精的出色连击点生成技能。该技能对已中毒目标的伤害提高20%，进一步深化了专精的主题设定，也促使你至少在一把武器上涂毒。待测试版等级上限提升到30级、我们能真正开始测试后，将补充更多信息。" }, { "|s1310703|", "我们的新终结技，可将毒药伤害提高30%，并将毒药的施加几率提高10%。不得不承认，它算不上最令人兴奋的技能，因为它实际上相当于第二个|s5171|需要去维持。它确实缺少了游戏后续版本中的伤害成分。" } } },
                        { t = "p", v = "奇袭天赋树对现有技能做出了一批改动，主要围绕提升我们的毒药输出，同时强化主要连击点生成技能的伤害。" },
                        { t = "tb", v = { { "|s14138|", "现在还会提高你的毒药暴击几率。" }, { "|s14144|", "该天赋的收益现在也延伸到了毁伤。" }, { "|s14158|", "现在每点天赋提供2%的伤害加成，由1%上调。不再对野兽和龙人生效。" }, { "|s14128|", "收益现在也适用于毁伤。伤害加成下调至每点天赋4%，原先为6%。" }, { "|s14168|", "该天赋已被完全重做。现在每点天赋使破甲的能量消耗降低5点，并且在5连击点时使用会返还2个连击点。" }, { "|s14174|", "现在只提高你对被眩晕目标造成的伤害。" }, { "|s14983|", "该天赋在天赋树中上移，现在为2点天赋，最大能量提升不变。" }, { "|s14113|", "现在使你的毒药有50%几率不消耗层数。" }, { "|s14177|", "现在还会提高毁伤的暴击几率。" } } },
                    } },
                    { key = "viability", flow = {
                        { t = "p", v = "奇袭的实际可行性仍有待测试。初步看法是，每当面对高护甲值的对手时，奇袭将开始崭露头角，因为它能无视敌人护甲，并且比另外两个专精拥有更高的成长性。" },
                    } },
                    { key = "sw", flow = {
                        { t = "p", v = "奇袭盗贼最大的优势和劣势本质上是一样的。我们无法提供有益的团队增益/减益，只能靠纯粹的伤害输出来争取团队位置。因此，你可以预期盗贼在伤害统计上表现非常出色，以弥补功能性的不足。毒药应占我们伤害的一大部分，而任何免疫自然伤害的怪物都会大幅削弱我们的贡献。" },
                        { t = "good", v = { "毒药伤害- 我们的毒药天然无视敌人护甲。", "破甲的应用- 在需要时，奇袭追求强化破甲的损失最小。", "生存能力我们拥有一些不错的自保技能，例如|s5277|、|s1856|以及|s1966|。" } },
                        { t = "bad", v = { "无团队增益在与战士|s7386|持平的情况下|s8647|，我们在伤害和打断之外几乎没有任何实质性的团队贡献。", "自然免疫若战斗首领具有毒性免疫，此专精立刻会受到限制。", "能量恢复在获得套装或任何可能提升能量回复的改动之前，所有盗贼专精的循环都会显得有些\"迟缓\"。" } },
                    } },
                    { key = "beginner", flow = {
                        { t = "p", v = "奇袭历来是盗贼各专精中最简单的一个。我们用|s1310707|积攒连击点数，并主要将它们用于维持|s5171|和|s1310703|。奇袭没有任何重要的爆发大招，这个专精的绝大部分内容就是维持好你的 2 个增益。" },
                    } },
                    { key = "races", flow = {
                        { t = "p", v = "盗贼可选种族新增了天裔,目前看来这个种族特长相当平庸。" },
                        { t = "races", v = { { race = "人类", side = "alliance", mark = "tick" }, { race = "矮人", side = "alliance", mark = "tick" }, { race = "暗夜精灵", side = "alliance", mark = "tick" }, { race = "侏儒", side = "alliance", mark = "tick" }, { race = "兽人", side = "horde", mark = "tick" }, { race = "亡灵", side = "horde", mark = "tick" }, { race = "巨魔", side = "horde", mark = "tick" } } },
                        { t = "ul", v = { { text = "|s1259416|- 在空中向下滑翔10秒,同时控制移动方向。" }, { text = "|s1259686|- 尝试从元素交汇处汲取力量并获得祝福,移动速度与坐骑移动速度提高10%。如果附近没有元素交汇处,持续30秒;如果找到,则持续15分钟。" }, { text = "|s1259705|- 尝试汲取附近地脉的能量,生命值与法力值回复速度提高100%。如果附近没有地脉,持续15秒;如果找到,则持续15分钟。" }, { text = "|s1259710|- 法术、近战和远程急速提高1%。" }, { text = "|s1259707|- 对元素生物造成的伤害提高5%。" }, { text = "|s20589|- 立刻解除所有限制移动的效果,并获得3秒的免疫。" }, { text = "|s1259812|- 你接下来的3个伤害技能的能量消耗降低10%,且造成的伤害提高10%。" }, { text = "|s1259803|- 最大能量值提高5。" }, { text = "|s20593|- 侏儒的聪明才智使你使用的工程学装置的故障或反噬几率降低20%。" }, { text = "|s1259799|- 使你的所有法术和攻击的暴击几率提高10%，持续15秒。" }, { text = "|s20580|- 激活后遁入阴影，降低敌人侦测到你存在的几率。持续直到主动取消或移动为止。在战斗中使用此技能会降低敌人攻击你的欲望，但冷却时间延长至2分钟。其功能更接近渐隐术，而非让我们获得潜行状态或使用需要潜行的技能。" }, { text = "|s20582|- 闪避几率提高1%，移动速度提高2%。暗夜精灵盗贼和德鲁伊在潜行状态下更难被侦测到，效果相当于高出1级。" }, { text = "|s20585|- 死亡后变身为小精灵，移动速度提高75%。" }, { text = "|s1259718|- 立即移除所有昏迷效果。" }, { text = "|s20600|- 大幅提高潜行侦测能力，持续20秒。" }, { text = "|s20597|- 装备剑或双手剑时，你的所有法术和攻击的暴击几率提高2%。" }, { text = "|s20598|- 精神提高5%。" }, { text = "|s20594|- 立即移除所有流血、中毒和疾病效果并使你免疫这些效果，同时使你受到的所有物理伤害降低10%，持续8秒。" }, { text = "|s2481|- 使矮人能够感知附近的宝藏，并将其显示在小地图上。持续直到取消。" }, { text = "|s1259719|- 装备锤或双手锤时，你的所有法术和攻击的暴击几率提高1%。" }, { text = "|s1259721|- 对野兽造成的伤害提高5%。" }, { text = "|s20572|- 攻击强度与法术强度提高 10%，持续 15 秒。" }, { text = "|s1299026|- 立即移除并免疫所有诅咒与恶意效果，并使受到的所有魔法伤害降低 15%，持续 8 秒。" }, { text = "|s20574|- 当你装备斧或双手斧时，所有法术与技能的暴击几率提高 1%。" }, { text = "|s20573|- 你身上的昏迷效果持续时间缩短 20%。" }, { text = "|s7744|- 立即移除所有魅惑、恐惧和睡眠效果。" }, { text = "|s20577|- 激活后，每 2 秒恢复 7% 的总生命值和 7% 的总法力值，持续 10 秒。仅对 5 码范围内的人型或亡灵尸体生效。食尸过程中任何移动、动作或受到伤害都会取消该效果。" }, { text = "|s5227|- 水下呼吸时间延长 300%。" }, { text = "|s1260189|- 你的法术和攻击有 5% 的几率从目标身上吸取生命值，最多为你最大生命值的 5%。" }, { text = "|s20554|- 施法与攻击速度提高 10%，持续 10 秒。" }, { text = "|s1260270|- 在 6 秒内恢复 50% 的最大生命值。任何移动、动作或受到伤害都会取消该效果。" }, { text = "|s20557|- 对野兽造成的伤害提高5%。" }, { text = "|s20555|- 生命值回复速度提高 10%。此外，10% 的总生命值回复效果可以在战斗中进行。" } } },
                        { t = "p", v = "无限服新增的职业-种族组合" },
                        { t = "h4", v = "联盟" },
                        { t = "p", v = "在《魔兽世界：无限》中，联盟盗贼通常会优先选择暗夜精灵或侏儒，因为他们拥有远超其他种族的高强度主动技能。暗夜精灵提供|s1259799|，能带来可观的暴击率加成，并可与其他主动技能和触发效果叠加，打出高额的爆发伤害。侏儒则提供|s1259812|，使接下来3个技能的能量消耗降低20%，此外还有|s1259803|，可以避免其他种族在使用该技能时因能量恢复机制顺畅而产生的能量溢出浪费。" },
                        { t = "p", v = "天裔——根据所选阵营不同，天裔拥有对应的联盟或部落专属主动种族技能。" },
                        { t = "p", v = "侏儒" },
                        { t = "p", v = "暗夜精灵" },
                        { t = "p", v = "人类" },
                        { t = "p", v = "矮人" },
                        { t = "h4", v = "部落" },
                        { t = "p", v = "在无限服中，部落盗贼会更倾向于选择兽人或亡灵。兽人的标志性种族技能|s20572|，一个强力的主动爆发技能，其逻辑与夜精灵相同。可以叠加在其他技能和触发效果之上，用来实现强力的按需爆发。此外种族特长还能带来|s20574|在装备斧类武器时获得额外的1%暴击率。亡灵则提供|s1260189|，触发几率为5%，内置1秒触发条件冷却时间。考虑到盗贼的攻击速度非常快，这一触发型种族特长的利用率应当高于任何其他职业。" },
                        { t = "p", v = "兽人" },
                        { t = "p", v = "亡灵" },
                        { t = "p", v = "巨魔" },
                    } },
                    { key = "prof", flow = {
                        { t = "p", v = "乍看之下，工程学依旧是曾经的强力专业之一，多种小装置和插件带来了极强的灵活性和功能性。剥皮和制皮同样值得关注——新增了大量配方，让你至少在游戏初期更容易制作一些装备。随着数据不断收集，本节内容将持续扩充。" },
                    } },
                },
            },
            combat = {
                updated = "2026/10/05",
                sections = {
                    { key = "changes", flow = {
                        { t = "p", v = "盗贼从原版香草年代过渡到《魔兽世界：无限》时经历了大量改动，有些变动幅度很大，有些只是小幅调整。其中影响最深的两项是：毒药现在可以享受攻击强度的加成，以及能量回复采用了《巫妖王之怒》之后的平滑回复机制，不再是原本的节拍式回复。此外值得一提的是，毒药现在可以与风怒图腾以及磨刀石叠加。" },
                        { t = "p", v = "盗贼进入无限版本后的改动主要围绕天赋树的重新平衡。因此，基础技能大体保持不变，玩过香草时代盗贼的玩家会觉得非常熟悉。战斗贼在 PvE 中一直是香草版本完成度最高的专精，因此整体改动也最少。" },
                        { t = "tb", v = { { "|s1224716|", "该天赋取代了旧版强化背刺。它现在还会使你的|s1329|获得暴击率加成，并为你的|s53|附加 45% 的几率，使该技能在目标身上额外获得一个连击点数。" }, { "|s1310711|", "使你的|s2098|能量消耗降低 10 点。" } } },
                        { t = "p", v = "虽然新增的天赋与技能数量不多，但现有技能的改动相当深远。最值得关注的是，所有武器专精天赋已合并为一个天赋：|s13960|。另外，未命中的技能现在会部分返还能量，与游戏中后期版本的机制类似。" },
                        { t = "tb", v = { { "|s1225295|", "该天赋现在是 3 点天赋，提供 3% 命中加成，而旧版为 5 点天赋提供 5% 命中。" }, { "|s13742|", "该天赋现在会缩短|s2983|和|s5277|降低30%/60%。相当于将这些技能的冷却时间缩短为原先的一半。" }, { "|s13960|", "这个天赋将我们之前所有的武器专精天赋整合为一个独立天赋。它会让斧和剑获得5%的几率触发额外攻击，匕首和拳套武器提升5%暴击率，而锤类武器则无视目标15%的护甲。这意味着只要你保持武器技能不断更新，就不必因为获得了一把新类型武器而专门去洗天赋。对，我们现在也可以使用斧头了！" }, { "|s23584|", "该天赋每点使副手伤害增加的比例从原先的10%下调至5%。这很可能是为了配合我们的毒药现在按攻击强度缩放而进行调整的主要天赋之一。" }, { "|s18427|", "该天赋现在还会提升我们使用|s53|造成的伤害。" }, { "|s30919|", "不再提升武器技能。改为每点天赋使你的攻击被闪避或招架的几率降低1%。" } } },
                    } },
                    { key = "viability", flow = {
                        { t = "p", v = "战斗贼在《魔兽世界：无限》中仍将是盗贼最实用的天赋之一，原因在于他们不依赖毒药或持续伤害效果，而部分战斗可能会有对这些效果的免疫。纯粹的自动攻击伤害，再加上通过|s13877|实现的顺劈能力，将让战斗贼在当前版本中保持竞争力。类似于巫妖王之怒版本加入双天赋时的情况，大多数盗贼很可能都会准备一套战斗天赋，以及另外一套用于纯单体输出的天赋。" },
                    } },
                    { key = "sw", flow = {
                        { t = "p", v = "盗贼最大的优势与劣势本质上是相同的：我们不提供有益的团队增益/减益，而是依靠原始伤害输出来争取团队位置。因此，你可以预见盗贼的伤害数据会非常亮眼，以弥补我们相对缺乏的功能性。" },
                        { t = "good", v = { "以自动攻击为核心的天赋- 不依赖毒药和持续伤害意味着你的技能组合不会受到任何限制。", "顺劈能力强- 唯一拥有可观群体伤害能力的盗贼天赋。", "不错的爆发能力- 通过|s13877|，|s13750|，以及激活的种族特长，战斗盗贼可以提前倾泻伤害，或将其保留用于特定的DPS爆发阶段。", "生存能力- 我们拥有一些不错的生存技能，例如|s5277|，|s1856|，以及|s1966|造成的伤害。" } },
                        { t = "bad", v = { "没有团队增益- 随着战士|s7386|与|s8647|持平，我们在伤害和脚踢之外缺乏实质性的团队贡献。", "能量回复- 在等到可能提升我们能量回复的套装或后续改动之前，盗贼的所有专精玩起来都会显得有些“慢”。" } },
                    } },
                    { key = "beginner", flow = {
                        { t = "p", v = "战斗盗贼是一个相当直白的专精。我们用|s1752|积攒连击点数，主要将它们花在维持|s5171|上，多余的连击点数则倾泻到|s2098|。|s13877|和|s13750|是我们拥有的两个大爆发技能。拿不准的时候，最好一好就用、尽量同开。" },
                    } },
                    { key = "races", flow = {
                        { t = "p", v = "盗贼的种族列表中唯一新增的是全新的天裔，就目前来看它给人的感觉相当乏善可陈。" },
                        { t = "races", v = { { race = "人类", side = "alliance", mark = "tick" }, { race = "矮人", side = "alliance", mark = "tick" }, { race = "暗夜精灵", side = "alliance", mark = "tick" }, { race = "侏儒", side = "alliance", mark = "tick" }, { race = "兽人", side = "horde", mark = "tick" }, { race = "亡灵", side = "horde", mark = "tick" }, { race = "巨魔", side = "horde", mark = "tick" } } },
                        { t = "ul", v = { { text = "|s1259416|- 在空中向下滑翔10秒，期间可控制移动方向。" }, { text = "|s1259686|- 尝试从元素交汇处汲取力量并获得其祝福，使你的移动速度和骑乘速度提高10%。若附近没有元素交汇处，效果持续30秒；若找到交汇处，则持续15分钟。" }, { text = "|s1259705|- 尝试汲取附近地脉的力量，使你的生命值和法力值回复速度提高100%。若附近没有地脉，效果持续15秒；若找到地脉，则持续15分钟。" }, { text = "|s1259710|- 使你的施法、近战和远程急速提高1%。" }, { text = "|s1259707|- 对元素生物造成的伤害提高5%。" }, { text = "|s20589|- 立即挣脱所有移动限制效果，并在此后的3秒内免疫这些效果。" }, { text = "|s1259812|- 你接下来的3个伤害技能能量消耗降低10%，造成的伤害提高10%。" }, { text = "|s1259803|最大能量值提高5%。" }, { text = "|s20593|侏儒的巧思使你使用的工程学装置的故障或反噬几率降低20%。" }, { text = "|s1259799|使所有法术和攻击的暴击几率提高10%，持续15秒。" }, { text = "|s20580|激活后融入阴影，降低敌人发现你的几率。持续到取消或开始移动为止。在战斗中使用会劝退敌人攻击你，但冷却时间延长至2分钟。该技能更类似于渐隐术，而非提供潜行或需要潜行的技能。" }, { text = "|s20582|闪避几率提高1%，移动速度提高2%。侏儒潜行等级比夜精灵高1级。" }, { text = "|s20585|死亡后变形为幽魂，移动速度提高75%。" }, { text = "|s1259718|立即移除所有昏迷效果。" }, { text = "|s20600|大幅提高潜行侦测能力，持续20秒。" }, { text = "|s20597|装备单手剑或双手剑时，所有法术和攻击的暴击几率提高2%。" }, { text = "|s20598|精神提高5%。" }, { text = "|s20594|立即移除所有流血、中毒、疾病、魔法、恶魔、激变效果，并在8秒内使受到的物理伤害降低10%。" }, { text = "|s2481|使矮人感知附近的宝藏，并显示在小地图上。持续到取消为止。" }, { text = "|s1259719|- 装备钉锤或双手锤时，所有法术和攻击的暴击几率提高 1%。" }, { text = "|s1259721|- 对野兽的伤害提高 5%。" }, { text = "|s20572|- 攻击强度和法术强度提高 30%，持续 15 秒。" }, { text = "|s1299026|- 立即移除并免疫所有诅咒与邪恶效果，并使受到的魔法伤害降低 15%，持续 8 秒。" }, { text = "|s20574|- 装备斧或双手斧时，所有法术和技能的暴击几率提高 1%。" }, { text = "|s20573|- 你身上的昏迷效果持续时间缩短 20%。" }, { text = "|s7744|- 立即移除所有魅惑、恐惧和睡眠效果。" }, { text = "|s20577|- 激活后，每 2 秒恢复 7% 的生命值上限和 7% 的法力值上限，持续 10 秒。仅对 5 码内的人型生物或亡灵尸体生效。进食期间任何移动、动作或受到伤害都会打断该效果。" }, { text = "|s5227|- 水下呼吸时间延长 300%。" }, { text = "|s1260189|- 你的法术和攻击有 5% 的几率吸取目标生命值，吸取量最多为你生命值上限的 5%。" }, { text = "|s20554|- 施法和攻击速度提高 10%，持续 10 秒。" }, { text = "|s1260270|- 在 6 秒内恢复 50% 的生命值上限。任何移动、动作或受到伤害都会打断该效果。" }, { text = "|s20557|- 对野兽的伤害提高 5%。" }, { text = "|s20555|生命值回复速度提高10%。此外，10%的总生命值回复会在战斗状态下持续进行。" } } },
                        { t = "p", v = "无限服新增的职业-种族组合" },
                        { t = "h4", v = "联盟" },
                        { t = "p", v = "《魔兽世界：无限》联盟盗贼方面，由于夜精灵运营和侏儒运营拥有超越其他选项的强力活动技能，我们将更倾向于选择这两个种族。夜精灵提供|s1259799|，可为我们提供中等数量的暴击率，配合其他触发效果使用能打出可观的爆发伤害。侏儒提供|s1259812|，使接下来使用的3个技能的能量值消耗降低20%，同时还有|s1259803|，减少了在平滑能量恢复机制下其他种族使用时容易出现的溢出浪费。" },
                        { t = "p", v = "天裔——根据所选阵营，天裔可加入部落或联盟，并拥有特定的主动种族技能。" },
                        { t = "p", v = "侏儒" },
                        { t = "p", v = "夜精灵" },
                        { t = "p", v = "人类" },
                        { t = "p", v = "矮人" },
                        { t = "h4", v = "部落" },
                        { t = "p", v = "对于无限服中的部落盗贼，我们倾向于选择兽人或亡灵。兽人提供其招牌的|s20572|，这是一个强力的爆发技能，其运作逻辑与夜精灵相同，能够与其他技能和触发效果叠加，带来极强的瞬时爆发能力。此外，兽人还提供|s20574|，当持有一把斧头时，免费获得1%的暴击几率加成。亡灵提供|s1260189|，触发几率为5%，内置1秒冷却时间。考虑到盗贼的攻击速度，我们应当是所有职业中最能从这个种族特长中获益的。" },
                        { t = "p", v = "兽人" },
                        { t = "p", v = "亡灵" },
                        { t = "p", v = "巨魔" },
                    } },
                    { key = "prof", flow = {
                        { t = "p", v = "乍看之下，工程学依然和以往一样强大，其各种小工具和装置带来了极高的灵活性和实用性。制皮师也颇具亮点，新增了大量配方，使得至少在游戏前期你能更轻松地制作一些装备。随着数据不断积累，本节内容也会进一步完善。" },
                        { t = "p", v = "专业技能概述指南" },
                    } },
                },
            },
            sub = {
                updated = "2026/10/05",
                sections = {
                    { key = "changes", flow = {
                        { t = "p", v = "盗贼从原版经典旧世到《魔兽世界：无限》经历了大量改动，其中有些影响深远，有些只是微调。最重要的两点是：我们的毒药伤害现在会随攻击强度而提升，能量回复机制也采用了巫妖王及之后版本的流畅回复方式，取代了原有的跳动式回复。此外值得一提的是，毒药现在可以与风怒图腾以及磨刀石叠加。" },
                        { t = "p", v = "敏锐获得了一些新天赋，比如|s1310728|和|s1310721|这些天赋旨在让敏锐摆脱长期以来以PvP为核心的形象。目前很多数据仍不确定，很遗憾在等级上限30级的情况下，我们还无法很好地判断敏锐在测试服中的输出表现。" },
                        { t = "tb", v = { { "|s1310721|", "我们的新终极天赋会使|s1943|的周期性伤害跳数降低你在10秒内施放的下一个|s16511|或|s53|的能量消耗3点。该效果最多可叠加5次。在保持割裂完美覆盖的情况下，这实际上为我们每秒提供1.5点能量。" }, { "|s1310728|", "使|s1752|、|s16511|和|s14278|对生命值低于35%的目标造成10%额外伤害。如果某个首领战全程都处于斩杀阶段，我们就可以从该天赋中获得极为可观的收益。" }, { "|s1224782|", "新天赋，2点，使闷棍和致盲的能量消耗每点降低25%。" }, { "|s462708|", "5点天赋，使背刺有3%/点概率使下一次伏击不再需要潜行。" } } },
                        { t = "p", v = "敏锐天赋树改动最大，这是有原因的。我们还需要更多测试，但鉴于这些大幅改动，敏锐天赋在单体伤害上应当能与其他两个天赋分支抗衡。" },
                        { t = "tb", v = { { "|s14183|", "不再需要潜行，并且可添加连击点数的窗口时间从10秒延长至20秒。" }, { "|s13975|", "该天赋的第一点现在额外使潜行冷却时间缩短1秒。" }, { "|s14057|", "现为2点天赋，满级时提高10%伤害。原为5点天赋，满级时提高20%伤害。" }, { "|s14095|", "该天赋已被移除，因为闷棍不再有几率使你脱离潜行。" }, { "|s13983|", "伺机而动已上移至天赋树更高位置，现在使躲避或完全抵抗法术时有100%几率添加一个连击点数。该效果原满级时上限为45%。" }, { "|s13976|", "现在使相关技能有100%几率添加连击点数（原为75%）。" }, { "|s14278|", "现在在装备匕首时造成更高伤害。" }, { "|s14171|", "护甲削减效果已改为固定百分比，而非随玩家等级提升的数值。" }, { "|s16511|", "现在在装备匕首时造成更高伤害。对盟友造成的物理伤害加成已移除，改为使割裂伤害提高15%。" }, { "|s14082|", "\\\"割裂\\\"技能不再需要站位要求。" } } },
                    } },
                    { key = "viability", flow = {
                        { t = "p", v = "任何关于敏锐贼在 PvE 环境中的可行性评估都基本是猜测。我们有许多新内容可以提高我们的可行性，但在测试阶段我们无法接触到大部分技能组合。" },
                    } },
                    { key = "sw", flow = {
                        { t = "p", v = "敏锐盗贼最大的优势与弱点本质上是一样的。我们不能为团队提供有益的增益/减益效果，只能依靠原始伤害输出来争取团队位置。因此，你将看到盗贼在伤害统计中表现非常出色，以弥补缺乏更多辅助能力的不足。" },
                        { t = "good", v = { "持续伤害- 由于专注于强化\"割裂\"伤害以及\"千割\"效果，敏锐在战斗中的主动停顿期受到的惩罚最小。", "生存能力- 我们可以使用一些不错的技能来帮助生存，例如|s5277|、|s1856|和|s1966|。" } },
                        { t = "bad", v = { "无团队增益- 由于战士|s7386|的表现与|s8647|持平，除了伤害和\"脚踢\"之外，我们缺乏任何真正的团队贡献。", "流血免疫- 如果一场首领战中出现流血免疫机制，这个专精会立刻受到限制。", "能量回复- 在等到能提升能量回复速度的套装或更多改动之前，盗贼的所有专精手感都会有点“慢”。" } },
                    } },
                    { key = "beginner", flow = {
                        { t = "p", v = "敏锐盗贼的核心玩法是用|s16511|积攒连击点数，并主要将它们用于维持|s5171|以及给目标挂上|s1943|。这个专精比其他专精多一点细节：要穿插使用|s1856|来解锁更多潜行相关技能，同时保持|s16511|在目标身上的覆盖率以强化你的|s1943|。" },
                    } },
                    { key = "races", flow = {
                        { t = "p", v = "- 盗贼可选种族名单中唯一的新增内容是新种族天裔，就目前来看，这个种族的表现相当平淡。" },
                        { t = "races", v = { { race = "人类", side = "alliance", mark = "tick" }, { race = "矮人", side = "alliance", mark = "tick" }, { race = "暗夜精灵", side = "alliance", mark = "tick" }, { race = "侏儒", side = "alliance", mark = "tick" }, { race = "兽人", side = "horde", mark = "tick" }, { race = "亡灵", side = "horde", mark = "tick" }, { race = "巨魔", side = "horde", mark = "tick" } } },
                        { t = "ul", v = { { text = "|s1259416|- 在空中向下滑翔10秒，期间可控制移动方向。" }, { text = "|s1259686|- 尝试从元素汇聚之处汲取力量并获得其祝福，使你的移动速度和骑乘速度提高10%。若附近没有元素汇聚之处，效果持续30秒；若找到一处，则持续15分钟。" }, { text = "|s1259705|- 尝试汲取附近魔网的力量，使你的生命值和法力值回复速度提高100%。若附近没有魔网，效果持续15秒；若找到一处，则持续15分钟。" }, { text = "|s1259710|- 使你的施法、近战和远程急速提高1%。" }, { text = "|s1259707|- 对元素生物造成的伤害提高5%。" }, { text = "|s20589|- 立即摆脱所有移动限制效果的影响，并在3秒内免疫这些效果。" }, { text = "|s1259812|- 你接下来的3个伤害技能的能量消耗降低10%，并且造成的伤害提高10%。" }, { text = "|s1259803|- 能量上限提高5%。" }, { text = "|s20593|- 你天生的侏儒才智使工程学装置在你使用时发生故障或反噬的几率降低20%。" }, { text = "|s1259799|- 使你的法术和攻击的暴击几率提高10%，持续15秒。" }, { text = "|s20580|- 激活后遁入阴影，降低敌人侦测到你的几率。持续到主动取消或移动为止。战斗中使用该技能会打消敌人攻击你的念头，但冷却时间延长至2分钟。它更像一个渐隐术类技能，并不能让我们进入潜行状态或使用需要潜行的技能。" }, { text = "|s20582|- 闪避几率提高1%，移动速度提高2%。暗夜精灵盗贼和德鲁伊在潜行时更难被侦测到，效果相当于等级提高1级。" }, { text = "|s20585|- 死亡后变身为小精灵，移动速度提高75%。" }, { text = "|s1259718|- 立即解除所有眩晕效果。" }, { text = "|s20600|- 大幅提高你的侦测潜行能力，持续20秒。" }, { text = "|s20597|- 当你装备剑或双手剑时，你的法术和攻击的暴击几率提高2%。" }, { text = "|s20598|- 精神提高5%。" }, { text = "|s20594|- 立即移除并使你免疫所有流血、中毒和疾病效果，同时使你受到的所有物理伤害降低10%，持续8秒。" }, { text = "|s2481|- 使矮人可以感知附近的宝藏，并显示在小地图上。持续直到取消。" }, { text = "|s1259719|- 当装备锤或双手锤时，所有法术和攻击的暴击几率提高 1%。" }, { text = "|s1259721|- 对野兽造成的伤害提高 5%。" }, { text = "|s20572|- 攻击强度和法术强度提高 10%，持续 15 秒。" }, { text = "|s1299026|- 立即移除并免疫所有诅咒与恶毒效果，并使所有魔法伤害降低 15%，持续 8 秒。" }, { text = "|s20574|- 当装备斧或双手斧时，所有法术和技能的暴击几率提高 1%。" }, { text = "|s20573|- 受到的昏迷效果持续时间缩短 20%。" }, { text = "|s7744|- 立即移除所有魅惑、恐惧和沉睡效果。" }, { text = "|s20577|- 激活后，每 2 秒恢复 7% 的总生命值和 7% 的总法力值，持续 10 秒。仅对 5 码范围内的人型生物或亡灵尸体生效。进食期间任何移动、动作或受到伤害都会打断该效果。" }, { text = "|s5227|- 水下呼吸的持续时间延长 300%。" }, { text = "|s1260189|- 你的法术和攻击有 5% 的几率从目标身上吸取生命值，吸取量最多为你最大生命值的 5%。" }, { text = "|s20554|- 施法速度和攻击速度提高 10%，持续 10 秒。" }, { text = "|s1260270|- 在6秒内恢复50%最大生命值。任何移动、动作或受到伤害都会打断此效果。" }, { text = "|s20557|- 对野兽造成的伤害提高 5%。" }, { text = "|s20555|- 生命值恢复速度提高10%。此外，战斗中将持续恢复总生命值恢复量的10%。" } } },
                        { t = "p", v = "无限服新增的职业-种族组合" },
                        { t = "h4", v = "联盟" },
                        { t = "p", v = "在《魔兽世界：无限》中，联盟盗贼更推荐选择夜精灵或侏儒，因为他们的主动技能非常强力，胜过其他种族。夜精灵提供|s1259799|，为我们带来中等程度的暴击率，可以与其他主动技能和触发效果结合，打出高额爆发伤害。侏儒提供|s1259812|，使接下来3次技能的能量值消耗降低20%，同时|s1259803|能够减少其他种族在使用|平滑能量恢复机制时产生的能量溢出。" },
                        { t = "p", v = "天裔 - 天裔可根据所选阵营加入部落或联盟，其主动种族技能也会随之不同。" },
                        { t = "p", v = "侏儒" },
                        { t = "p", v = "夜精灵" },
                        { t = "p", v = "人类" },
                        { t = "p", v = "矮人" },
                        { t = "h4", v = "部落" },
                        { t = "p", v = "对于无限服中的部落盗贼，我们更推荐选择兽人或者亡灵。兽人的标志性种族特长是|s20572|，这是一项强力的主动爆发技能，其逻辑与夜精灵相似，可以与其他技能叠加以获得强大的瞬时爆发。他们还提供|s20574|，当手柄斧刃时获得免费提升 1% 暴击率。亡灵提供|s1260189|，触发几率 5%，内置 1 秒冷却。考虑到盗贼的攻击速度非常快，我们应当能比其他任何职业更频繁地从这个种族特长中受益。" },
                        { t = "p", v = "兽人" },
                        { t = "p", v = "亡灵" },
                        { t = "p", v = "巨魔" },
                    } },
                    { key = "prof", flow = {
                        { t = "p", v = "乍看之下，工程学依然是熟悉的核心强力专业，各种小装置和附魔零件提供了高度的灵活性和功能性。制革与裁缝也颇具价值，加入了大量新图纸，让你在游戏初期就能更轻松地制造一些装备。随着我们收集到更多数据，这一节的内容将会进一步扩充。" },
                        { t = "p", v = "专业概览指南" },
                    } },
                },
            },
        },
        PRIEST = {
            disc = {
                updated = "2026/09/22",
                sections = {
                    { key = "changes", flow = {
                        { t = "p", v = "在《魔兽世界：无限》中,戒律牧师获得了彻底重做的天赋树,开启了多种全新的玩法路线。重点强化了戒律牧师在后续资料片中发展出的特色,比如通过吸收伤害来|s10901|以及|s431622|。根据具体数值平衡,该专精有望成为所有团本的常驻人选,也是副本治疗者的优质选择。得益于|s402174|的加入,它同样适合作为升级专精使用!" },
                        { t = "p", v = "《魔兽世界：无限》为牧师职业引入了大量经典版本中没有的全新有趣技能。" },
                        { t = "tb", v = { { "|s402174|", "|s402174|是戒律牧师的标志性法术,首次加入于《巫妖王之怒》资料片。可对敌人造成伤害,也可对盟友进行治疗。2秒引导可造成大量治疗,并缩短目标身上虚弱灵魂的持续时间,从而实现将|s402174|以及|s10901|组合使用,大幅治疗单一目标的玩法。同时也是野外练级的优秀伤害技能。" }, { "|s431622|", "作为吸收伤害体系中的另一关键拼图,|s431622|会为受到我们暴击治疗的目标添加一层吸收护盾。" }, { "|s1277324|", "|s1277328|是亡灵牧师的新种族特长。可以在15秒内将生命值转化为法力值。虽然冷却时间很长,但可以在整场战斗期间提供可观的额外法力值。对治疗专精来说,损失的生命值基本可以忽略不计。" }, { "|s1277462|", "|s1277640|是侏儒(现在可以首次选择牧师)的新种族技能。|s1277640|是一个指向性增益,当目标生命值降低时会为其附加护盾并持续治疗。是非常强力的种族特长。" } } },
                        { t = "p", v = "《魔兽世界》中的戒律牧师：《无限》对现有技能也有一些改动，不过比其他一些专精要少一些。" },
                        { t = "tb", v = { { "|s14521|", "该|s14521|天赋现在允许你在施法时保留高达 50% 的精神法力回复（原版《魔兽世界》中为 15%）。这意味着你有更多法力可以运用——前提是装备上的精神属性仍如预期般充足。" }, { "|s6346|", "|s6346|，一项关键的辅助能力，现在所有牧师都可以使用。" }, { "|s2944|", "|s19280|现在成为所有牧师的基础法术，冷却时间为一分钟。" } } },
                    } },
                    { key = "viability", flow = {
                        { t = "p", v = "由于许多终局内容仍笼罩在神秘之中，很难判断每个专精的可行性。不过，戒律牧师吸收伤害而非治疗伤害的定位往往极具统治力，很有可能出现在许多团队配置中。它可能遇到的唯一困难是，那些点数在天赋树中非常靠前，一个大胆的神圣牧师也许能在不深入戒律天赋树的情况下获得类似的优势。" },
                    } },
                    { key = "sw", flow = {
                        { t = "p", v = "以下是基于当前可用信息，戒律牧师最明显的优势和劣势：" },
                        { t = "good", v = { "游戏中最强的吸收- 较低的|s10901|通常是造就一个出色甚至近乎压制的治疗专精的配方。|s431622|进一步增强了这一优势，不过其数值调整相当低。", "单刷不死专精- 出色的生存能力与不俗的伤害相结合，使戒律成为户外单练的绝佳专精。很少有精英怪能与你抗衡。", "核心辅助能力-|s27681|，|s21564|以及|s6346|都是核心辅助能力。|s10060|也相当不错。" } },
                        { t = "bad", v = { "与神圣专精竞争激烈- 上述大多数优势，神圣牧师点出|s10901|天赋后同样具备。我们天赋树更深层的天赋并没有那么不可或缺。", "群体治疗较弱- 我们获得的大部分激动人心的新内容只是进一步强化了单体治疗。群体治疗依然只是中规中矩。" } },
                    } },
                    { key = "beginner", flow = {
                        { t = "p", v = "总体而言，戒律牧师是新手玩家的绝佳选择。它单练能力足够，生存能力出色，而且进组治疗毫无问题。它也非常简单直接，上手快——用魔杖攻击敌人是你早期升级体验的常态。你还拥有一系列应急控制技能，例如|s8122|一旦陷入麻烦,尽管恐惧的怪物可能会吸引更多仇恨,所以务必跑得快!你的治疗和输出循环都具备足够的复杂度,足以保持趣味性。" },
                    } },
                    { key = "systems", flow = {
                        { t = "p", v = "牧师在《魔兽世界：无限》中区别于其他职业的主要特征就是种族专属法术。你将在10级时获得第一个,然后在20级时获得第二个。每个种族提供两个独特的种族专属法术,此外还有所有职业共享的常规种族特长。" },
                        { t = "tb", v = { { "10级", "|s1277370|", "|s13908|", "|s10797|", "|s1277455|", "|s2652|", "|s9035|" }, { "20级", "|s13896|", "|s1277331|", "|s2651|", "|s1277462|", "|s1277324|", "|s18137|" } } },
                    } },
                    { key = "races", flow = {
                        { t = "p", v = "《魔兽世界：无限》同时包含全新与熟悉的职业与种族组合。以下是所有可选方案的快速一览:" },
                        { t = "races", v = { { race = "暗夜精灵", side = "alliance", mark = "tick" }, { race = "牛头人", side = "horde", mark = "tick" } } },
                        { t = "ul", v = { { text = "|s1259823|是一个非常节省法力值的选择,并且在合理的冷却时间内提供了不错的伤害爆发。" }, { text = "|s1277462|是救命神技,尽管冷却时间确实较长。作为种族特长来说,它非常强大。" }, { text = "|s20591|和|s20589|完善了种族技能组合。前者是通用的法力值提升手段,后者在PvP中表现卓越,在PvE中也偶有用武之地。" } } },
                        { t = "p", v = "无限服新增的职业-种族组合" },
                        { t = "p", v = "虽然现在下定论戒律牧师最佳种族选项还为时过早,但以下是Beta测试阶段的几个热门候选:" },
                        { t = "p", v = "联盟联盟玩家可以选择人类、矮人、暗夜精灵和侏儒。" },
                        { t = "p", v = "尤其能带来种族特长与牧师专属种族法术的绝佳组合：" },
                        { t = "p", v = "如果侏儒不合你意，那么值得一提，因为其强大之处在于|s1259799|。与我们的|s431622|天赋结合后，它应该会成为一个非常强大的爆发治疗窗口。可惜的是，我们其他一些法术如|s10901|无法暴击。" },
                        { t = "p", v = "部落部落玩家可以在和之间选择。你的选择相当灵活，但我建议你选亡灵。|s20577|能快速回复法力值，在升级时为你节省时间。|s1277324|是战斗中的法力回复，代价是无关紧要的生命值消耗，|s7744|仍然是游戏中最佳的 PvP 种族特长之一，并且|s1260201|提供免费的伤害加成，即使在治疗天赋中也同样实用。" },
                    } },
                    { key = "prof", flow = {
                        { t = "p", v = "专业技能内容在《魔兽世界：无限》版本中进行了彻底重做，许多满级专业物品目前还没有公开资料。在练级初期以及无限测试服中，推荐选择附魔和裁缝。" },
                        { t = "p", v = "附魔可以制作魔杖，在练级过程中会构成伤害输出的主要来源之一。能够制造更高等级的魔杖会带来巨大优势。附魔还可以让你为装备附魔，在升级过程中获得额外属性。初期留意" },
                        { t = "p", v = "附魔扎营加成是" },
                        { t = "p", v = "裁缝可以制作布甲，这是牧师唯一能穿的护甲类型。在《无限》版本中有许多极为强力的裁缝布甲可以制作，成为裁缝能显著提升练级速度和副本表现。裁缝制作的装备往往优于同等级的任务奖励，同时每个部位还有更多的选择。" },
                        { t = "p", v = "裁缝扎营加成是" },
                    } },
                },
            },
            holy = {
                updated = "2026/09/21",
                sections = {
                    { key = "changes", flow = {
                        { t = "p", v = "神圣牧师在经典怀旧服团本治疗中已是核心，治疗手段围绕治疗术、强效治疗术、快速治疗、恢复和群体治疗展开。《魔兽世界：无限》保留了这一套技能组合，并新增了应对分散伤害的机制，鼓励切换治疗目标，同时移除了一些旧天赋和种族限制。神圣天赋树中移除了治疗专注、强化群体治疗和光明之泉。取代它们的是束缚治疗、愈合祷言和光明礼赞。所有牧师都可以学习神圣之灵和防护恐惧结界。" },
                        { t = "p", v = "《魔兽世界：无限》为牧师职业引入了不少经典原版中并不存在的新技能与新机制。" },
                        { t = "tb", v = { { "|s1240774|", "束缚治疗是神圣系的新天赋。它会同时治疗友方目标与施法者本人，威胁值较低，施法时间1.5秒。" }, { "|s1240827|", "愈合祷言是神圣系的新天赋，也是神圣天赋树的最终天赋点。它会在目标下一次受到伤害或受到非周期性治疗时为其治疗一次，随后跳跃至20码范围内的一名队友或团友身上。同一施法者只能存在一个愈合祷言，最多跳跃5次。" }, { "|s1277370|", "神圣恩典是人类牧师的新种族特长，立即治疗一名生命值低于50%的友方目标，并移除虚弱灵魂效果。无法对自己施法，冷却时间10分钟。人类牧师不再拥有绝望祷言。" }, { "|s1277462|", "应急方案侏族牧师的新种族特长，对一名队友施加持续30秒的护盾。下一次使其生命值降至35%以下的攻击将触发一次吸收效果和一个持续治疗效果。每个目标只能存在一个护盾，冷却时间10分钟。" } } },
                        { t = "p", v = "《无限》中的神圣牧师将获得一系列重做与升级后的能力与天赋，以提升团本治疗的游戏体验。" },
                        { t = "tb", v = { { "|s6346|", "防护恐惧结界现在所有牧师都可以在20级学习。此前它是矮人种族专属。冷却时间和持续时间均为3分钟。" }, { "|s14752|", "神圣之灵现在从30级起即可学习，不再是戒律系天赋。最高等级持续时间1小时。" }, { "|s20711|", "救赎之灵在《无限》中的持续时间为15秒，经典怀旧服中为10秒。" }, { "|s596|", "群体治疗现在的施法范围为40码，经典怀旧服中为30码。" }, { "|s10938|", "真言术：韧的最高等级持续时间为1小时。经典怀旧服中6级持续时间为30分钟。" } } },
                    } },
                    { key = "viability", flow = {
                        { t = "p", v = "神圣牧师依然是PvE中最强的治疗者之一。新的神圣天赋补充了对分散伤害的应对，以及切换治疗技能时的法力值返还。该专精依旧是布甲、依旧以站桩为主，依旧依赖法力值。" },
                    } },
                    { key = "sw", flow = {
                        { t = "p", v = "根据当前可用内容，神圣牧师最明显的优缺点如下：" },
                        { t = "good", v = { "灵活的治疗手段- 直接治疗、恢复、真言术：盾和治疗祷言，加上联结治疗和愈合祷言来应对分散伤害。", "强力的团队增益- 真言术：韧和神圣之灵均为已习得的技能。韧持续1小时。", "驱散与功能性- 驱散魔法、驱除疾病、所有种族都可使用的防护恐惧结界，以及死亡后的救赎之灵。" } },
                        { t = "bad", v = { "易受物理伤害- 布甲与较低的生命值使神圣牧师成为近战的首要目标。", "机动性不足- 大多数治疗需要站桩施法。移动时主要可用的手段是恢复和真言术：盾。", "耗蓝较高- 在切换治疗技能时，光明圣诗会返还法力值。重复施放同一个法术仍会消耗法力。" } },
                    } },
                    { key = "beginner", flow = {
                        { t = "p", v = "神圣牧师，以及更广泛的牧师职业，整体都非常容易上手，适合新玩家。牧师在前期练级中拥有出色的生存能力，可以使用多种治疗与防御技能，伤害能力也相当可靠。早期在伤害输出或法力回复方面可能遇到的任何问题，都能通过专业技能大幅简化，尤其是附魔提供的魔杖和裁缝产出的各种布甲。牧师在练级期间的小队内容中也十分灵活，在早期地下城中既能治疗又能造成伤害。" },
                    } },
                    { key = "systems", flow = {
                        { t = "p", v = "《魔兽世界：无限》中牧师区别于其他职业的主要特色是牧师种族法术。首次在10级获得，20级再次获得；每个种族除该种族所有职业共有的基础种族能力外，还提供两个该种族独有的法术。这些技能已在下表中整理：" },
                        { t = "tb", v = { { "10级", "|s1277370|", "|s13908|", "|s10797|", "|s1277455|", "|s2652|", "|s9035|" }, { "20级", "|s13896|", "|s1277331|", "|s2651|", "|s1277462|", "|s1277324|", "|s18137|" } } },
                    } },
                    { key = "races", flow = {
                        { t = "p", v = "《魔兽世界：无限》包含全新以及玩家熟悉的职业与种族组合。以下是所有可选方案的简要一览：" },
                        { t = "races", v = { { race = "人类", side = "alliance", mark = "tick" }, { race = "矮人", side = "alliance", mark = "tick" }, { race = "暗夜精灵", side = "alliance", mark = "tick" }, { race = "亡灵", side = "horde", mark = "tick" }, { race = "巨魔", side = "horde", mark = "tick" } } },
                        { t = "p", v = "无限服新增的职业-种族组合 目前虽然还无法明确判定哪种种族最适合神圣牧师，但一些可选种族绝对值得关注。联盟联盟玩家可以在人类、矮人、暗夜精灵和侏儒之间进行选择。在这些选项中，侏儒拥有一套非常出色的基础种族能力，包括|s1259823|，|s20591|，以及|s20589|和独特的牧师种族技能|s1277455|，|s1277462|使其成为 PvE 和 PvP 内容中神牧的稳妥选择。人类值得一提的荣誉奖是|s1277370|，一个外部瞬发治疗技能，还能移除虚弱灵魂。矮人保留|s13908|并获得|s1277331|。暗夜精灵仍然拥有|s20585|，|s20580|以及|s2651|，|s10797|。恐惧结界不再是矮人的专属能力。" },
                        { t = "p", v = "部落部落玩家可以选择亡灵或巨魔。两者各有优势，亡灵的基础属性与牧师种族特长组合非常出色，在升级、团本小队玩法中都能提供价值，以及PvP内容中同样适用。|s20577|是升级过程中（尤其是早期）维持生命值与法力值的优秀能力，而|s1260201|法术伤害则能提供稳定的被动伤害与生存能力。|s1277324|是一项有趣且独特的法力值回复手段，而|s7744|仍然是PvP战斗中的常备技能，尽管它已不再提供免疫效果。" },
                    } },
                    { key = "prof", flow = {
                        { t = "p", v = "说到专业技能，随着游戏进展，许多可行的选项最终都会在后期内容中变得有效或受欢迎。就当前阶段而言，尤其是升级过程中，有两个专业技能立刻脱颖而出：附魔和裁缝。附魔可以为玩家提供各种小幅装备增强效果，但选择这个专业的主要原因是可以制作魔杖。虽然起步武器的表现已经相当不错，但旅行早期可制作的魔杖（分别在5级和13级需要）能极大提升伤害输出，尤其在与……|s14524|。裁缝同样能带来各种容易获取的布甲装备，提升升级速度和生存能力，但特别值得一提的是它包含一些拾取绑定的稀有物品的图纸，例如旅行初期可制作的特殊披肩，对于其等级要求而言尤其强大。作为额外奖励，裁缝制作的旅行披风和附魔制作的旅行魔杖都提供露营加成，在升级过程中特别有用，可以提升法力值回复和生存能力。" },
                    } },
                },
            },
            shadow = {
                updated = "2026/09/21",
                sections = {
                    { key = "changes", flow = {
                        { t = "p", v = "《魔兽世界：无限》开发团队最雄心勃勃的目标之一，就是为传统的弱势专精提供新的增强手段。从无限版本的改动中可以看出，暗影牧师正是在这一理念下迎来重大变革的专精之一。在经典版本中，尽管暗影牧师凭借单挑能力在PvP玩家中颇受欢迎，但在团队副本中却一直是最弱的输出职业之一，通常只是为了给术士提供增益才会带一位。" },
                        { t = "p", v = "尽管游戏中仍有大量内容有待探索,但开发团队显然已经加入了一系列改动,直接着眼于提升暗影牧师在终极PvE里作为伤害输出者的可用性,同时保留了暗影的核心定位。" },
                        { t = "p", v = "《魔兽世界：无限》为牧师职业引入了大量经典旧世中原本没有的全新有趣技能。" },
                        { t = "tb", v = { { "|s1309595|", "暗言术：灭是暗影牧师在《燃烧的远征》中首次引入的标志性技能，在无限服中已被添加为基础牧师法术，32级即可习得。暗言术：灭是斩杀低血量敌人的完美工具，可用于触发|s15270|，并在其中投入两点天赋|s1310076|，暗言术：灭成为一个强大的斩杀型循环技能，冷却时间仅15秒。" }, { "|s1277324|", "黑暗牺牲是《无限》中新增的多个牧师种族特长之一，它为亡灵牧师提供类似于术士的效果。|s1454|能力，在15秒内将生命值转化为法力值。尽管尚不清楚该技能在实际使用中的强度如何，尤其是考虑到其长达10分钟的冷却时间，但毫无疑问，这项能力与暗影牧师的技能体系天然契合。" }, { "|s1277462|", "应急方案是牧师的新种族特长之一，能让侏儒牧师为指定目标附加一个防御性的增益效果：当目标生命值较低时，获得护盾并产生持续治疗效果。假设应急方案可以在暗影形态下使用，那么这项技能是一个非常有趣的外部防御手段，可在紧急情况下对盟友或自己使用。" } } },
                        { t = "p", v = "暗影牧师在《魔兽世界：无限》中将一直受益于大量经过重做与更新的技能和天赋，这些改动旨在提升其作为输出专精的整体可用性和操作体验。" },
                        { t = "tb", v = { { "|s2944|", "吞噬瘟疫现在是牧师的基础法术，冷却时间缩短至1分钟。此前，吞噬瘟疫只有亡灵牧师才能使用，冷却时间为3分钟。" }, { "|s15473|", "暗影形态基本上被彻底重做了：暗影形态现在仅提高10%的暗影伤害（原为15%），但同时使暗影法术的法力值消耗降低50%，并将暗影法术的暴击伤害加成提高100%。此外，只有治疗法术无法在暗影形态下施放，也就是说你可以在保持暗影形态的同时施放神圣系的伤害和辅助法术。受到物理伤害降低15%的效果保持不变。" }, { "|s15286|", "吸血鬼之拥的冷却时间现在为1分钟，持续30秒，并且新增了触发心灵窃取的效果：当受影响的敌人死亡时会激活心灵窃取。这为暗影牧师在团队作战中提供了一种更稳定的心灵窃取触发方式，特别是在有大量小怪的团战首领战中，敌人最后一击几乎不可能获取。" }, { "|s15257|", "暗影交织已被重新调整，不再提高目标所承受的全部暗影伤害，而仅仅是提高施法者自身的暗影伤害。这与经典版本相比是重大改动，因为该天赋历史上曾促使团队为了获取这一增益而带上恰好一名暗影牧师，无视其整体伤害表现。这将游戏末期PvE的重心重新拉回到暗影牧师个人的伤害输出上，这也是整个职业设计新思路中反复强调的主题。" } } },
                    } },
                    { key = "viability", flow = {
                        { t = "p", v = "虽然无限开发团队对暗影牧师所做的改动显然是为了直接改善其在游戏末期PvE中的表现，但其实际效果仍有待观察。" },
                    } },
                    { key = "sw", flow = {
                        { t = "p", v = "根据现有信息，以下是暗影牧师一些最显著的优势与劣势：" },
                        { t = "good", v = { "强大的单挑PvP能力暗影牧师的技能组合特别适合一对一的PvP，这在《魔兽世界：无限》中不太可能改变。", "全新的法力值回复手段暗影牧师历来法力值消耗极大，而《无限》中针对暗影的诸多改动都旨在改善该专精的法力值经济。", "拥有斩杀阶段伤害暗言术：死的加入以及配套天赋早逝为暗影牧师提供了一个针对生命值低于20%敌人的快速击杀伤害定位。" } },
                        { t = "bad", v = { "游戏末期团本表现尚不明朗针对暗影牧师的改动移除了其原有的团本定位，转而专注于个人伤害输出，但尚不清楚此版本的暗影牧师在与其他专精的团本对比中表现如何。", "暗影形态下无法治疗- 其他混合型职业在副治疗支援队友时可能更轻松一些，因为暗影牧师在暗影形态下无法施放治疗法术，只有吸血之拥等效果例外。", "升级过程中缺乏暗影特色- 暗影牧师的主题和视觉表现虽然经典，但需要一定时间才能完全成型。精神鞭笞在20级才能习得，而核心机制暗影形态要到40级才能解锁。" } },
                    } },
                    { key = "beginner", flow = {
                        { t = "p", v = "暗影牧师，乃至整个牧师职业，都非常容易上手，适合新手玩家。牧师在早期升级时生存能力出色，拥有多种治疗和防御技能，同时伤害输出也不差。早期在伤害或法力回复方面遇到的任何困难，都可以通过专业技能大幅简化，尤其是附魔提供的魔杖，以及裁缝制作的布甲。在升级期间的地下城中，牧师还能灵活切换治疗与输出，适应性很强。" },
                    } },
                    { key = "systems", flow = {
                        { t = "p", v = "《魔兽世界：无限》中区别于其他职业的牧师核心特色是种族专属法术。分别在10级和20级解锁，每个种族除了通用的种族特长之外，还拥有两项独有的种族专属法术。下表列出了这些技能：" },
                        { t = "tb", v = { { "10级", "|s1277370|", "|s13908|", "|s10797|", "|s1277455|", "|s2652|", "|s9035|" }, { "20级", "|s13896|", "|s1277331|", "|s2651|", "|s1277462|", "|s1277324|", "|s18137|" } } },
                    } },
                    { key = "races", flow = {
                        { t = "p", v = "《魔兽世界：无限》包含了全新以及经典熟悉的职业与种族组合。以下是所有可选组合的快速概览：" },
                        { t = "races", v = { { race = "人类", side = "alliance", mark = "tick" }, { race = "矮人", side = "alliance", mark = "tick" }, { race = "暗夜精灵", side = "alliance", mark = "tick" }, { race = "亡灵", side = "horde", mark = "tick" }, { race = "巨魔", side = "horde", mark = "tick" } } },
                        { t = "p", v = "无限服新增的职业-种族组合" },
                        { t = "p", v = "虽然现在下定论哪些种族最适合暗影牧师还为时尚早，但其中一些选项绝对值得特别关注。" },
                        { t = "h4", v = "联盟" },
                        { t = "p", v = "联盟玩家可以在人类、矮人、夜精灵和侏儒之间进行选择。在这些选项中，侏儒拥有一套相当出色的基础种族技能，例如|s1259823|、|s20591|和|s20589|，以及独有的牧师种族法术|s1277455|和|s1277462|，无论是在 PvE 还是 PvP 内容中，都是暗影牧师的可靠选择。夜精灵同样值得一提，其基础种族技能中既有|s20585|和|s20580|这类新奇独特的效果，也拥有强大的|s1259799|技能。" },
                        { t = "h4", v = "部落" },
                        { t = "p", v = "部落玩家可以在亡灵和巨魔之间进行选择。虽然两种选项都有各自的优势，亡灵的基础种族技能和牧师职业种族技能组合非常出色，在练级、满级团队副本和PvP内容中都能提供价值。|s20577|是一个在练级过程中、尤其是初期阶段维持生命值和法力值的优秀能力，而|s1260201|则同时提供可观的被动伤害和生存能力。|s1277324|是一个有趣且独特的工具，可提供额外的法力值回复，而|s7744|尽管不再提供免疫窗口期，但仍然是PvP战斗中的常用技能。" },
                    } },
                    { key = "prof", flow = {
                        { t = "p", v = "在专业技能方面，许多可行的选项最终都可能成为满级内容中有效或受欢迎的选择。在这个阶段，尤其是练级过程中，有两个专业立刻脱颖而出：附魔和裁缝。" },
                        { t = "p", v = "附魔可以为玩家提供各种小型装备强化效果，但早期选择这个专业的主要原因是能够制作魔杖。虽然魔杖在大多数可用初始武器中表现更出色，并且分别需要5级和13级才能使用，对伤害输出有巨大提升，尤其是与|s14524|搭配时效果更佳。" },
                        { t = "p", v = "裁缝还提供多种容易获取的布甲装备，可提升练级速度和生存能力，但尤为值得一提的是，它拥有一些拾取后绑定的稀有品质特殊物品配方，例如 ，这些物品就其等级需求而言属性格外强力。" },
                        { t = "p", v = "此外，裁缝的 和附魔的 都提供露营加成，在练级过程中特别实用，可提升法力值恢复和生存能力。" },
                    } },
                },
            },
        },
        SHAMAN = {
            ele = {
                updated = "2026/10/05",
                sections = {
                    { key = "changes", flow = {
                        { t = "p", v = "与其他专精相比，元素萨满目前的改动总体不多，主要集中在一些便利性优化以及来自《燃烧的远征》和《巫妖王之怒》中备受喜爱的回归技能，例如|s408438|和|s408490|。我们后期的法力值问题或许可以通过恢复天赋树中的|s1223033|天赋来解决，但其他问题——例如练级难度——由于我们法术基础伤害的改动以及天赋树早期缺乏新天赋支持，反而变得更严峻。就目前来看，我们的单体伤害不尽如人意，但群体伤害因新加入的|s408341|技能而格外强大。" },
                        { t = "tb", v = { { "|s408341|", "法术——萨满祭司基础技能，对你当前火图腾周围10码范围内的敌人造成火焰伤害。该技能取代了火焰新星图腾。其伤害数值非常高。" }, { "|s408438|", "元素天赋——3点——从《燃烧的远征》中回归，使你的闪电箭和闪电链有3/6/10%的几率在同一个目标上再施放一个相似的法术，不消耗法力值，伤害减半且不会产生仇恨。触发几率远低于后续资料片中的版本，因此表现偏弱。" }, { "|s408490|", "元素天赋/技能/法术——向目标投掷熔岩，造成火焰伤害。如果目标身上已有烈焰震击，熔岩爆裂的伤害提高20%。在历史上，熔岩爆裂在烈焰震击存在时必定暴击，但本版本对此进行了调整，以避免我们在暴击率提高时出现收益衰减的问题。" }, { "|s1223033|", "恢复天赋——3点——使你在施法时可以保留17/33/50%的法力值回复。这应该能为元素萨满提供一个更稳定的被动法力回复来源，而这正是原汁味魔兽世界版本中我们极度欠缺的能力。" }, { "|s66842||s66843||s66844|", "法术——分别于20、30、40级习得，作为萨满祭司的基础技能加入，可以为大地、火、水、空气四种图腾各配置一套，然后一次性同时插下所有4个图腾。这些技能最初在《巫妖王之怒》中加入，但本版本中较长的施法时间使其使用起来较为繁琐。" }, { "|s36936|", "法术——将图腾收回大地，按每个图腾的法术消耗返还25%的法力值。该技能同样最初在《巫妖王之怒》中加入，对于维持法力值以及避免因残留图腾意外激怒敌人而言，是一个非常实用的补充。" }, { "|s437009|", "法术——将你当前激活的图腾重新放置到30码范围内的指定位置，冷却时间1分钟。该技能最初在《熊猫人之谜》中加入，是一个不错的便利性技能，避免了为了重新插图腾而不得不跑到相应位置的麻烦。" } } },
                        { t = "tb", v = { { "|s16089|", "元素天赋 - 5点 - 使你的灼热图腾与熔岩图腾以及你的火焰、冰霜和自然法术的暴击伤害加成提高20/40/60/80/100%。这一改动源自原先位于天赋树更深处的单点天赋（提供100%加成）。这实际上对一个本就弱势的专精造成了不必要的削弱，但能让增强萨满也能享受该天赋。" }, { "|s29062|", "元素天赋 - 3点 - 使你在施放闪电箭、闪电链和熔岩爆裂时，因受到伤害攻击而被打断的程度降低23/46/70%。在经典怀旧服中，施法打断保护只在受到暴击时触发，使得该天赋的这一版本在所有场景中都更为实用。" } } },
                    } },
                    { key = "beginner", flow = {
                        { t = "p", v = "元素萨满历来拥有简单的操作风格，非常适合新手玩家；不过，并不建议在30级后期之前用元素天赋进行练级，因为那时你才能点出|s16578|。在《魔兽世界：无限》目前的情况下更是如此——在缺少大量法术强度装备的早期，元素萨满的练级难度更高。" },
                    } },
                    { key = "races", flow = {
                        { t = "p", v = "矮人是玩家的唯一选择。对于联盟部落玩家而言，兽人可能略胜一筹，但所有可选种族的表现都应当相差无几——主要取决于战斗时长、敌人类型以及你所拥有的装备等因素。" },
                        { t = "races", v = { { race = "兽人", side = "horde", mark = "tick" }, { race = "牛头人", side = "horde", mark = "tick" }, { race = "巨魔", side = "horde", mark = "tick" } } },
                        { t = "p", v = "无限服新增的职业-种族组合" },
                        { t = "p", v = "玩家的唯一选择。对于" },
                        { t = "p", v = "矮人- 目前联盟玩家的唯一可选种族。他们的种族特长|s1259719|在使用锤类武器时获得 1% 暴击几率。这让矮人相较于部落对应种族更为弱势。" },
                        { t = "h4", v = "部落" },
                        { t = "p", v = "兽人- 兽人的种族特长|s20572|在使用斧类武器时于 2 分钟冷却时间内使攻击强度与法术强度提高 10%，并因|s20574|获得 1% 暴击几率。血性狂暴本身极强，平均下来相当于 2 分钟内提升 1.25%。巨魔- 巨魔的种族特长|s20554|在 3 分钟冷却时间内使攻击与施法速度提高 10%，持续 10 秒。这明显弱于经典旧世时期根据已损失生命值获得更高加成的版本。|s20557|仅在特定情况下有用。|s401460|和|s20555|对于喜欢练级与单刷的玩家来说极为强力。- 牛头人的种族特长|s20550|现在还使你的命中几率提高1%。这是相当强力的效果，可以让你的配装更加灵活。他们的其他种族特长在练级和户外玩法中都很出色，拥有|s12566|让你能够快速穿越世界，以及标志性的|s20549|- 非常适合用来脱离险境或在PvP中使用。天裔- 天裔的种族特长|s1259710|提供1%的攻击和施法速度提升。这看起来似乎不多，但急速/施法速度对于元素萨满来说历来都是非常强力的属性。|s1259686|是一个不错的品质级技能，既能加快你的练级速度，也能在关键时刻帮你脱离敌人。|s1259707|依然在特定情况下非常强力，而|s1259416|在野外或许能在关键时刻救你一命。" },
                    } },
                    { key = "prof", flow = {
                        { t = "p", v = "制皮- 已经发现了数个装备属性优秀的新制皮图纸。我们知道暴雪的理念是\"最佳装备将更难获得\"，因此制造的装备在练级和游戏后期都可能会成为你配装的重要补充。**附魔**- 附魔一直是个强势选择，因为附魔师可以制作武器油，而且许多附魔的成本高得离谱。在《魔兽世界：无限》中，武器油的强度获得了进一步提升。此外，附魔师现在还可以制作各种图腾，例如 。目前还无法预测满级后的情况，但附魔已经展现出了极大的潜力。" },
                    } },
                },
            },
            enh = {
                updated = "2026/10/02",
                sections = {
                    { key = "changes", flow = {
                        { t = "p", v = "先说最重要的事：增强萨满祭司现在使用双手武器。这个版本的游戏中不会有官方的双持支持，相关技能已被移除。这个改动对部分玩家来说是好事，对另一部分来说则可能是灾难。不过除双手武器高伤害带来的爽快打击感外，这种武器风格的变化对增强萨满祭司的常规玩法可能影响不大。|s16362|来自我们高伤害双手武器的强力打击，当然也很过瘾。另一个重大变化是天赋的加入，该天赋早在巫妖王之怒版本就已加入增强专精。叠加到5层后可以|s15208|获得瞬发施法。还有一些图腾也做了调整，同时新增了|s11307|法术，相关内容将在改动部分重点介绍。" },
                        { t = "tb", v = { { "|s11307|", "现在绑定你当前激活的火系图腾，而不是作为独立的图腾存在。使用该技能会在你的火系图腾周围产生一次新星效果。" }, { "|s437009|", "该技能可以将你当前所有激活的图腾重新放置到指定位置。" }, { "|s408498|", "该天赋叠加到5层后，可以让你瞬发施放|s15208|。" }, { "", "这是一个3分钟冷却时间的爆发技能，开启后使你的近战攻速提高30%，持续25秒。" } } },
                        { t = "tb", v = { { "", "现在可以在室内变形为幽灵狼了。升级到2级时，它还会变成瞬发技能。" }, { "", "原本是将攻击强度转化为法术强度，现在改为将智力转化为法术强度。" }, { "", "该天赋在2级时，让你施法后仍能保持100%的法力值回复，无视5秒回复规则，并且还有100%的几率重置|s17364|每当你闪避或招架时。" }, { "", "使你能够招架攻击。同时降低你制造的大量威胁值，除非你正在使用|s16316|，此时反而会提高30%。" }, { "|s17364|", "现在冷却时间为8秒，而不是12秒。" }, { "|s66842|", "现在为3秒施法时间，可同时放置全部4个图腾。" }, { "|s10614|", "不再为你的小队提供脉冲式的武器附魔增益；改为稳定的团队范围增益，可与武器附魔叠加。" }, { "|s16387|", "现在提供一个短时脉冲增益，放大团队主手攻击伤害，可与武器附魔叠加。" }, { "|s16362|", "现在可以与|s16387|。" }, { "|s16342|", "现在可以与|s10614|。" } } },
                    } },
                    { key = "viability", flow = {
                        { t = "p", v = "《魔兽世界：无限》的一个目标是让每个职业和天赋都能发挥用途。目前来看，增强天赋是非常强力的练级天赋，能够依靠武器攻击而无需消耗太多法力值。后期团本中的可用性目前还无法预测，但就萨满祭司整体的当前实现而言，并没有什么明确的理由让你优先选择某个萨满天赋而非另一个。但有一点非常清楚：每个近战小队都会需要至少一名萨满祭司来提供|s10614|。这将使萨满祭司职业整体在每次团本中都有极高的需求。增强萨满祭司的群体伤害表现将非常出色，前提是我们有足够的法力值来维持|s11307|。至于单体伤害，这仍需观察，但目前看来同样颇具竞争力。" },
                    } },
                    { key = "sw", flow = {
                        { t = "good", v = { "机动性- 可在室内使用的瞬发幽灵狼在户外世界和团队副本中都非常实用", "群体伤害潜力- 火焰新星是一个冷却时间短的强力群体伤害技能；配合图腾传递，你可以轻松打出漂亮的群体伤害", "功能性- 你不仅能为团队提供有用的伤害输出，还能通过图腾强化和保护队友" } },
                        { t = "bad", v = { "缺乏独特性- 如果其他输出专精的表现超过你，团队完全可以换成其他萨满祭司专精，因为图腾效果是一样的" } },
                    } },
                    { key = "beginner", flow = {
                        { t = "p", v = "这个版本的增强萨满祭司对新玩家来说应该很容易上手。此前那些繁琐的机制都已经得到改善，整体操作也非常简单。对新手来说，最重要的两件事就是学会正确使用图腾和管理好法力值。你会非常依赖自动攻击，这也能让你有更多时间去思考这些，整体来说是一个非常适合新手的专精。" },
                    } },
                    { key = "systems", flow = {
                        { t = "p", v = "图腾管理是每个优秀萨满祭司玩家的关键。你需要清楚自己图腾的位置、能否覆盖到所有需要覆盖的队友，以及如何最高效地重新布置图腾以避免消耗过多法力值。强化自己和队友是增强萨满祭司的重要组成部分。" },
                        { t = "p", v = "随着|s408498|天赋的加入，你将能够无施法时间且不消耗法力值地使用|s15208|。立即使用一次|s15208|叠到 5 层之后再使用，避免溢出浪费层数。最大化这个天赋的收益一直是各版本经典游戏中增强萨满玩法的关键环节。" },
                    } },
                    { key = "races", flow = {
                        { t = "p", v = "这是对全新可用种族特长以及全新职业/种族组合的初步介绍。" },
                        { t = "races", v = { { race = "兽人", side = "horde", mark = "tick" }, { race = "牛头人", side = "horde", mark = "tick" }, { race = "巨魔", side = "horde", mark = "tick" } } },
                        { t = "p", v = "无限服新增的职业-种族组合" },
                        { t = "h4", v = "联盟" },
                        { t = "p", v = "已加入《魔兽世界：无限》中可选的种族池，成为联盟方可选的萨满种族。不幸的是，就 PvE 种族特长而言，即便不是最弱的选择，也是非常弱的选择之一。不过在联盟方只有这一个可选，所以也只能选它。它们的种族特长|s1259721|对野兽的伤害提高 5%，以及|s1259719|只要装备锤类武器，攻击和法术的暴击率就永久提高 1%。这两个种族特长各有用处，却都非常依赖场景。|s20594|依然是矮人的招牌种族特长，能立即移除并免疫所有流血、中毒和疾病效果，同时在 8 秒内受到的物理伤害降低 10%。" },
                        { t = "h4", v = "部落" },
                        { t = "p", v = "在《无限》中，部落方可选的萨满种族非常丰富。最新的成员是|s1259707|和|s1259710|带来的 1% 急速加成。这些种族特长没有其他那些那么依赖场景，但收益依然不高。天裔的真正优势在于通过种族特长提供的大量移动能力，|s1259686|使你的（坐骑）移动速度提高10%，持续30秒，并且|s1259416|赋予你10秒免费的缓落术。也有一些改动加入到《无限》中，另外一些种族特长则保持不变。|s20549|保持不变，而|s20550|现在还会额外提高1%命中以及5%总生命值。两个全新加入的种族特长是|s1259918|，在移动时缓慢提高你的行走速度，最高达到30%，以及|s20552|，允许你每小时采集一棵草药而不需要学习草药学技能，但每株草药只能使用一次。|s20557|来强化对野兽的伤害，提高5%。|s20554|提高10%急速，持续10秒。|s20555|基本保持不变，使你的生命回复速度提高10%，并且战斗外回复总量的10%将在战斗内持续。全新加入的种族特长是|s1260270|，在6秒内回复你最大生命值的50%，但任何移动动作或受到伤害都会打断此效果。在《无限》中依然是增强萨满祭司的最佳选择。虽然|s20574|在装备斧类武器时提供1%暴击率依然是场景性的选择，|s20572|获得了不错的改动，能在15秒内提升我们10%的攻击强度和法术强度，没有任何负面效果。|s1299026|同样非常强力，可以瞬间解除并免疫所有诅咒与灾厄效果，并且使受到的法术伤害降低15%，持续8秒。|s1299026|与|s20573|的组合，让兽人成为适合各种内容的全能选择。" },
                        { t = "p", v = "总体而言，如果你是部落玩家，兽人正在成为PvE和PvP中最强的选择，但其他三个可选种族也根据你的需求提供各自独特的增益。不幸的是，联盟的选择非常匮乏，矮人目前更多是针对特定情况的选择，但这不应阻止你选择矮人萨满祭司。" },
                    } },
                    { key = "prof", flow = {
                        { t = "p", v = "在Beta测试期间，制造类专业，例如|s10662|和|s9785|看起来非常强力，因为它们可以让你通过简单方式获得属性不错的装备升级。尤其是早期的武器升级感觉提升巨大。当你能够获得副本奖励后，|s9785|的价值可能会下降，但总体而言，它们似乎能够很好地填补你装备上的空缺。|s11611|在升级过程中同样看起来非常强力，为你提供大量强力的增益，这些增益应该也能很好地延续到游戏后期。" },
                    } },
                },
            },
            resto = {
                updated = "2026/09/23",
                sections = {
                    { key = "changes", flow = {
                        { t = "p", v = "恢复天赋相比其他专精到目前为止改动不多，主要集中在提升操作便利性，以及回归一些《燃烧的远征》和《巫妖王之怒》中广受喜爱的内容，例如|s408510|和|s1239243|。恢复天赋树中的新加天赋也有助于缓解经典旧世版本中略显乏力的法力值消耗问题。尽管练级阶段的治疗职业仅推荐组队玩家选择，但恢复萨满在游戏后期的潜力依然强劲，因为|s1223033|天赋树中的新天赋也有助于改善经典版魔兽原本乏力的法力值经济。虽然作为治疗职业练级只建议在组队的情况下进行，但恢复萨满在游戏后期的潜力依然强劲，因为|s10623|凭借激流获得了前所未有的增强，且|s25357|也获得了强力新天赋的支持，让萨满在不考虑套装奖励和特定团队战斗的情况下，已具备坚实的核心技能组合。" },
                        { t = "tb", v = { { "|s408341|", "法术 - 该法术为萨满基础技能，可对当前火焰图腾周围10码范围内的敌人造成火焰伤害，并取代火焰新星图腾。其伤害数值极高。" }, { "|s1239243|", "恢复天赋/技能 - 为友方目标恢复一定生命值，并附加一个持续15秒的强力持续治疗效果。同时使你对该目标施放的|s10623|法术的治疗效果提高25%。" }, { "|s1223033|", "恢复天赋 - 3点 - 施法时可继续分别恢复17%/33%/50%的法力值。这是一项强力的法力值回复手段，使精神属性对萨满的价值远超经典旧世版本。" }, { "|s66842||s66843||s66844|", "法术 - 分别在20级、30级和40级学会，该技能作为萨满祭司的基础技能，允许你为每种能力设置一组由土、火、水和空气图腾组成的独特组合，然后一次性放下全部4种图腾。虽然一次性放下多达4种图腾非常强力，但你需要为此投入3秒施法时间，因此该法术最适合在准备开Boss前使用，或在当前图腾到期后再使用。" }, { "|s36936|", "法术 - 将你的图腾归于大地，返还每个图腾施法所需法力值的25%。该技能最初在巫王之怒资料片中加入，对于快速销毁不需要的图腾以避免拉到额外敌人，以及在图腾即将失效或不再有用时恢复法力值都非常实用。" }, { "|s437009|", "法术 - 将你的激活图腾重新放置到30码范围内的指定位置，冷却时间为1分钟。该技能最初在熊猫人之谜资料片中加入，是一项非常实用的便捷法术，可以在不跑到位的情况下重新布置图腾，或充分利用增益图腾的较长持续时间，避免通过召唤类技能放下4个新图腾所需的3秒施法时间。" } } },
                        { t = "tb", v = { { "|s29206|", "恢复天赋 - 3点 - 该天赋曾在你对目标施放|s25357|时最多可叠加3层，使其在应对伤害时表现糟糕且整体效果不佳，但现在它只是治疗之涌的基础强化增益，使其在所有情况下都更加强大，而非局限于特定场景。" }, { "|s16184|", "恢复天赋 - 2点 - 除了缩短冷却时间和提升|s20608|的生命值法力值外，现在还使你的最大生命值永久提升4%。" }, { "|s16179|", "恢复天赋 - 5点 - 现在除了法力值减免效果外，还可使命中几率最多提升5%！" } } },
                    } },
                    { key = "beginner", flow = {
                        { t = "p", v = "恢复天赋历史上拥有非常简单的玩法（放下图腾，使用治疗链），这使其成为新手玩家的绝佳选择。虽然你现在也需要使用新的激流和治疗之涌——因为它现在作为基础技能确实变得更强了——但这只是让该专精变得更加全面，同时保持了其简单性。一个群体治疗技能、一个主要的单体治疗技能、以及一个冷却时间较短的周期性治疗效果；这就是恢复天赋保持高效所需的一切！" },
                    } },
                    { key = "races", flow = {
                        { t = "p", v = "矮人是联盟玩家的唯一选择。对于部落玩家而言。对于玩家来说，玩家而言，兽人战士可能略胜一筹，但所有可选种族的表现大致相当——主要取决于战斗时长、目标类型以及可用装备的差异。" },
                        { t = "races", v = { { race = "兽人", side = "horde", mark = "tick" }, { race = "牛头人", side = "horde", mark = "tick" }, { race = "巨魔", side = "horde", mark = "tick" } } },
                        { t = "p", v = "无限服新增的职业-种族组合" },
                        { t = "p", v = "玩家的唯一选择。对于部落" },
                        { t = "p", v = "矮人- 联盟玩家目前唯一的种族选择。其种族特长在使用锤类武器时获得1%暴击几率。这使得侏儒相对兽人略显劣势，因为兽人使用斧类对获得类似的加成，且附带其他非常实用的加成。|s1259719|在使用锤类武器时获得 1% 暴击几率。这使得矮人相对弱于兽人，兽人拥有类似的斧类武器加成，同时还附带其他非常有用的加成！" },
                        { t = "p", v = "玩家来说，" },
                        { t = "p", v = "兽人战士- 兽人的种族特长|s20572|在使用斧类武器时，可使攻击强度和法术强度提高 10%，持续 15 秒，冷却时间为 2 分钟，并且因|s20574|. 血性狂怒是一个强力的冷却技能，应在战斗中治疗需求最高的时刻使用，以增强你的治疗量。巨魔- 巨魔的种族特长|s20554|使攻击速度和施法速度提高10%，持续10秒，冷却时间3分钟。这比经典旧世中的同款技能弱得多，旧版初始为10%提速，生命值极低时最高可达30%。|s20557|对治疗来说基本没有用处，其他的自我治疗加成也只有些许价值，因为需要时你可以随时给自己施加远超于此的治疗。牛头人- 牛头人的种族特长|s20550|现在还能使你的命中率提高1%，但遗憾的是这对治疗者来说基本无关紧要（除了用功能型法术命中目标之外）。他们的其他种族特长在练级和野外玩法中非常出色，其中|s12566|能让你在世界中飞速穿行，而标志性的|s20549|- 非常适合用来摆脱困境或参与PVP。天裔- 天裔的种族特长|s1259710|提供 1% 的攻击和施法速度加成。虽然这点加成不多，但急速/施法速度对于恢复萨满祭司来说历来都非常强力。|s1259686|是一个提升移动速度的爆发技能，在某些情况下非常好用，而且|s1259416|可能在野外危机关头救你一命。|s1259707|对于治疗职业来说基本可以无视。" },
                    } },
                    { key = "prof", flow = {
                        { t = "p", v = "制皮—— 已经发现了几种新的制皮图纸，其装备属性非常优秀。我们知道暴雪的理念是“最佳装备将更加难以获得”，因此制造装备在练级和满级阶段都可能特别有用，可以作为你装备积累的补充。附魔—— 附魔一直是一个强力选择，因为它能制作武器油，而且许多附魔的成本也很高。在《魔兽世界：无限》中，武器油（例如）的效果变得更强了。附魔师现在还可以制作图腾（例如）。满级阶段会发现什么还很难说，但附魔看起来已经是一个很好的选择。" },
                    } },
                },
            },
        },
        MAGE = {
            arcane = {
                updated = "2026/10/05",
                sections = {
                    { key = "changes", flow = {
                        { t = "p", v = "奥术已经独立成为一个专精，不再仅仅用于强化另外两个法师专精。相反，你需要深入天赋树，通过奥术法术来造成伤害。这一切都基于奥术冲击，以及一些让你消耗更多法力、并与之形成联动效果的天赋。" },
                        { t = "p", v = "除了奥术冲击（让这个专精得以独立存在）以及弹幕（让循环更流畅）之外，其余新加入的技能大多作为辅助天赋出现。" },
                        { t = "tb", v = { { "|s1239700|", "奥术冲击在2.5秒延迟后造成伤害，每层叠加会使其他所有法术的伤害提高10%，最多叠加4层。每层都会使法力消耗提高175%。" }, { "|s400588|", "这个天赋是与上文提到的法术并列的两大核心改动之一，让你能在不消耗法力的情况下，充分利用奥术冲击的层数来打出可观的伤害。" }, { "|s11210|", "降低奥术法术的仇恨值，让你在进行群体伤害时无需担心仇恨问题。它还提供一定的法术穿透，在目标没有抗性时可提高伤害。" }, { "|s11247|", "奥术法术的射程最多提升6码。虽然大多数时候影响不大，但你通常会至少投入一点来解锁后面的天赋。" } } },
                        { t = "p", v = "这些是对原有法术的改动，正是它们让奥术拥有了自己的独立定位。" },
                        { t = "tb", v = { { "|s18462|", "施法期间法力值依然可以持续回复；该数值从原先满级时的15%调整为50%。" }, { "|s11232|", "效果与经典旧世版本相同，提供等量智力，但现在还会使奥术法术的暴击伤害提高100%。" }, { "|s11222|", "该天赋从原先每点2%命中、最高10%，下调为每点1%命中、最高5%。值得注意的是，整体命中属性经过了重新设计，现在17%即可完全命中，不再有1%的不可避免未命中。" }, { "|s10216|", "同名不同等级的该法术不再叠加，无法再增加区域内生效的持续性伤害效果数量。" }, { "|s18459|", "该火焰天赋现在除了对火焰法术外，还为奥术冲击和冰枪术提供暴击几率加成。" } } },
                    } },
                    { key = "viability", flow = {
                        { t = "p", v = "《魔兽世界：无限》的目标之一是让每个职业和专精都切实可用。请写上几行、大约两段文字，谈谈你对职业可行性的初步看法，重点关注团队副本和 PvE 内容；也可以适当聊一点 PvP 和升级方面的话题。" },
                    } },
                    { key = "sw", flow = {
                        { t = "p", v = "奥法总体上是一个相当令人满意的专精，最大的短板在于升级。玩家通常用冰霜或火焰专精练级，等到三个专精都各有一席之地的其他资料片，再换回奥术。你的整体表现也在很大程度上取决于你所在的公会以及团队副本的输出速度；对于喜欢在自身所处的限制条件下发挥到极致的玩家来说，这可能是一件好事；而对另一些玩家来说则可能令人非常恼火，因为在击杀时间更短、法力管理更容易甚至无关紧要的战斗中，他们本可以打出高得多的表现。" },
                        { t = "good", v = { "爆发潜力- 凭借奥术强化这类爆发技能，以及提升奥术暴击伤害的天赋，奥法在游戏后期极有可能拥有出色的爆发伤害（从历史来看也确实如此）。", "流畅的输出循环- 虽然更多是手感层面的事，但先用奥术冲击叠出减益效果，再接一发迅捷的奥术飞弹，玩起来非常爽快，是很棒的玩法循环。", "法力管理- 很多玩家喜欢奥法的这一面：通过高效利用法力值来最大化伤害/覆盖时间，从而体现自己的操作水平。" } },
                        { t = "bad", v = { "法力值问题- 虽然这可以算优点，但对于不擅长法力管理的玩家来说，蓝量耗尽的感觉会让人极其恼火。", "升级体验差- 由于法术的法力消耗非常高，你会经常发现自己只能用魔杖来输出——魔杖的伤害其实还不错，但换成任何专精都能做到这一点。", "战斗时长不定- 表现与特定首领以及/或整个团队的表现紧密挂钩——限制击杀时间会非常令人沮丧。" } },
                    } },
                    { key = "beginner", flow = {
                        { t = "p", v = "与经典怀旧服中的其他法师专精类似，《魔兽世界：无限》里的这个所谓新专精起初玩起来非常简单；至于之后会不会变得更复杂，目前还很难说——可能简单到只需用奥术冲击叠到4层，再用强化后的奥术飞弹清掉层数，也可能需要在触发运气不佳时中间插入某个法术来移除层数。此外，它很可能还需要根据Boss击杀时间调整输出循环，改变每次愿意叠加的奥术冲击层数，以最大化法力值的利用，让你最关键的法术保持更高的整体覆盖率。" },
                        { t = "p", v = "我猜测是前者，而且目前来看依然非常简单，因为游戏在怀旧魔兽世界精神层面上似乎极为简易，不过这也很难确定。" },
                        { t = "p", v = "升级过程中，魔棒在升级时感觉非常有用，但任何施法者一直以来都是这样。奥法拥有一个魔棒专精天赋，进一步强化了这一点，尤其是在早期。" },
                        { t = "p", v = "在地下城中进行战斗时，群体伤害感觉非常出色，是该天赋专精的最大亮点，并附带来自|s11210|，这样你就可以无顾虑地尽情使用魔爆术，假定你的坦克足够强力（最好是圣骑士坦克）。这确实需要一些调整，才能确保你在地下城中始终保持良好的法力值；调整方法是使用魔杖或低耗法术，比如只用一次奥术冲击后立刻接奥术飞刃，或者直接用魔杖来省蓝，把法力留给那些用群体伤害更划算的拉怪场合。" },
                        { t = "p", v = "个人认为，这个专精对新手来说相当友好，因为初期操作非常简单，后续优化主要是避免喝水休息，大多数队伍都能接受。即使后期难度有所提升，我相信也不会太大，而且你还有充足的时间，在升满级的过程中慢慢适应。" },
                    } },
                    { key = "systems", flow = {
                        { t = "ul", v = { { term = "奥术冲击层数", text = "- 每次使用时|s1239700|，获得一层负面效果，最多叠加 4 层——每层都会提高下一次奥术冲击的法力消耗，并提升你随后使用的任何一个其他法术的伤害。这个后续法术会将层数清零。玩法就是先叠层，然后用它们强化之后一个有意义的大法术；通常这会是用|s400588|强化过的奥术飞弹来完成，但也可能存在不同的变体。" }, { term = "法力管理", text = "- 奥法的核心要点之一在于不要把法力值视为负担，而应将其当作必须被推到极限的资源,以便从专精中榨取最大伤害。通常的目标是把每一场战斗的法力值耗到 0,前提是之后没有重要战斗。通过奥术冲击叠层、以及在 2-3 层时清除来灵活控制法力消耗,比低装等时稳定叠到 4 层要高效得多。到了后期,也会面临类似的抉择:在 4 层后赌一轮导弹弹幕触发,还是用其他法术清掉层数再重新叠奥术冲击。当然,未来的数值平衡、新法术加入以及现有法术之间的联动都可能改变这里给出的基础思路。" } } },
                        { t = "p", v = "虽然非常简单,但法师在战斗中有以下两个系统或机制需要记住:" },
                    } },
                    { key = "races", flow = {
                        { t = "p", v = "除了旧的种族-职业组合外,法师现在在部落方还可以选择兽人,在联盟方还可以选择天裔精灵。虽然这很有趣,但并不会盖过旧的组合,因为所有种族特长都已被重做。目前还很难判断哪种在终局更优,因为有太多尚未确定的因素。在测试服中,每个种族都有各自有趣的优势,所以暂时不必过于担心选择问题,先挑自己觉得有趣或主题喜欢的就好。" },
                        { t = "races", v = { { race = "人类", side = "alliance", mark = "tick" }, { race = "侏儒", side = "alliance", mark = "tick" }, { race = "亡灵", side = "horde", mark = "tick" }, { race = "巨魔", side = "horde", mark = "tick" } } },
                        { t = "ul", v = { { text = "|s1259817|:" }, { text = "|s20591|:" }, { text = "|s20593|:" }, { text = "|s20589|:" }, { text = "|s1259718|:" }, { text = "|s20600|:" }, { text = "|s20597|:" }, { text = "|s20598|:" }, { text = "|s1259705|:" }, { text = "|s1259707|:" }, { text = "|s1259416|:" }, { text = "|s1259710|:" }, { text = "|s20574|:" }, { text = "|s20572|:" }, { text = "|s1299026|:" }, { text = "|s20573|:" }, { text = "|s20554|:" }, { text = "|s1260270|:" }, { text = "|s20557|:" }, { text = "|s20555|:" }, { text = "|s20577|:" }, { text = "|s5227|:" }, { text = "|s7744|:" }, { text = "|s1260201|:" } } },
                        { t = "p", v = "无限服新增的职业-种族组合" },
                        { t = "h4", v = "联盟 侏儒" },
                        { t = "p", v = "|s1259817|是侏儒获得的新的主动冷却技能,除了伤害提升外,它还附带一定的法力值消耗减免效果。伤害提升方面不错,但法力值减免幅度较小。此外,|s20591|直接增加法力值上限,而不是智力。|s20593|不再提供额外等级,而是提升工程学道具的效果。" },
                        { t = "p", v = "种族加成" },
                        { t = "p", v = "人类" },
                        { t = "p", v = "|s1259718|是一个强力的PvP种族特长，让法师除了闪现术之外还能解除昏迷效果。|s20597|现在也能让法师受益，装备剑类武器时暴击几率提高2%。精神无论是练级阶段，还是随着游戏推进获得法师护甲和奥术冥想天赋之后，都相当重要；即使在战斗和施法状态下，它也能提高你的法力值回复速度。|s20600|能侦测潜行。比较看情况，但有时能帮你赢下决斗。" },
                        { t = "p", v = "种族加成" },
                        { t = "p", v = "高阶天裔" },
                        { t = "p", v = "|s1259705|是这个新种族的种族特长，使法力值和生命值回复速度提高100%，持续15秒。如果后期法师在高覆盖输出下法力值需求吃紧，它会很有用——不过除此之外，与侏儒增加法力值上限的种族特长相比，它显得有些逊色。|s1259707|也可能有用，主要取决于你面对的敌人和/或未来要打的团队副本。" },
                        { t = "p", v = "|s1259710|是其中最有意思的一个，提供1%法术急速。不过目前还很难判断，与其他种族特长相比，它后期到底有多重要。" },
                        { t = "p", v = "种族加成" },
                        { t = "h4", v = "部落" },
                        { t = "p", v = "兽人" },
                        { t = "p", v = "|s20572|也是新增的，为施法者提供法术强度。|s20573|缩短昏迷效果的持续时间。盗贼恨死它了。|s1299026|另一项优秀的PvP主动冷却类饰品，能移除诅咒和巫毒，但对法师来说基本没用，因为我们自己有相应技能|s475|，但它还能在接下来的8秒内降低受到的魔法伤害。|s20574|毫无用处，因为很遗憾，法师无法使用斧类武器。" },
                        { t = "p", v = "种族加成" },
                        { t = "p", v = "巨魔" },
                        { t = "p", v = "巨魔法师依然有一席之地；其种族特长稍有改动|s20554|移除了基于生命值损失提升施法速度的机制，改为始终提供10%的增益。我们还能使用|s20557|，实用性非常看情况——如果目标是野兽就很有用，否则就没多大意义。它的价值很大程度上取决于当前阶段的内容环境。|s1260270|现在改为引导型，在6秒内回复50%最大生命值，这非常实用，因为我们之前除了绷带之外并没有这类防御手段。" },
                        { t = "p", v = "种族加成" },
                        { t = "p", v = "亡灵" },
                        { t = "p", v = "|s20577|现在除了生命值外还能回复法力值，进一步改善了任务过程中的续航体验。|s5227|带来的提升相当有限。然而，法师PvP中最强的种族特长通常是|s7744|，它能解除或免疫魅惑、恐惧和睡眠效果。这相当于PvP中多了一个免费的饰品位。|s1260201|随等级恢复，基于耐力值，会随装备成长。对 PvE 中的输出职业，以及 PvP 中那些\"一点血量都关乎生死\"的时刻都很有影响。" },
                        { t = "p", v = "种族加成" },
                    } },
                    { key = "prof", flow = {
                        { t = "p", v = "《魔兽世界：无限》中的专业技能目前都得到了相当大的加强，使彼此之间的差距缩小了不少——即便过去对法师毫无用处的专业，如今也有了一定价值。这并不意味着它们都会一样强，但现在还为时过早，无法确定未来法术/交互/缩放机制的改动，甚至尚未进行的平衡调整会如何影响各个专业的发挥。这并不妨碍我们对奥法法师可能适用的专业做出有依据的预判（虽然知道未来可能会有所变化）：\n工程学目前相当值得关注，因为它现在拥有诸如氮气推进器这样的工程道具，单凭这一点就让该专业成为了毕业选择。它常被用于短距离爆发移动以大幅提升站桩时间（从而获得输出提升），或完全规避某些机制（让你无需堆叠防御向属性，以另一种方式获得进攻向属性）。此外，它仍会包含典型的爆炸物以及可能的其他功能性道具，这意味着它在团队副本和 PvP 中都始终具有很高的价值。\n裁缝为布甲提供刺绣附魔，但由于我们仍处于 beta 阶段，目前尚不清楚它是类似巫妖王之怒那样在披风上带有特定内置冷却时间的法术强度触发，还是像燃烧的远征/巫妖王之怒中腿部附魔那样只是附带固定法术强度的廉价附魔，又或者是完全不同的形式。如果它是触发型附魔，那么在短时间战斗或与奥术强化等增益效果结合时可能会非常强力；如果只是固定法术强度，那么它就归属于以下三个专业同一类别。\n炼金、附魔和制皮在很大程度上取决于它们提供的总属性加成，以及这些加成彼此之间的比较。" },
                        { t = "tb", v = { { "", "", "法力回复", "制造特定试剂，随后解锁需要在炼金实验室制作的配方。" }, { "", "", "力量提高", "提供可用的铁砧，随后解锁需要在锻造台制作的配方。" }, { "", "", "护甲、全属性与抗性提高", "分解附魔素材更高效，随后解锁需要在奥术锻造台制作的配方。" }, { "", "", "购买试剂", "新增装备修理，随后解锁需要在无政府主义者工作台制作的配方。" }, { "", "", "智力提高", "种下的种子随时间生长出草药，随后可将种子倍增或组合成更稀有的档位。" }, { "", "", "休息经验最多提升一级的5%", "制造特定试剂，随后解锁需要它的配方。" }, { "", "", "近战攻击强度提高", "随时间生成一个普通矿点，随后解锁需要它的配方。" }, { "", "", "2%爆击", "提供野兽追踪，随后新增一个陷阱。" }, { "", "", "精神提高", "制造特定试剂，随后解锁需要它的配方。" }, { "", "", "允许烹饪并提供3个营地功能位", "可容纳5个、随后10个营地功能；2级时还为提升耐力的食物提供解锁。" }, { "", "", "耐力", "治疗药水与解毒剂，随后是治疗药水与药膏。" }, { "", "", "全属性提高8%", "钓鱼技能鱼饵，外加1小时非常见鱼，随后是稀有鱼。" } } },
                        { t = "p", v = "专业技能总览指南" },
                    } },
                },
            },
            fire = {
                updated = "2026/10/05",
                sections = {
                    { key = "changes", flow = {
                        { t = "p", v = "火焰专精获得的新技能不多，但其中最主要的那个——|s400624|——会让|s11366|真正成为火焰法师输出循环中重要的一环。至于|s11078|，它看起来主要是个练级用的技能。最后，|s1237313|，虽然它同样造成火焰伤害，但目前还很难说它对火焰专精是否真正有用，因为这取决于该法术未来的数值成长和联动机制，而这些我们暂时还无法测试。" },
                        { t = "tb", v = { { "|s400624|", "最多可叠加三层，每当你用非周期性法术打出两次暴击便可获得一层。每层会使|s11366|的施法时间缩短25%。" }, { "|s11078|", "使火冲击的冷却时间缩短2秒。击杀一个等级与你相近的怪物后，你的下一个火冲击暴击几率提高50%。" }, { "|s1237313|", "发射一枚法术飞弹，造成冰火伤害，并对敌人同时施加减速效果和周期性伤害效果。" } } },
                        { t = "tb", v = { { "|s11119|", "你的法术暴击会使目标燃烧，在4秒内受到相当于该法术伤害40%的伤害。现在这完全是一个属于个人的伤害技能，不会与其他法师的点燃叠加，也就是说你无法再持续“滚动”点燃了。" }, { "|s11095|", "现在改为个人效果，不再是全团都能受益的目标减益；它只会增强你自身的火焰伤害。" }, { "|s11129|", "每命中一次，暴击几率便提高10%，直到你用火焰法术打出3次暴击为止。" }, { "|s10216|", "在目标区域造成一些群体伤害，随后留下一片地面效果，在8秒内对区域内的敌人持续造成伤害。" } } },
                    } },
                    { key = "viability", flow = {
                    } },
                    { key = "sw", flow = {
                        { t = "p", v = "火焰法师的强度需要相当多的装备来支撑，因为它需要相对稳定的暴击才能发挥大多数技能联动。即便装备相当出色，在达到专精上限方面也常常非常依赖运气——这取决于玩家对这种游戏风格的看法，可以是让人喜爱，也可以是让人厌恶的点。以当前的状态来看，它的操作手感也有些别扭，因为|s400624|目前游戏内的是一个新版天赋，无法让你瞬发炎爆术，只会缩短其施法时间，从巫妖王之怒版本（该天赋加入的版本）起就存在的专精流畅感基本上被破坏了。" },
                        { t = "good", v = { "高伤害潜力- 火焰通常是游戏中成长性最高的专精之一。由于依赖暴击，其数值通常针对满级满装进行平衡。也就是说，当你达到那个阶段时，伤害通常非常出色。", "运气好时手感极佳- 当暴击连续触发、各项要素完美契合时，作为法师的体验是无与伦比的。" } },
                        { t = "bad", v = { "依赖运气- 虽然这可以是优点，但对于那些希望对自己的表现和输出拥有更多掌控感的玩家来说，这是该专精的一大缺点。", "别扭的输出循环- 由于热门天赋|s400624|的改动，它不再拥有瞬发炎爆术，而是改为每层提供少量施法时间缩短，削弱了玩家在未来资料片中喜爱的由该天赋带来的机动性。", "依赖装备- 虽然这常常是该天赋专精成长性出色的原因，但也意味着如果你想在装备未成型时玩它，或是在装备对天赋专精并不友好的团本里玩，它的伤害输出很容易大幅落后。" } },
                    } },
                    { key = "beginner", flow = {
                        { t = "ul", v = { { text = "用魔杖收掉残血目标；" }, { text = "在暴击率较高时使用火焰冲击来拉住下一只怪物。" } } },
                        { t = "p", v = "与经典《魔兽世界》中的其他法师天赋专精类似，《魔兽世界：无限》中的火焰天赋起初感觉非常简单；至于以后是否会变得更复杂，目前尚不清楚。它可能会保持现在这样的简单玩法：用火球术叠到3层热力迸发，然后施放一次炎爆术。同时还要保持强化灼烧的减益效果始终生效，在持续时间较长的战斗中维持住。" },
                        { t = "p", v = "目前还无法得知霜火箭在该天赋专精中的影响，因为该法术的交互效果及潜在伤害尚未明确，Beta测试中也暂不可用。" },
                        { t = "p", v = "在练级时，这天赋专精的体验很简单，所用火焰就是|s11078|在转到下一个目标时，尽量获得一次暴击，使用火焰冲击作为起手。这样可以让你击杀当前敌人后，对下一个目标施放炎爆术，再用火焰冲击获得更高的暴击几率。在非常低的等级时，你可以直接用法杖把敌人击杀，然后用觉醒之火 火焰冲击开启下一个目标的战斗，如此循环：" },
                        { t = "p", v = "如果在初期点出奥术天赋中的魔杖专精，可以进一步提升这个流程，因为该天赋能进一步提高魔杖伤害；再加上现在魔杖也拥有法术强度系数，这让它在练级时变得非常强力。" },
                        { t = "p", v = "同样值得一提的是，在低等级时裁缝装备以及副本和任务装备更加重要，因为所有法术的基础伤害都被削弱了，需要一定的法术强度才能恢复到经典《魔兽世界》中我们熟悉的强度。" },
                        { t = "p", v = "在副本中，群体伤害一如既往地出色，特别是现在还能用圣骑士作为坦克，让你在很低的等级副本中就能开始使用AoE技能。这需要一定的适应，才能保证在副本中法力值始终充裕；具体做法是：预读炎爆术后频繁使用法术技能，并利用前一个怪物死亡时触发的觉醒之火效果，把法力值留给更值得的AoE场合——先用火焰冲击配合冲击再施法术。" },
                    } },
                    { key = "systems", flow = {
                        { t = "ul", v = { { term = "点燃", text = "- 是火焰法师天赋的核心机制之一。当玩家用非周期性法术造成暴击时，会将 40% 的伤害转化为持续性伤害效果（DoT）。过去这一机制较为复杂，需要团队配合，因为每个玩家的点燃效果会叠加成一个巨大的 DoT；而在《魔兽世界：无限》中，它变成了纯个人机制，与未来版本的魔兽世界一致。这使得该天赋变得完全被动，无需调整任何玩法。总体而言，这让该专精对绝大多数玩家来说更加简单易上手。" }, { term = "热力迸发", text = "- 这是与以往及未来版本的主要区别；只要用火焰系法术造成暴击就能触发该效果（不再需要连续两次暴击）。此外，它可使炎爆术的施法时间每层缩短 25%，最多叠加 3 层。这与过去天赋的“瞬发”效果不同。叠加这些触发效果，再用主法术，然后接一发快速施法的炎爆术，将是输出循环的关键。" }, { term = "强化灼烧", text = "- 是你的个人减益，给目标挂上后，可使火焰系法术对其造成的伤害提高 15%，最多可叠满，这是最大化伤害的关键。务必保持该减益不间断，尤其在首领战中不能让它断掉。" } } },
                        { t = "p", v = "虽然火焰法师的玩法非常简单，但有以下两个需要时刻留意的机制：" },
                    } },
                    { key = "races", flow = {
                        { t = "p", v = "除了原有的种族与职业组合之外，法师现在还可以是部落方的兽人，以及联盟方的天裔精灵。虽然这两个组合很有意思，但它们并不会盖过原有组合，因为所有种族特长都经过了重做。目前还很难判断哪种组合在满级强更出色，因为有太多未知因素。在测试服中，每个组合都有各自的优势，所以现在不用太纠结选择；不如先挑一个你觉得在外观或主题上有趣的组合。" },
                        { t = "races", v = { { race = "人类", side = "alliance", mark = "tick" }, { race = "侏儒", side = "alliance", mark = "tick" }, { race = "亡灵", side = "horde", mark = "tick" }, { race = "巨魔", side = "horde", mark = "tick" } } },
                        { t = "ul", v = { { text = "|s1259817|:" }, { text = "|s20591|:" }, { text = "|s20593|:" }, { text = "|s20589|:" }, { text = "|s1259718|:" }, { text = "|s20600|:" }, { text = "|s20597|:" }, { text = "|s20598|:" }, { text = "|s1259705|:" }, { text = "|s1259707|:" }, { text = "|s1259416|:" }, { text = "|s1259710|:" }, { text = "|s20574|:" }, { text = "|s20572|:" }, { text = "|s1299026|:" }, { text = "|s20573|:" }, { text = "|s20554|:" }, { text = "|s1260270|:" }, { text = "|s20557|:" }, { text = "|s20555|:" }, { text = "|s20577|:" }, { text = "|s5227|:" }, { text = "|s7744|:" }, { text = "|s1260201|:" } } },
                        { t = "p", v = "无限服新增的职业-种族组合" },
                        { t = "h4", v = "联盟侏儒" },
                        { t = "p", v = "|s1259817|是侏儒获得的新主动冷却技能，除了伤害提升之外，还附带法力值减免效果。不错，但除了伤害提升本身之外，并没有特别大的意义——可以与燃烧一起使用，让点燃稍微高一点。|s20589|可以解除定身和减速效果。在 PvP 中你会每次都用。|s20591|直接提高法力值，而非智力。|s20593|不再提供额外的等级加成，而是提高工程学小装置的效果。" },
                        { t = "p", v = "种族加成" },
                        { t = "p", v = "人类" },
                        { t = "p", v = "|s1259718|是一个强大的 PvP 种族特长，可以让法师在除了闪现术之外还能解除昏迷效果。|s20597|现在也能让法师受益——装备单手剑时暴击几率提高 2%。精神属性在练级和游戏进程中都非常实用，搭配法师护甲后能在战斗和施法过程中提高法力值回复。|s20600|反潜。视情况而定，但能帮助你赢得决斗。" },
                        { t = "p", v = "种族加成" },
                        { t = "p", v = "高阶天裔" },
                        { t = "p", v = "|s1259705|是该新种族的种族特长，能在 15 秒内将法力值和生命值的回复速度提高 100%。对于高强度施法时法力值压力较大的法师来说，后期可能会有用——但相比侏儒的法力池增大等种族特长，它显得较为平庸。|s1259707|同样可能相关，主要取决于你所对抗的敌人和未来的团队副本。" },
                        { t = "p", v = "|s1259710|最为值得关注，它提供 1% 的法术急速。目前还难以判断它与其他种族特长相比，后期究竟有多大的价值。" },
                        { t = "p", v = "种族加成" },
                        { t = "h4", v = "部落" },
                        { t = "p", v = "兽人" },
                        { t = "p", v = "|s20572|也是新增的，可以为施法者提供法术强度。|s20573|减少昏迷效果的持续时间。盗贼对此很头疼。|s1299026|是另一个强大的PvP主动爆发技能，可以解除诅咒和有害效果，对法师来说基本没什么用，因为我们自己有|s475|，不过它还能在接下来的8秒内减少受到的魔法伤害。|s20574|毫无用处，因为我们很遗憾不能用斧头。" },
                        { t = "p", v = "种族加成" },
                        { t = "p", v = "巨魔" },
                        { t = "p", v = "巨魔法师依然有一席之地；其种族特长稍有变化|s20554|该效果并不附带提高施法速度部分的血量缺失，而是每次直接提供10%。我们还可以使用|s20557|，实用性取决于具体场景——如果对手是野兽则效果拔群，否则毫无价值。它的价值很大程度上取决于当时相关的内容是什么。|s1260270|现在变为引导型法术，在6秒内恢复最大生命值的50%，这一点非常实用，因为此前除了绷带外我们没有任何此类防御手段。" },
                        { t = "p", v = "种族加成" },
                        { t = "p", v = "亡灵" },
                        { t = "p", v = "|s20577|现在恢复法力的同时也恢复生命值，进一步提升了它在任务时本就不错的减少坐地板时间的能力。|s5227|其实没多大价值。不过法师PvP最强的种族特长通常是|s7744|，它能解除或免疫魅惑、恐惧和睡眠效果。这在PvP中相当于白送一个饰品栏位。|s1260201|随耐力提升，因此会随装备成长。在PvE中对DPS有影响，在PvP中则在那些“差1点血就决定生死”的时刻发挥作用。" },
                        { t = "p", v = "种族加成" },
                    } },
                    { key = "prof", flow = {
                        { t = "p", v = "《魔兽世界：无限》中的专业目前都被大幅增强，使它们之间的差距缩小了不少——就连过去对法师毫无帮助的专业现在也有了一定相关性。这并不意味着它们都一样强，但考虑到未来的法术/互动/成长，甚至尚未完成的平衡性调整，现在判断哪个表现最好还为时过早。不过这并不妨碍我们对火焰法师可能有用的选择做出有根据的推测（同时清楚未来可能变化）：\n工程学目前相当有趣，因为它现在拥有像硝基推进器这样的工匠装置，仅凭这些就已经让该专业成为最佳选择。它被用于短时间爆发移动来获得大量输出时间（从而提高DPS），或完全规避某个否则需要你堆更多防御属性的机制（以迂回的方式为你换来进攻属性）。此外，它仍然包含典型的炸药，可能还有一些其他功能性的东西，这意味着它在团本和PvP中始终具有极高的价值。\n裁缝为布甲提供刺绣附魔，但由于目前只是Beta，我们还不知道这会不会像WotLK那样，是披风上带有特定内置冷却的法术强度触发效果，还是像TBC/WotLK那样只是便宜的附魔（如带有固定法术强度的腿部附魔），亦或是完全不同的东西。如果是触发型的，它在短时间战斗中或与燃烧等增益搭配时可能非常出色，因为它能增强那些必定暴击的伤害；如果只是固定法术强度，那它就与接下来3个专业归为同一类。\n炼金、附魔与制皮将在很大程度上取决于它们提供的总属性加成，以及日后这些加成之间的对比。" },
                        { t = "tb", v = { { "", "布料刺绣——法术强度、攻击强度或耐力，共5个等级。可从人形生物身上获取额外布料。" }, { "", "戒指附魔 - 法术强度、攻击强度或耐力，共5个等级。" }, { "", "没有属性加成，但有各种装置、工匠和炸弹。" }, { "", "药剂学：药剂和混合药剂的持续时间更长、效果更强。点金石可以升级。" }, { "", "天生特质：抵抗所有魔法系，强度随技能提升。" }, { "", "对野兽和龙类敌人造成的伤害提高5%。" }, { "", "+5%总生命值。" }, { "", "护腕护甲片（法术强度/攻击强度/耐力）、最高提供+5%坐骑速度的马鞍、背包。" }, { "", "皮带扣，提供全属性，共分4档。附带全部修理，冷却8小时，2级时缩短为4小时。" }, { "", "几乎所有制造的食物都提供属性加成和少量经验值加成。" }, { "", "绷带的治疗量已调整为匹配TBC耐力数值缩放。" }, { "", "熔岩钓鱼、鱼竿盒、黑口村日常任务、咸鱼头衔。" } } },
                    } },
                },
            },
            frost = {
                updated = "2026/09/22",
                sections = {
                    { key = "changes", flow = {
                        { t = "p", v = "冰霜不再只是寒冰箭了！冰枪术将在技能组中第二次亮相，其运作方式与其他版本基本相同（与燃烧的远征版本最为接近）。这让输出循环有了些新内容，再加上从巫妖王之怒移植过来的寒冰指，你将拥有一套以寒冰箭起手、以冰枪术打出巨额伤害收尾的触发反应型输出循环（还能给你留出一些移动时间）。" },
                        { t = "tb", v = { { "冰枪术", "对一名敌方目标造成冰霜伤害。对被冻结的目标造成的伤害提高300%。这个法术是从魔兽世界的另一条时间线移植而来的，是对我们技能组的可喜补充，它很可能是你输出循环中的主要反应点，用来利用冻结效果及其收益。" }, { "寒冰指", "使你的冰冷效果有15%的几率赋予你寒冰指效果，将你的下1次施法视同目标已被冻结。持续15秒。这将是你PvE中的主要触发来源，使你能够使用冰枪术，或对那些本无法被冻结的敌人（大多数首领）利用其他天赋带来的冻结收益！" } } },
                        { t = "p", v = "相比经典旧世的三大改动在于冰霜及其副天赋树的天赋重构，但最大的很可能是暴风雪减速效果的削弱，开发者大概是希望借此减少法师多年来在经典旧世中沿用的群体伤害刷怪打法。" },
                        { t = "tb", v = { { "强化暴风雪", "为你的暴风雪法术附加冰冷效果。该效果使目标的移动速度降低15/25/40%，持续1.5秒。相比原先的30/50/65，这是对暴风雪减速效果的一次重大削弱，与经典旧世相比，很可能会对群体伤害练级和刷怪战术产生重大影响。" }, { "冰霜天赋树改动", "这里的变化很多：命中天赋要多投2点，整体命中却少了1%；碎裂现在变成3点天赋，效果不变；极寒在天赋树中的位置比以前更靠下；此外还有不少调整。希望你对旧版没有太深的感情！" }, { "火焰与奥术天赋树改动", "与上文类似，火焰和奥术也有许多改动，其中一些暗示了可能出现围绕奥术飞弹弹幕的构筑，或是冰霜火箭的回归！" } } },
                    } },
                    { key = "viability", flow = {
                        { t = "p", v = "在《魔兽世界：无限》中,既定设计目标之一是让每个天赋在任意内容中都具备可用性,到目前为止冰霜专精感觉在20级之前都很合适。随着进度推进,我会更新本帖,但三个法师专精整体上彼此相当,与其他九个职业相比也没有明显落后。" },
                    } },
                    { key = "sw", flow = {
                        { t = "p", v = "冰霜有一个鲜明的定位——远程减速的大师级施法者,也是一名全方位的坚韧施法者,在群体伤害和单体战斗中同样有效。我们总体上存在一些不足之处,即自身的续航能力不佳,缺乏奥术和火焰那样的爆发能力。另外一个在经典旧世中经常出现的较大弱点是,怪物免疫或抵抗状态可能让我们在霜火箭可用时更倾向于使用它,或在某些战斗中不把冰霜作为主天赋。" },
                        { t = "good", v = { "难以击杀- 冰霜法师是《魔兽世界》中最典型的安全型施法者;冰霜法术会减速敌人,使风筝和伤害输出更加轻松,且自身毫无风险。冰甲术和寒冰屏障进一步增强了不可忽视的防御能力。", "团队功能性- 与其他法师不同,冰霜法师可以轻松使用急速冷却,瞬间让冰霜新星和寒冰屏障等技能的效果翻倍,在关键时刻能够决定局势。", "机动性- 与经典旧世的输出循环相比,寒冰箭的加入带来了许多即插即用发的瞬发公共冷却时间,可以用于优化移动。", "群体伤害- 法师在群体伤害方面堪称霸主;冰霜法师很好地契合了这一特点,招牌群体伤害法术附带强力减速效果。" } },
                        { t = "bad", v = { "自我治疗- 冰霜法师在《魔兽世界》历史上向来有些难以应对持续性伤害;《魔兽世界：无限》不打算改变这一点,我们仍然缺乏合适的战斗中生命恢复技能。", "爆发- 我们天赋树内的冰霜法师缺少像奥术强化或燃烧这样合适的冷却爆发技能。", "免疫敌人- 冰霜法师极度依赖敌人能够受到冰霜伤害，且不会拥有提升过的抗性或免疫。当敌人拥有冰霜免疫时，我们投入的大量天赋点数都会浪费，因为我们不得不改用其他法术系。" } },
                    } },
                    { key = "beginner", flow = {
                        { t = "p", v = "冰霜的输出循环很可能非常简单，不过要想把收益压榨到极限，可能还需要一定的快速反应能力。这使得它非常适合那些想要稳定且有趣的玩法、又不想使用过于复杂循环的玩家。话虽如此，如果你可能在处理触发时反应不过来，冰霜法师可能会是个问题，但请注意，目前仍处于测试服早期，在正式上线前或上线后我们了解更多时，很多内容都可能会改变！" },
                    } },
                    { key = "systems", flow = {
                        { t = "p", v = "法师在《魔兽世界：无限》中拥有一套全新的职业系统，即我们可以解读卷轴，并（有可能）研究它们以学会制作卷轴。这第二部分尚未确认，因为曾在测试服出现但已被移除。与盗贼的锁箱类似，卷轴会掉落给玩家，只有法师可以使用其解读卷轴的能力来解锁额外的增益和效果。" },
                    } },
                    { key = "races", flow = {
                        { t = "p", v = "法师在《魔兽世界：无限》中有6个种族可选：人类、侏儒、天裔（联盟），以及兽人、亡灵和巨魔。" },
                        { t = "races", v = { { race = "人类", side = "alliance", mark = "tick" }, { race = "侏儒", side = "alliance", mark = "tick" }, { race = "亡灵", side = "horde", mark = "tick" }, { race = "巨魔", side = "horde", mark = "tick" } } },
                        { t = "p", v = "无限服新增的职业-种族组合" },
                        { t = "p", v = "显然，现在还处于测试服早期，无法正确理解种族改动；以下只是一些初步看法。法师在《魔兽世界：无限》中有6个种族可选：人类、侏儒、天裔（联盟），以及兽人、亡灵和巨魔。天裔法师在练级时非常强力；依靠这个种族特长我大量减少了喝水次数，尤其是在他们出生地几乎一直保持激活。巨魔和兽人感觉都是快速输出的强力候选；同样，其他选项也并非明显不好。值得一提的是，由于部分种族对特定敌人类型有明确的5%伤害加成，因此也会自然存在一个针对该战斗的“最佳种族”。下面我将讨论每种种族的功能性优缺点，但输出能力的问题其实更应该留到以后再考虑（很可能要到正式上线之后很久才会有明确答案）。" },
                        { t = "h4", v = "联盟" },
                        { t = "p", v = "人类- 人类对法师来说略显多余，因为我们可以用闪现解除昏迷，而且警觉对我们来说也没那么有用——我们可以用魔爆术来探查隐身敌人。侏儒- 逃脱高手与闪现术也有一定功能重叠，但工程学技能可以在关键时刻避免施法失败。高阶天裔- 滑翔与缓落术同样存在功能重叠，不过它不需要材料。在天裔区域练级时，奔逸之纹非常实用，但在此之后作用就不大了。" },
                        { t = "h4", v = "部落" },
                        { t = "p", v = "兽人- 与上面提到的联盟种族类似，对于一个能自行解除诅咒的职业来说，免疫昏迷也有些功能重叠，虽然目前还不清楚诅咒具体指哪些；法术伤害减免也很不错，昏迷持续时间缩短同样有用。亡灵- 被遗忘者的意志是这里第一个基本没有功能重叠的选项，它实实在在地帮我们省去使用冰霜新星或承受失控后果的麻烦。食尸和墓穴之触在练级及之后都很实用，可以减少停顿时间并帮助维持状态。巨魔- 被动与主动的生命值回复都能在一定程度上弥补我们在生命恢复方面的弱点，但主动技能要求我们不受到伤害，而偏偏在我们最需要它的时候最难达成这个条件。" },
                    } },
                    { key = "prof", flow = {
                        { t = "p", v = "我一直推崇工程学，因为它能在战斗中为你提供各种选择和灵活性；不过，裁缝和附魔可以通过装备的形式在练级期间提供强大的力量加成。到目前为止，魔杖看起来非常、非常强力。" },
                    } },
                },
            },
        },
        WARLOCK = {
            affli = {
                updated = "2026/10/02",
                sections = {
                    { key = "changes", flow = {
                        { t = "p", v = "术士在学会第一个新技能后会首先注意到，|s348|，现在遭遇伤害的技能可以造成暴击了！这让痛苦天赋能够更好地受益于游戏中主要的增伤属性之一。造成伤害的诅咒被改造成了灾厄。灾厄原本是另一类技能；例如|s11713|可以与|s1311680|同时使用。|s1316697|于灾厄与咒文之间进行选择|s25307|的伤害|s18271|同时使用。" },
                        { t = "tb", v = { { "|s1225177|", "" }, { "|s437032|", "" }, { "|s403511|", "" }, { "|s427712|", "" }, { "|s1310949|", "" }, { "|s1316697|", "" } } },
                        { t = "ul", v = { { text = "的伤害来为其他专精提供增益。恶魔学奇术对战或毁灭对战指南中了解其他专精技能与天赋的详细信息。" } } },
                        { t = "p", v = "|s18174|现在为所有属性提供命中并降低仇恨。这让它成为大多数对战对战专精的关键天赋。|s11713|并且|s1311680|同时使用。|s1311680|现在影响所有魔法学派，包括奥术、自然和神圣法术！|s11689|现在随精神缩放，略微提升了该属性的实用性。|s11717|不再提高被诅咒目标造成的伤害。|s17810|现在还会提高造成的伤害。|s11675|现在在造成伤害时也有几率产生灵魂碎片，而不再仅仅是目标死亡时。" },
                        { t = "tb", v = { { "|s11713|", "" }, { "|s603|", "" }, { "|s11689|", "" }, { "|s11717|", "" }, { "|s18174|", "" }, { "|s17810|", "" }, { "|s18827|", "使你的痛苦诅咒造成的伤害提高10%。" }, { "|s18223|", "" }, { "|s17783|", "" }, { "|s17804|", "" }, { "|s18271|", "" } } },
                    } },
                    { key = "viability", flow = {
                        { t = "p", v = "痛苦在团队副本中表现出色。诅咒不再限制你使用|s11713|或|s603|。与此同时，|s17793|不再被其他施法者消耗。除此之外，痛苦的自愈能力在PvP中大有帮助，使旧的吸取生命/灵魂链接流派（|s18881|+|s19028|）更为强大。" },
                    } },
                    { key = "sw", flow = {
                        { t = "p", v = "痛苦术的主要伤害来源是周期性伤害，因此拥有极强的顺劈潜力，因为我们可以对多个目标预铺大量伤害。然而这种预铺也意味着面对快速死亡的敌人时缺乏爆发伤害。痛苦术在有两个或更多目标的长线战斗中表现出色，此时我们的周期性伤害法术才能发挥全部潜力。急速不会影响持续性伤害技能或吸取类引导法术。这意味着与恶魔学识不同，后者使用|s17924|或毁灭系搭配|s1293813|，急速对我们来说很可能是浪费的属性。" },
                        { t = "good", v = { "顺劈- 给每个目标挂上周期性伤害，使我们拥有游戏中最优秀的顺劈能力之一，且不在乎怪物分散程度", "长线战斗- 周期性伤害能够完整跳出，这正是该专精脱颖而出的地方" } },
                        { t = "bad", v = { "缺乏爆发- 预铺的伤害仍需等待跳出；难以抢杀低血量怪物", "短线战斗- 周期性伤害需要时间才能打出全部伤害" } },
                    } },
                    { key = "beginner", flow = {
                        { t = "p", v = "这是上手周期性伤害玩法的完美起点。你能享受到在多个怪物之间切换并追踪多个周期性伤害的满足感，又不必面对后续（还是说更早？）资料片中快照机制的复杂度。大多数周期性伤害会在你获得增益或对目标施加减益时动态更新伤害；只要确保每个目标都正确挂上了周期性伤害，你就完成了90%。" },
                    } },
                    { key = "systems", flow = {
                        { t = "p", v = "痛苦天赋亲和力较低，玩法非常直接——在目标身上挂上周期性伤害效果，并使用吸取类法术填充伤害循环。痛苦天赋中的核心动态效果来自天赋选择|s17804|。当完全点出后，它会根据目标身上痛苦法术的数量，最多提升你的|s11700|、|s11675|以及|s1316697|法术伤害达 36%。这意味着始终在你的主要目标身上保持至少 3 个痛苦系效果（诅咒、灾祸、|s25311| 等），以便最大化伤害输出。" },
                    } },
                    { key = "races", flow = {
                        { t = "p", v = "新增的种族/职业组合现在包括巨魔术士。多数种族特长也被改动过，使种族选择更加平衡但仍各具特色。对于术士来说，现在还很难判断哪个种族最强。外形条件请随意选择你喜欢的种族（比如你觉得最好看的——你得盯着它看很久）。" },
                        { t = "races", v = { { race = "人类", side = "alliance", mark = "tick" }, { race = "侏儒", side = "alliance", mark = "tick" }, { race = "兽人", side = "horde", mark = "tick" }, { race = "亡灵", side = "horde", mark = "tick" } } },
                        { t = "ul", v = { { text = "|s1259817|：" }, { text = "|s20591|：" }, { text = "|s20593|：" }, { text = "|s20589|：" }, { text = "|s1259718|：" }, { text = "|s20600|：" }, { text = "|s20597|：" }, { text = "|s20598|：" }, { text = "|s20574|：" }, { text = "|s20572|：" }, { text = "|s1299026|：" }, { text = "|s20573|：" }, { text = "|s20554|：" }, { text = "|s1260270|：" }, { text = "|s20557|：" }, { text = "|s20555|：" }, { text = "|s20577|：" }, { text = "|s5227|：" }, { text = "|s7744|：" }, { text = "|s1260201|：" } } },
                        { t = "p", v = "无限服新增的职业-种族组合" },
                        { t = "h4", v = "联盟侏儒" },
                        { t = "p", v = "|s1259817|是侏儒获得的新主动伤害爆发冷却时间技能。|s20589|可以解除定身和减速效果。每次 PvP 都要使用它。此外，|s20591|直接增加法力值，而非智力。|s20593|不再提供额外等级；改为提高工程学装置的效果。" },
                        { t = "p", v = "种族特长" },
                        { t = "p", v = "人类" },
                        { t = "p", v = "|s1259718|是一个强大的PvP种族特长，能让术士解除眩晕效果。|s20597|现在对术士也有益，装备剑时能提高2%的暴击几率。精神对我们影响不大，除了略微提升|s11689|，这使得|s20598|优势更小。|s20600|侦测潜行。虽然要看情况，但能赢下决斗。" },
                        { t = "p", v = "种族特长" },
                        { t = "h4", v = "部落" },
                        { t = "p", v = "兽人" },
                        { t = "p", v = "|s20572|现在的作用与后续资料片一致，并且还会给施法者提供法术强度。|s20573|缩短昏迷持续时间。盗贼对此深恶痛绝。|s1299026|是另一个很棒的PvP主动使用冷却技能，能移除诅咒和灾厄，并使我们免疫这些效果，同时在接下来8秒内降低受到的魔法伤害。|s20574|毫无用处，因为遗憾的是我们无法使用斧。" },
                        { t = "p", v = "种族特长" },
                        { t = "p", v = "巨魔" },
                        { t = "p", v = "巨魔是新种族！|s20554|终于让术士的施法速度更快了。遗憾的是，它不影响周期性伤害效果或引导法术，降低了其伤害潜力。|s20557|对野兽造成的伤害提高5%。它是那种确保巨魔在野兽Boss战中的输出排名始终名列前茅的种族特长之一。|s1260270|是绷带的强化版；它必须引导且容易被打断。如同|s20577|对于亡灵来说，这极大地减少了术士在任务或地下城中的休整时间；|s11689|恢复至满法力值，使用再生，继续前进。" },
                        { t = "p", v = "种族特长" },
                        { t = "p", v = "亡灵" },
                        { t = "p", v = "|s20577|现在同时恢复法力和生命值，进一步提升了其在任务过程中本就不错的减少休整时间的能力。|s5227|对术士来说并没有太大意义，因为他们已经能获取|s5697|。不过术士PvP最强的种族特长是|s7744|，可以解除或免疫魅惑、恐惧和沉睡效果，等于在PvP中免费多了一个饰品栏位。|s1260201|随耐力成长，因此会随着装备提升而增强。在PvE中提升DPS，在PvP中那些\"一丝血也是生与死\"的时刻也很有用。" },
                        { t = "p", v = "种族特长" },
                    } },
                    { key = "prof", flow = {
                        { t = "p", v = "目前为时尚早。Beta测试刚刚开启，所有专业的配方表都尚未公布，所以我们还不知道什么最强。在正式上线前，所有内容都可能变动。所有专业都已随《魔兽世界：无限》重做。每个专业现在都会提供一项收益，例如魔法抗性或额外生命值。配合可获得最高的预期伤害潜力，因为有炸弹和裁缝刺绣加成。另一方面，配合也很不错，因为你 可以分解自己制作的物品。由于仍处于Beta阶段，请随意尝试所有专业，找到最适合自己的。" },
                        { t = "tb", v = { { "", "", "法力回复", "制造特定试剂，随后解锁需要在炼金实验室制作的配方。" }, { "", "", "力量提高", "提供可用的铁砧，随后解锁需要在锻造台制作的配方。" }, { "", "", "护甲、全属性与抗性提高", "分解附魔素材更高效，随后解锁需要在奥术锻造台制作的配方。" }, { "", "", "购买试剂", "新增装备修理，随后解锁需要在无政府主义者工作台制作的配方。" }, { "", "", "智力提高", "种下的种子随时间生长出草药，随后可将种子倍增或组合成更稀有的档位。" }, { "", "", "休息经验最多提升一级的5%", "制造特定试剂，随后解锁需要它的配方。" }, { "", "", "近战攻击强度提高", "随时间生成一个普通矿点，随后解锁需要它的配方。" }, { "", "", "2%爆击", "提供野兽追踪，随后新增一个陷阱。" }, { "", "", "精神提高", "制造特定试剂，随后解锁需要它的配方。" }, { "", "", "允许烹饪并提供3个营地功能位", "可容纳5个、随后10个营地功能；2级时还为提升耐力的食物提供解锁。" }, { "", "", "耐力", "治疗药水与解毒剂，随后是治疗药水与药膏。" }, { "", "", "全属性提高8%", "钓鱼技能鱼饵，外加1小时非常见鱼，随后是稀有鱼。" } } },
                    } },
                },
            },
            demo = {
                updated = "2026/10/02",
                sections = {
                    { key = "changes", flow = {
                        { t = "p", v = "随着31点终极天赋的加入,|s425464|,你现在终于可以让恶魔参战,同时受益于|s18788|。恶魔学识术士最大的变化是宠物现在会按玩家的属性缩放,你可以在角色面板中查看具体的缩放比例。|s440870|让你可以更快地施放|s17924|,不消耗灵魂碎片,并缩短冷却时间。虚空行者坦克在搭配|s1293695|,时或许有一战之力,但仍有待观察。恶魔学识已不再主要用于通过|s25307|来强化|s18788|另一项重大改动是宠物管理。在经典版中,你可以指挥宠物攻击、跟随或停留。停留已被移至替换为“移动到”,点击后会在光标处的地面显示一个标记,让你指示宠物移动到该位置。" },
                        { t = "p", v = ",的伤害。" },
                        { t = "tb", v = { { "|s1235316|", "" }, { "|s1225214|", "" }, { "|s440870|", "" }, { "|s1293695|", "" }, { "|s1225217|", "" }, { "|s412732|", "" }, { "|s425464|", "" }, { "|s437169|", "" } } },
                        { t = "ul", v = { { text = "查看痛苦系概览或毁灭 概述指南，了解其他新专精技能和天赋的更多详情。" } } },
                        { t = "p", v = "|s18174|现在为所有职业技能提供命中加成并降低威胁值。这使其成为大多数 PvE 专精的关键天赋。伤害型诅咒与功能型诅咒被拆分，伤害型诅咒变为灾祸。你不再需要在|s11713|和|s1311680|另一项重大改动是宠物管理。在经典版中,你可以指挥宠物攻击、跟随或停留。停留已被移至替换为“移动到”,点击后会在光标处的地面显示一个标记,让你指示宠物移动到该位置。|s18769|的增益效果从 20% 降低至 10%，但在天赋树中的获取节点大幅提前。|s18788|现在持续时间为 2 小时，并且不同恶魔提供的增益有所调整：小鬼：暗影伤害，魅魔：火焰伤害，恶魔猎犬：生命恢复，虚空行者：法力值回复。|s23785|小鬼改为提升火焰伤害，而非降低威胁值；恶魔猎犬改为减少受到的魔法伤害，而非提升全系抗性。|s17953|和|s17728|现在两者均作为武器油使用。" },
                        { t = "tb", v = { { "|s18703|", "" }, { "|s18694|", "" }, { "|s18697|", "" }, { "|s18769|", "" }, { "|s18731|", "" }, { "|s18788|", "" }, { "|s23785|", "" }, { "|s17953|", "" }, { "|s17728|", "" } } },
                    } },
                    { key = "viability", flow = {
                        { t = "p", v = "恶魔学识在团本中表现非常出色。|s425464|让你可以献祭一只宠物，召唤另一只宠物造成伤害。叠加天赋后，你可以在某一系魔法伤害（暗影或火焰）上获得约 30% 的加成。|s440870|在生命值低于 35% 时触发，使你施放的|s17924|不消耗灵魂碎片，施法速度更快且冷却时间缩短。恶魔学识强大的减伤能力在 PvP 中非常实用，使传统的 吸取生命/灵魂链接 配装（|s18881|+|s19028|) 更强的效果。" },
                        { t = "p", v = "一个有趣的天赋是|s1293695|，这是你通过|s17923|对敌人施加的一个减益效果。它会使你的宠物攻击产生额外威胁值并造成更高伤害。通过使用此天赋并在|s17923|，你的宠物很可能成为主要的伤害来源。具体测试将在Beta中进行，以查看它产生的威胁值大小，以及在长期提升宠物伤害方面的可行性。|s25307|之间穿插" },
                    } },
                    { key = "sw", flow = {
                        { t = "p", v = "恶魔学识在理论上提供最高的单体DPS，因为它拥有大量的伤害加成以及你被强化的恶魔带来的额外伤害。随着战斗接近尾声，由于|s440870|，你也会获得额外的伤害。相比其他法系，你更加耐打，因为|s19028|和|s18697|提供了约64%的额外有效生命值。你很大一部分伤害来自你的恶魔。这也意味着如果它们不像它们的主人那样跑出火圈，它们就会死亡。" },
                        { t = "good", v = { "单体目标- 叠加的伤害加成加上强化的恶魔带来的伤害，使其成为游戏中单体最强的专精之一", "造成伤害-|s440870|意为随着战斗临近结束，我们的伤害会持续攀升", "生存能力-|s19028|和|s18697|使我们更加耐打" } },
                        { t = "bad", v = { "依赖宠物- 我们的大量伤害来自四处走动的宠物，团队群体伤害加上站位不佳都可能让它丧命" } },
                    } },
                    { key = "beginner", flow = {
                        { t = "p", v = "恶魔学识能为你提供强力的宠物与出色的生存能力；它是一个非常友好的练级与PvP天赋。在 PvE 内容中，你需要保持宠物存活以最大化输出。这意味着要妥善安排宠物站位，让它避开伤害类机制，这并非总是易事。除此之外，输出循环很简单：保持你的持续伤害法术不断，|s1293695|保持|s17923|作用于主目标，用|s25307|填充，在|s440870|生效时施放|s17924|。" },
                    } },
                    { key = "systems", flow = {
                        { t = "p", v = "恶魔学识专精，顾名思义，核心就是恶魔！这包括宠物管理，比如决定何时上把宝宝投入战斗或如何走位。" },
                        { t = "p", v = "|s18788|强化你恶魔的对立属性。因此，你可以献祭小鬼，召唤魅魔，获得约30%的暗影伤害加成(1.15 × 1.03 × 1.10，分别来自|s18788|，|s23785|，和|s19028|。反过来——献祭上品召唤小鬼——同样获得约30%的加成，但对应的是火焰伤害。" },
                        { t = "p", v = "|s440870|在35%血量以下使用，可获得一段短暂的伤害提升，配合|s17924|。不过该技能有6秒冷却时间，无法像游戏后期那样连续使用。" },
                    } },
                    { key = "races", flow = {
                        { t = "p", v = "就术士而言，现在还为时尚早，无法确定哪个种族收益最大。怎么选都不会错，选你最喜欢的外观就好(比如觉得最好看的那一个——你要盯着它看很久呢)。" },
                        { t = "races", v = { { race = "人类", side = "alliance", mark = "tick" }, { race = "侏儒", side = "alliance", mark = "tick" }, { race = "兽人", side = "horde", mark = "tick" }, { race = "亡灵", side = "horde", mark = "tick" } } },
                        { t = "ul", v = { { text = "|s1259817|：" }, { text = "|s20591|：" }, { text = "|s20593|：" }, { text = "|s20589|：" }, { text = "|s1259718|：" }, { text = "|s20600|：" }, { text = "|s20597|：" }, { text = "|s20598|：" }, { text = "|s20574|：" }, { text = "|s20572|：" }, { text = "|s1299026|：" }, { text = "|s20573|：" }, { text = "|s20554|：" }, { text = "|s1260270|：" }, { text = "|s20557|：" }, { text = "|s20555|：" }, { text = "|s20577|：" }, { text = "|s5227|：" }, { text = "|s7744|：" }, { text = "|s1260201|：" } } },
                        { t = "p", v = "无限服新增的职业-种族组合" },
                        { t = "h4", v = "联盟 侏儒" },
                        { t = "p", v = "|s1259817|对侏儒来说，是一个新的使用后提升伤害的爆发技能。|s20589|可以解除定身并造成减速效果。在 PvP 中你会一直使用它。此外，|s20591|直接提升法力值，而非智力。|s20593|不再提供额外的等级加成；取而代之的是，它会提升工程学道具的效果。" },
                        { t = "p", v = "种族特长" },
                        { t = "p", v = "人类" },
                        { t = "p", v = "|s1259718|是一个强力的 PvP 种族特长，可以让术士解除昏迷效果。|s20597|现在能使术士在装备剑类武器时暴击几率提高 2%。精神对你的影响不大，只是略微提升|s11689|，这使得|s20598|的优势降低。|s20600|能侦测潜行。有一定局限性，但可以赢得决斗。" },
                        { t = "p", v = "种族特长" },
                        { t = "h4", v = "部落" },
                        { t = "p", v = "兽人" },
                        { t = "p", v = "|s20572|现在和后续资料片中的一样，同时给予施法者法术强度。|s20573|缩短昏迷效果的持续时间，盗贼对此非常头疼。|s1299026|是另一个PvP中强力的主动爆发技能，可以驱散诅咒与祸害效果，并使你在接下来的8秒内免疫此类效果，同时减少受到的魔法伤害。|s20574|没有用，因为我们很不幸地无法使用斧头。" },
                        { t = "p", v = "种族特长" },
                        { t = "p", v = "巨魔" },
                        { t = "p", v = "巨魔是新加入的！|s20554|终于让术士的施法速度加快了。可惜的是，它不影响持续伤害效果和引导类法术，限制了其伤害潜力。|s20557|对野兽造成的伤害提高5%。这是一个让巨魔在野兽类首领战中永远登顶伤害统计的种族特长。|s1260270|是强化版的绷带；需要引导施法，且很容易被打断。和|s20577|对亡灵一样，这大幅减少了术士在任务或副本中的下线时间；|s11689|回到满法力值，使用再生，继续推进。" },
                        { t = "p", v = "种族特长" },
                        { t = "p", v = "亡灵" },
                        { t = "p", v = "|s20577|现在除了恢复生命值之外还会回复法力值，在做任务时进一步缩短了本就十分优秀的停手时间。|s5227|对于术士来说并没有太大用处，因为他们已经能够使用|s5697|。然而，术士在 PvP 中最强的种族特长是|s7744|，它可以解除或抵抗魅惑、恐惧和沉睡效果，相当于在 PvP 中多出一个免费的饰品栏位。|s1260201|的收益会随着耐力提升而成长，因此会随着装备提升而变强。在 PvE 中对输出有显著影响，在 PvP 中则是那些“一点血量都很关键”的时刻的关键技能。" },
                        { t = "p", v = "种族特长" },
                    } },
                    { key = "prof", flow = {
                        { t = "p", v = "目前还为时尚早。Beta 刚刚开放，任何专业的配方表都尚未公布，所以我们还不知道什么最强。在临近正式上线之前，请把以下所有内容都视为可能改动。所有专业都已随《魔兽世界：无限》重做。每个专业现在都会为你提供一项收益，例如魔法抗性加成或更高的生命值。配合" },
                        { t = "tb", v = { { "", "", "法力回复", "制造特定试剂，随后解锁需要在炼金实验室制作的配方。" }, { "", "", "力量提高", "提供可用的铁砧，随后解锁需要在锻造台制作的配方。" }, { "", "", "护甲、全属性与抗性提高", "分解附魔素材更高效，随后解锁需要在奥术锻造台制作的配方。" }, { "", "", "购买试剂", "新增装备修理，随后解锁需要在无政府主义者工作台制作的配方。" }, { "", "", "智力提高", "种下的种子随时间生长出草药，随后可将种子倍增或组合成更稀有的档位。" }, { "", "", "休息经验最多提升一级的5%", "制造特定试剂，随后解锁需要它的配方。" }, { "", "", "近战攻击强度提高", "随时间生成一个普通矿点，随后解锁需要它的配方。" }, { "", "", "2%爆击", "提供野兽追踪，随后新增一个陷阱。" }, { "", "", "精神提高", "制造特定试剂，随后解锁需要它的配方。" }, { "", "", "允许烹饪并提供3个营地功能位", "可容纳5个、随后10个营地功能；2级时还为提升耐力的食物提供解锁。" }, { "", "", "耐力", "治疗药水与解毒剂，随后是治疗药水与药膏。" }, { "", "", "全属性提高8%", "钓鱼技能鱼饵，外加1小时非常见鱼，随后是稀有鱼。" } } },
                    } },
                },
            },
            destro = {
                updated = "2026/10/02",
                sections = {
                    { key = "changes", flow = {
                        { t = "p", v = "毁灭曾经专注于尽可能多地造成伤害，使用|s25307|，并切到其他天赋树中获取额外的暗影伤害。时代变了！现在毁灭会深挖自身天赋树，强化火焰伤害并解锁一个新填充技能：|s17959|并转投其他专精天赋树来获取额外的暗影伤害——这种日子一去不复返了！如今毁灭会深入自己的天赋树，强化火焰伤害，并解锁一个新的填充法术：|s1293813|。|s1225228|为单体输出的核心天赋树提供一些顺劈能力。|s426316|为暗影与火焰伤害之间提供一些联动。" },
                        { t = "tb", v = { { "|s1225220|", "" }, { "|s1225228|", "" }, { "|s412751|", "" }, { "|s426316|", "" }, { "|s1293813|", "" } } },
                        { t = "ul", v = { { text = "查阅痛苦概述或恶魔学识概述指南，了解其他新专精技能和天赋的更多细节。" } } },
                        { t = "p", v = "|s17917|现在还会影响所有伤害性法术，而不仅仅是毁灭系法术。|s17793|不再消耗充能，且现在只影响你对目标造成的暗影伤害，不再作用于其他人的伤害。|s18119|提升|s348|的直接伤害，并为|s18932|附加减速效果。|s17959|现在需要5点天赋点而非1点。|s17927|过去仅用于提升|s17923|的暴击几率；现在它还会提高每一个毁灭系法术的伤害。" },
                        { t = "tb", v = { { "|s17917|", "" }, { "|s17793|", "" }, { "|s17778|", "" }, { "|s18119|", "" }, { "|s17959|", "" }, { "|s18135|", "" }, { "|s17927|", "" }, { "|s18932|", "" } } },
                    } },
                    { key = "viability", flow = {
                        { t = "p", v = "毁灭是最贴近经典版术士的天赋分支，除了填充技能从|s25307|变为|s1293813|。它拥有强大的单体伤害能力，以及通过天赋强化的强力群体伤害技能。毁灭的顺劈斩效果不如痛苦，因为无法对每个目标施加周期性伤害，不过你会通过其他途径施加少量伤害|s1225228|。" },
                    } },
                    { key = "sw", flow = {
                        { t = "p", v = "毁灭专精配合两者都能打出出色的爆发|s18932|和|s18871|。它还拥有强大的群体伤害能力，得益于|s11684|和|s11678|，这两者是毁灭系天赋强化的法术。多目标输出不如痛苦系；大多数周期性伤害从痛苦系天赋中获得大量加成，并且|s1225228|部分弥补了这一点。" },
                        { t = "good", v = { "爆发能力- 配合|s18871|和|s18932|你拥有充足的爆发能力", "群体伤害- 所有群体伤害法术都属于毁灭系，并受益于其天赋" } },
                        { t = "bad", v = { "多目标- 暗影伤害没有加成，因此多目标战斗时处于劣势" } },
                    } },
                    { key = "beginner", flow = {
                        { t = "p", v = "毁灭系输出循环简单，对新手非常友好。保持周期性伤害不断，有|s18871|或|s18932|就用，否则施放|s1293813|或|s25307|。" },
                    } },
                    { key = "systems", flow = {
                        { t = "p", v = "|s18932|需求|s348|保持在目标身上并消耗该减益，不过如果你点了5/5|s426316|，则不会消耗。它还能防止|s18871|消耗灵魂碎片，并在施放时提升火焰系伤害。|s18932|通过对应天赋类似地提升暗影系伤害。|s1225228|让你对主目标造成伤害的15%会同时作用于一个次要目标。" },
                    } },
                    { key = "races", flow = {
                        { t = "p", v = "新的种族/职业组合现已加入巨魔术士。大多数种族特长也经过了重新调整，使种族选择更加平衡但仍各具特色。对于术士来说，现在判断哪个种族受益最多还为时尚早。随便选一个你喜欢的种族就行（比如你觉得最好看的那一个——毕竟你要盯着它看很久）。" },
                        { t = "races", v = { { race = "人类", side = "alliance", mark = "tick" }, { race = "侏儒", side = "alliance", mark = "tick" }, { race = "兽人", side = "horde", mark = "tick" }, { race = "亡灵", side = "horde", mark = "tick" } } },
                        { t = "ul", v = { { text = "|s1259817|：" }, { text = "|s20591|：" }, { text = "|s20593|：" }, { text = "|s20589|：" }, { text = "|s1259718|：" }, { text = "|s20600|：" }, { text = "|s20597|：" }, { text = "|s20598|：" }, { text = "|s20574|：" }, { text = "|s20572|：" }, { text = "|s1299026|：" }, { text = "|s20573|：" }, { text = "|s20554|：" }, { text = "|s1260270|：" }, { text = "|s20557|：" }, { text = "|s20555|：" }, { text = "|s20577|：" }, { text = "|s5227|：" }, { text = "|s7744|：" }, { text = "|s1260201|：" } } },
                        { t = "p", v = "无限服新增的职业-种族组合" },
                        { t = "h4", v = "联盟 侏儒" },
                        { t = "p", v = "|s1259817|是侏儒获得的新增主动增伤冷却技能。|s20589|可以解除定身和减速效果。在PvP中你会每次都使用它。此外，|s20591|直接提升法力值，而非智力。|s20593|不再提供额外的等级加成；而是提高工程学小装置的效果。" },
                        { t = "p", v = "种族特长" },
                        { t = "p", v = "人类" },
                        { t = "p", v = "|s1259718|强力PvP种族特长，可让术士解除昏迷效果。|s20597|现在可使术士受益，装备单手剑时暴击几率提高2%。精神属性对我们影响不大，仅略微提升|s11689|，导致|s20598|的优势减弱。|s20600|侦测潜行。属于特定场景技能，但能赢得决斗。" },
                        { t = "p", v = "种族特长" },
                        { t = "h4", v = "部落" },
                        { t = "p", v = "兽人" },
                        { t = "p", v = "|s20572|效果与后续资料片一致，还能为施法者提供法术强度。|s20573|缩短昏迷效果的持续时间。盗贼非常讨厌这个效果。|s1299026|是另一个强力的PvP主动爆发技能，可以移除诅咒与毒咒，使我们免疫这些效果，并在接下来的8秒内降低受到的魔法伤害。|s20574|没什么用，因为我们很不幸无法使用斧头。" },
                        { t = "p", v = "种族特长" },
                        { t = "p", v = "巨魔" },
                        { t = "p", v = "巨魔是新的！|s20554|终于让术士获得了更快的施法速度。可惜的是，它不影响周期性伤害或引导效果，削弱了它的伤害潜力。|s20557|对野兽造成的伤害提高5%。在兽王Boss战中，这是让巨魔始终占据伤害榜首的种族特长之一。|s1260270|是绷带的强化版；必须引导施法，而且很容易被打断。就像|s20577|对亡灵来说，术士在任务或副本中的停顿时间大幅减少；|s11689|法力值回满，激活再生，继续推进。" },
                        { t = "p", v = "种族特长" },
                        { t = "p", v = "亡灵" },
                        { t = "p", v = "|s20577|现在除了生命值还能恢复法力值，进一步缩短了任务过程中本就优秀的停顿时间。|s5227|对术士来说并没有太大价值，因为他们已经可以|s5697|然而，术士 PvP 最强种族特长是|s7744|，它可以解除或抵抗魅惑、恐惧和睡眠效果，相当于 PvP 中多了一个免费的饰品栏位。|s1260201|随耐力成长，因此会随着装备提升而增强。在 PvE 中对 DPS 有影响，在 PvP 中则是那些\"1 点生命也很关键\"的时刻的决定性因素。" },
                        { t = "p", v = "种族特长" },
                    } },
                    { key = "prof", flow = {
                        { t = "p", v = "现在还处于早期阶段。Beta 刚刚开放，所有专业的配方列表都尚未公布，所以我们还不知道哪个最强。在临近上线前，请把以上所有内容视为可能调整。所有专业都已随《魔兽世界：无限》重做。每个专业现在都会提供一种加成，比如魔法抗性或更高的生命值。与裁缝搭配，由于炸弹和布艺刺绣的存在，预计能获得最高的伤害潜力。另一方面，与附魔搭配也很好，因为你可以分解自己制作的物品。由于仍处于 Beta 阶段，建议自由尝试所有专业，看看哪个最适合你。" },
                        { t = "tb", v = { { "", "", "法力回复", "制造特定试剂，随后解锁需要在炼金实验室制作的配方。" }, { "", "", "力量提高", "提供可用的铁砧，随后解锁需要在锻造台制作的配方。" }, { "", "", "护甲、全属性与抗性提高", "分解附魔素材更高效，随后解锁需要在奥术锻造台制作的配方。" }, { "", "", "购买试剂", "新增装备修理，随后解锁需要在无政府主义者工作台制作的配方。" }, { "", "", "智力提高", "种下的种子随时间生长出草药，随后可将种子倍增或组合成更稀有的档位。" }, { "", "", "休息经验最多提升一级的5%", "制造特定试剂，随后解锁需要它的配方。" }, { "", "", "近战攻击强度提高", "随时间生成一个普通矿点，随后解锁需要它的配方。" }, { "", "", "2%爆击", "提供野兽追踪，随后新增一个陷阱。" }, { "", "", "精神提高", "制造特定试剂，随后解锁需要它的配方。" }, { "", "", "允许烹饪并提供3个营地功能位", "可容纳5个、随后10个营地功能；2级时还为提升耐力的食物提供解锁。" }, { "", "", "耐力", "治疗药水与解毒剂，随后是治疗药水与药膏。" }, { "", "", "全属性提高8%", "钓鱼技能鱼饵，外加1小时非常见鱼，随后是稀有鱼。" } } },
                    } },
                },
            },
        },
        DRUID = {
            balance = {
                updated = "2026/09/24",
                sections = {
                    { key = "changes", flow = {
                        { t = "p", v = "在《魔兽世界：无限》中，平衡德鲁伊从经典原型迎来了一次大改：天赋树重新设计，新的装备、专业收益与种族天赋都会影响你的取舍。" },
                        { t = "p", v = "本指南会重点标注这些选择，帮助你在配装与养成时做出判断。" },
                        { t = "p", v = "新技能与天赋方面，平衡德暂时没有新增法术，但天赋树经历了大规模重做。" },
                        { t = "tb", v = { { "|s409813|", "核心天赋：鼓励平衡德在 |s5179| 与 |s8950| 之间交替施放。" }, { "|s1223083|", "延长周期性效果的持续时间：|s8926| +3 秒、|s24977| +2 秒、|s9858| +6 秒、|s25299| +3 秒。" }, { "|s16864|", "转为常驻基础技能，与 |s24858| 配合收益更高。" } } },
                        { t = "p", v = "全职业法术的基础伤害普遍下调，装备上的法术强度相应增加。以下既有技能也有改动：" },
                        { t = "tb", v = { { "|s16814|", "现在还会降低 |s5179| 的法力消耗。" }, { "|s339|", "可在室内施放；点出 |s17245| 与 |s16918| 天赋后可对多个目标施放，伤害可观。" }, { "|s24977|", "移入了平衡天赋树。" }, { "|s16845|", "在天赋树中的位置提前，收益更高。" } } },
                    } },
                    { key = "viability", flow = {
                        { t = "p", v = "平衡德在经典旧世时代一直以伤害疲软著称。本次天赋改动确实带来了提升，但其输出曲线能否支撑团本位置仍不明朗。不过在 PvP 中，深平衡天赋的配点让平衡德更具竞争力。" },
                    } },
                    { key = "sw", flow = {
                        { t = "p", v = "平衡德带来的团本辅助能力少有输出专精能及，但它的输出上限受制于法力，而非天赋。" },
                        { t = "good", v = { "灵活的补位治疗", "为队友提供增益与减益", "可对多个目标进行群体控制" } },
                        { t = "bad", v = { "没有打断技能", "法力续航需要投入大量天赋点" } },
                    } },
                    { key = "beginner", flow = {
                        { t = "p", v = "测试期间这方面的建议随职业调整几经变化，目前平衡德看起来是个相当稳妥的升级选择。循环足够简单，一晚上就能上手，但法力是瓶颈：一次只拉一个怪，对近身的敌人保持 |s339|，战斗间隙宁可喝水也别硬撑。专业在这一版比以往更有分量，剥皮和制皮会对你的旅程提供大量支持，拍卖行买点消耗品也能让前期顺畅不少。武器升级同样重要：法杖从 10 级起就带法伤，在这个阶段比大多数护甲件对你的伤害贡献更大。" },
                    } },
                    { key = "systems", flow = {
                        { t = "p", v = "顾名思义，我们沿着平衡天赋树一路点到底，直达标志性的 |s24858|。沿途优先选择能提升伤害、增加施法距离、缩短施法时间的天赋。经典旧世的平衡德天赋树设计欠佳，而《魔兽世界：无限》的天赋树改动同时改善了法力续航与伤害；|s16864| 现在也是常驻技能。这些变化让这个专精的成长性大幅改善。" },
                    } },
                    { key = "rotation", flow = {
                        { t = "p", v = "《魔兽世界：无限》尚未被完全研究透彻，但玩法大概率与下表相近。" },
                        { t = "tb", v = { { "战斗前", "条件允许时预读 |s5179|。" }, { "保持", "目标身上始终维持 |s8926| 与 |s24977|。" }, { "主循环", "在 |s409813| 期间交替施放 |s8950| 与 |s5179|，以 |s8950| 作为主要伤害技能。" }, { "|s16880| 触发", "利用触发效果大幅加快 |s8950| 的施放。" }, { "移动中", "使用瞬发法术填充（如降级 |s8926| 或 |s24977|），站定后回到正常循环。" } } },
                        { t = "h4", v = "多目标" },
                        { t = "tb", v = { { "2-4 目标", "给两个目标挂上 |s8926| 与 |s24977|，然后继续正常循环。" }, { "5+ 目标", "|s17401| 成为伤害收益技能，应当用于 AOE。" } } },
                    } },
                    { key = "stats", flow = {
                        { t = "ul", v = { { term = "法术伤害", text = "法系的立身之本，为法术提供固定伤害加成。多数伤害法术会按施法者的法术强度获得额外基础伤害（即法术强度系数）。《魔兽世界：无限》更看重武器法强，看到武器升级别错过！" }, { term = "命中", text = "降低法术被抗住概率的关键属性。比施法者高 3 级的敌人（如顶级团本首领）有 17% 的基础法术抵抗，可以压到 1%，即命中上限为 16%。" }, { term = "暴击", text = "提高施法打出暴击的概率。|s16909| 天赋在打出暴击时提升伤害，因此暴击是很有价值的属性。" }, { term = "急速", text = "缩短施法时间。套装加成、|s16880| 与天裔种族天赋是法术急速的来源。" }, { term = "智力", text = "相对次要的属性，提供少量暴击并扩大法力池。" }, { term = "精神", text = "价值较低，基本只有对自己施放 |s29166| 回蓝时才用得上。" } } },
                    } },
                    { key = "races", flow = {
                        { t = "p", v = "《魔兽世界：无限》加入了新的职业种族组合与新的种族天赋，以下是能玩德鲁伊的种族一览。" },
                        { t = "races", v = { { race = "暗夜精灵", side = "alliance", mark = "tick" }, { race = "牛头人", side = "horde", mark = "tick" }, { race = "天裔", side = "both", mark = "star" } } },
                        { t = "p", v = "★ 表示《无限》新增的职业种族组合。" },
                        { t = "p", v = "作为德鲁伊，你现在每个阵营都有两个种族可选。从极限收益角度说，各种族天赋的差异可以忽略：牛头人和暗夜精灵的德鲁伊都比天裔更能打，而高阶天裔的法力续航略好一些。" },
                        { t = "p", v = "掠风天裔（部落）/ 高阶天裔（联盟）是《无限》的新种族：天裔对元素敌人造成额外伤害（|s1259707|），并获得少量被动急速（|s1259710|）。联盟天裔通过 |s1259705| 获得法力与生命回复，部落则通过 |s1259686| 获得 10% 移动速度爆发；两者都能用 |s1259416| 滑翔。" },
                        { t = "h4", v = "联盟" },
                        { t = "p", v = "暗夜精灵：在无限服中通过 |s20582| 获得被动移速与躲闪，通过 |s1259799| 获得短时间内提升暴击的冷却技能，并可用 |s20580| 脱战。死亡后还能靠 |s20585| 加快移动速度。" },
                        { t = "h4", v = "部落" },
                        { t = "p", v = "牛头人：提供一点额外生存能力（|s20550|）；|s20549| 给了你人形状态下没有的实用昏迷。此外 |s1259918| 提供叠加式移速加成，但别被打断移动，否则收益会掉。" },
                        { t = "p", v = "牛头人还能用 |s20552| 制造可采集的新草药，且不需要采药专业。" },
                    } },
                    { key = "prof", flow = {
                        { t = "p", v = "《魔兽世界：无限》重做了专业系统，对平衡德来说专业比大多数专精都重要。裁缝和制皮都提供配装升级，多数是不用追任务或副本掉落就能做出来的小件法伤装备，制皮尤其适合作为配装支撑。想要强力提升，可以参与逶迤补给箱系统，拿几件前期强力散件助力升级。" },
                        { t = "p", v = "附魔和炼金也能支撑升级旅程，但我建议通过拍卖行获取它们的多数收益，比自己做划算。" },
                        { t = "p", v = "平衡德需要尽可能多的法术强度，完全不碰专业会明显拖累表现和体验。两种思路：一是双采集专业，从炼金师和附魔师那里买需要的东西；二是自己学炼金、附魔、制皮或裁缝，自给自足，用额外的伤害更快打怪赚钱。" },
                        { t = "p", v = "个人建议「剥皮 + 制皮」组合。" },
                    } },
                },
            },
            feral = {
                updated = "2026/09/25",
                sections = {
                    { key = "changes", flow = {
                        { t = "p", v = "野性德鲁伊输出玩法的最大变化是对天赋的|s17056|天赋完全重做，移除了原版中能量偷取的输出循环部分。为了弥补这部分能量获取的损失，|s417046|已作为天赋加入，使得|s5217|在使用时为我们回复60点能量；但与原版的能量偷取相比，能量获取仍然存在很大差距。野性德鲁伊的输出能力目前看来有所欠缺，未来很可能进行调整，届时本攻略也会保持更新！" },
                        { t = "p", v = "野性德鲁伊输出方面有相当多的新技能与天赋，而对操作风格影响最大的则是|s417046|和|s417141|这两个天赋。这两个天赋为野性德鲁伊输出提供了主要的核心爆发。|s1223246|和|s1223242|同样是影响力不俗的新天赋，但它们本质上只是提升我们的伤害，并不会影响输出循环。" },
                        { t = "tb", v = { { "天赋——|s417046|", "|s5217|现在可以立即获得 20/40/60 点能量。" }, { "天赋——|s417141|", "使你连击点数生成技能的暴击几率提高 100%。期间清除并免疫恐惧效果，持续 15 秒。" }, { "天赋——|s1223246|", "使你对正在流血的目标的近战技能伤害提高 12%/4%/6%/8%/10%。" }, { "天赋——|s1223242|", "使你的近战技能暴击伤害加成提高 10%/20%。" }, { "天赋——|s1223081|", "使你的法术和技能的周期性伤害与治疗效果提高 1%/2%/3%/4%/5%。" }, { "天赋——|s16819|", "使你的命中几率提高 2%/4%。" }, { "天赋——|s17069|", "使你造成的所有伤害提高 1%/2%/3%/4%/5%。" }, { "基础 -|s437138|", "复活一名死亡的玩家，附带 70 点生命值和 135 点法力值。无法在战斗中使用。" } } },
                        { t = "p", v = "野性德鲁伊 DPS 输出循环最重要的改动是|s17056|，它在变形为|s768|时不再为你提供固定数量的能量；取而代之的是，它允许你恢复上一次处于|s768|形态时所拥有的能量。天赋树中的天赋也有所变动。" },
                        { t = "tb", v = { { "|s17056|", "在变形为|s768|时不再为你提供固定数量的能量；取而代之的是，它允许你恢复上一次处于|s768|时不再为你提供固定数量的能量。" }, { "|s5217|", "现在使你的伤害提高 15%，而非固定的伤害数值。" }, { "|s16864|", "现在是一项可以在 20 级时学习的基础被动技能。" }, { "|s1238122|", "现在包含|s414924|，可让你在|s768|中跃向目标敌人身后；不过两者共享冷却时间。" }, { "|s16958|", "现在还包括：你在猎豹形态下能够生成连击点数的非周期性技能的暴击有 50% 的几率额外产生 1 个连击点数。" }, { "|s1223082|", "现在使法术和近战攻击的暴击几率提高 2%/4%。" }, { "|s16689|", "现在作为 10 级的基础法术加入。" }, { "|s17007|", "现在与|s24858|增益互斥。" } } },
                    } },
                    { key = "viability", flow = {
                        { t = "p", v = "《魔兽世界：无限》版本的目标之一是让每个职业和天赋都具备可用性。请用几行文字（最多两段）谈谈你对职业可用性的初步看法，重点关注团本和 PvE 内容；也欢迎顺带提一下 PvP 和练级体验。" },
                    } },
                    { key = "sw", flow = {
                        { t = "p", v = "本节将在我们获得更多 Beta 测试信息后更新。" },
                        { t = "good", v = { "副坦克- 野性德鲁伊是唯一能同时担任坦克和输出的专精，因此是最佳副坦选择。", "机动性- 诸如|s17002|和|s1238122|配合使用，|s23099|使野性德鲁伊成为机动性最强的职业之一。", "战斗复活-|s20484|能轻松把一次灭团变成一次击杀！" } },
                        { t = "bad", v = { "能量等待- 除了等待能量恢复外，基本没有其他事情可做。", "缺乏群体伤害/顺劈伤害- 除了给多个目标上持续伤害之外，没有真正意义上的群体伤害/顺劈技能。|s1822|", "多面手- 通常会被期待不仅担任输出，还要协助扛怪或提供其他功能性。" } },
                    } },
                    { key = "beginner", flow = {
                        { t = "p", v = "《魔兽世界：无限》中的野性德鲁伊龙猫输出是对专精最友好的新手版本；然而，作为一名德鲁，你有许多可选内容，新手需要应对不同的形态转换，可能会觉得应接不暇。团队对野性德鲁伊的期望通常相当高，许多人会期望你随时准备好切去抗怪。" },
                    } },
                    { key = "systems", flow = {
                        { t = "p", v = "变形是德鲁伊独有的能力。作为一名野性德鲁伊输出，通常你会希望尽可能保持|s768|。但要想成为一名真正优秀的野性德鲁伊，你应当能够在不同场合灵活运用所有形态。如果坦克阵亡，能够瞬间切为|s5487|并拉住怪物，这能迅速拯救团队避免团灭。或者如果需要额外的治疗，切出形态施放治疗也会很有帮助，甚至可以在治疗坐下喝水时帮助抬血线。" },
                    } },
                    { key = "races", flow = {
                        { t = "p", v = "《魔兽世界：无限》中德鲁伊只有一个新种族可选，那就是新种族：天裔。德鲁伊可选的其他种族也已重做，新增了种族特长。" },
                        { t = "races", v = { { race = "暗夜精灵", side = "alliance", mark = "tick" }, { race = "牛头人", side = "horde", mark = "tick" } } },
                        { t = "p", v = "无限服新增的职业-种族组合" },
                        { t = "p", v = "对于野性德鲁伊输出而言，选择并不多，哪个种族更强一目了然，或者说至少在联盟这边非常明显——暗夜精灵凭借|s1259799|无疑是最佳选择。对于部落而言，牛头人和天裔相差不大，而牛头人只要你能从其命中加成中获益，就是略胜一筹的选择。|s20550|时不再为你提供固定数量的能量。" },
                        { t = "h4", v = "联盟 / 部落天裔" },
                        { t = "p", v = "天裔德鲁伊对联盟和部落双方阵营均开放。两个阵营都能获得1%急速增益，来源是|s1259710|，并可通过|s1259416|规避坠落伤害机制。联盟和部落各有其独特的主动技能|s1259705|和|s1259686|，但这些主动技能对野性德鲁伊的DPS而言并没有实质作用，因为我们并不在意法力值，而且|s1259686|的移速加成无法与|s17002|叠加。1%急速加成虽然不错，但不会影响我们的能量回复，实际上只能略微提升自动攻击伤害，并使|s16870|触发频率略有提高。" },
                        { t = "h4", v = "联盟暗夜精灵" },
                        { t = "p", v = "暗夜精灵在《魔兽世界：无限》中的重大改动是新增了|s1259799|. 10%暴击率，持续15秒的爆发技能非常强力，能显著提升野性德鲁伊的爆发伤害，特别是在与|s5217|15%增伤效果期间同时使用时效果更佳。|s20580|的机制有所改动，如果你战斗中的仇恨过高，可以用来取消怪物对你的攻击；不过要注意，一旦你取消了|s20580|，你的仇恨值也会回来！暗夜精灵还保留着他们的种族特长：|s20585|、|s20582|和|s20585|。这些对伤害都没有太大影响。2%的移动速度加成不会与|s17002|时不再为你提供固定数量的能量。" },
                        { t = "h4", v = "部落牛头人" },
                        { t = "p", v = "牛头人获得了一些有趣的增益。对|s20550|的加成可为野性德鲁伊提供1%的命中加成，这是牛头人唯一能提升DPS的种族特长；它影响我们的所有技能和近战攻击，因此只要命中不会因此超出命中上限，就是非常强力的天赋。|s20549|也是个强力的爆发技能，现在可以在所有形态下使用，但由于怪物普遍具有昏迷免疫，团战中常常派不上用场。新的被动效果|s1259918|升级初期可能有用，但在满级时对野性德鲁伊毫无用处，因为无法叠加|s17002|时不再为你提供固定数量的能量。" },
                    } },
                    { key = "prof", flow = {
                        { t = "p", v = "我们才刚刚开始触及专业技能如何影响游戏玩法这一话题的皮毛。营地这一新机制为所有专业带来了有趣的补充。开发者致力于尽量模糊相关信息，所以随着我们了解更多，本主题会持续更新。" },
                        { t = "p", v = "一直凭借各种工具的多功能性稳居榜单前列。被暗示是《魔兽世界：无限》组成部分的是其中最突出的代表，但还有许多其他工具，例如炸弹、降落伞披风、隐形装置、训练假人，以及在《魔兽世界：无限》中尚未被发现的新配方。如今即使在变形形态下也能使用这些爆炸物，使我们野性德鲁伊能更轻松地发挥其全部潜力。" },
                        { t = "p", v = "通过调酒学（药剂和合剂效果+25%）提供强大的伤害加成，哲学之石可能是不错的饰品；但从历史经验来看并非如此。" },
                        { t = "p", v = "提供个人戒指附魔。官方公告提到攻击强度、耐力或法术强度的附魔选项。" },
                        { t = "p", v = "是另一个强力专业，因为加入了护甲片和刺绣，分别为护腕/披风提供增益。《魔兽世界：无限》还引入了大量可制作装备以帮助升级，也可能包含满级物品。" },
                        { t = "p", v = "提供腰带扣以提升属性。是否值得投入取决于腰带扣增益的强度，以及该专业是否会产出独有的制造武器。" },
                        { t = "p", v = "采集类专业（//）在 PvE 方面影响不大，但对钱包影响显著，可以帮你负担各种团队副本消耗品。或为最佳选择，因为分别提供魔法抗性和生命值加成，能提升生存能力。" },
                    } },
                },
            },
            resto = {
                updated = "2026/09/26",
                sections = {
                    { key = "changes", flow = {
                        { t = "p", v = "虽然《魔兽世界：无限》中的大部分法术与天赋仍然让人熟悉，但我们看到许多数值和效果发生了变化，这将改变我们使用职业的方式。恢复德鲁伊仍将继续拥有有趣多样的治疗工具，以应对地下城或团队副本中的任何情况。同样值得关注的是，恢复德鲁伊在《魔兽世界：无限》当前版本里缺少了什么：生命绽放、滋养、繁盛以及枭兽形态。究竟这种缺失会对满级治疗产生怎样的影响，时间会给出答案。" },
                        { t = "p", v = "恢复德鲁伊从后续资料片中获得了几个强力新技能与天赋。我们看到|s408120|和|s437138|回到了我们的技能列表，同时天赋树也进行了大量调整，使我们曾经熟悉的天赋以全新的方式影响我们的玩法。" },
                        { t = "tb", v = { { "|s408120|", "这个著名的多目标周期性治疗技能回归后有了新机制：不再向周围目标扩散，而是锁定作用于目标的小队成员。|s408120|现在更接近牧师职业的|s25316|。" }, { "|s437138|", "地下城治疗者们欢呼雀跃。我们将在《魔兽世界：无限》中获得一个战斗外复活技能，帮助我们在治疗之旅中更顺畅。虽然有些人觉得单靠一个|s20484|加上30分钟冷却的紧张感为小队内容提供了趣味,但我们其余的人会乐于享受这样的安心感——手快的DPS不再让我们的冒险陷入险境。" }, { "|s414673|", "将我们的|s1430|、|s408120|和|s18562|的公共冷却时间缩短至一秒。作为经典版本新增的天赋，我们可以看到暴雪正着手描绘「快速 HoT 是应对治疗情境的强力工具」这一图景。这将使我们能够快速铺开全团 HoT 覆盖以应对 AoE 场合，并以同样快的速度补上|s408120|，接住任何掉血过快的队伍。" }, { "|s1223081|", "满级时为我们的 HoT 提供 5% 加成。由于它位于平衡天赋树的第一层，任何天赋构筑都能轻松点出。" }, { "|s1223082|", "满级时使我们的治疗额外获得 4% 暴击。我们的所有 HoT 现在都能暴击，因此这个天赋是提升治疗输出量的绝佳选择。" }, { "|s1223083|", "延长我们的|s1430|和|s8938|的 HoT 持续时间。这个天赋与|s18562|联动极佳，后者现在的治疗量取整个 HoT 的持续时间总量，而不再是固定的秒数。" } } },
                        { t = "p", v = "我们现有的技能和天赋有许多改动。我们看到那些熟悉的效应得到了全新的更新，改变了我们对它们治疗影响力的看法。" },
                        { t = "tb", v = { { "|s782|", "现在使反弹的伤害按施法者的法术强度缩放。" }, { "|s8938|", "法力消耗大幅降低，且其 HoT 部分现在可以暴击。" }, { "|s16864|", "现在成为基础技能，且可由施法触发。留意该增益，随后施放一个大型的|s408120|、|s5188|或|s8938|，将对法力效率有极大帮助。" }, { "|s17063|", "现在是恢复天赋树的第一层天赋，完全取代了强化野性印记。它现在影响所有自然系与奥术系法术，这为混合输出与治疗联动打开了大门，也足以成为一个有价值的诱饵天赋，方便我们的枭兽朋友跨天赋借用。" }, { "|s17118|", "天赋层级上移一格，现在影响所有自然系与奥术系法术，而不仅仅是治疗法术。天赋消耗从 5 点降低到 3 点，在满级时的效果从 20% 威胁值降低提升至 30%。" }, { "|s17106|", "从原本略显疲软的施法时 15% 法力值回复大幅增强至惊人的 50% 施法时法力值回复。回复属性提升超过 3 倍，这让大家对在组队内容中进行治疗时的法力值限制会产生诸多疑问。" }, { "|s17104|", "效果保持不变，但天赋层级从第五层上调到第三层，且不再需要投入点数到|s5570|即可点出。这一强力的总体治疗乘数现在更早可用，也能被更多天赋构筑选择。" }, { "|s17111|", "现在作为天赋的前置，可解锁|s17074|。仍需测试，但目前的假设是它将成为|s1430|的总体乘数，而不再像经典旧世那样仅仅改变法术的基础治疗量。" }, { "|s18562|", "现在大幅前移到天赋树中，不再是恢复系的终极天赋。在《魔兽世界：无限》中，它的新效果会完整治疗整个周期性治疗效果（HoT）的治疗量，且默认不再消耗该 HoT。会选取目标身上治疗量最高的 HoT。这是一个非常受欢迎的改动，为各种延长我们 HoT 持续时间的效果带来了大量联动空间。" }, { "|s1309631|", "作为《燃烧的远征》资料片的天赋，|s1309631|将为我们的精神属性总值提供总体乘数。在以往的资料片中，该天赋会与其他百分比属性加成叠加，例如（来源）合计为|s20217|, 并且预计在无限服中也同样有效。这是一个强力天赋，可与|s17106|" }, { "|s17123|", "现在还会缩短|s740|的冷却时间至最高2分钟。|s17123|是挑战地下城时的最强天赋。无威胁的特性加上强力的全队治疗可以在极端危急时刻挽救团灭。" }, { "|s17003|", "从野性天赋树深处上移至第一层。只需少量投入就能显著提升智力属性，是非常值得选择的天赋。" }, { "|s16845|", "现在仅降低伤害性技能的法术消耗。经典时代的恢复德鲁伊会失望地发现，这个曾定义整个流派的天赋不再值得投入。" }, { "|s16880|", "现在更新为提供10%急速和公共冷却缩短，持续三秒，而不是让下一次施法减少0.5秒。这为|s16880|+|s17074|流派通过在|s8938|施法之间穿插|s1430|和|s18562|来叠加这个急速增益提供了很大潜力。选择这个天赋意味着放弃|s408120|，因此其价值取决于|s408120|在团队副本中。" } } },
                    } },
                    { key = "viability", flow = {
                        { t = "p", v = "恢复德鲁伊在PvE内容中依然是强力的治疗职业。从目前已公开的信息来看，我们拥有极高的效率、强大的单体治疗量、出色的全团HoT治疗覆盖，以及经典|s20484|和|s29166|帮助团队冲过终点。" },
                        { t = "p", v = "恢复德鲁伊在副本主流配置中的排名位置，将取决于其他职业的平衡以及首领战的设计。HoT治疗在团队承伤较低的场合会首先感到吃力，需要有压倒性的伤害让HoT自然跳动，而不被其他职业的直接治疗抢走生效。" },
                        { t = "p", v = "恢复德鲁伊面临的另一个大问题是，相较其他治疗职业，我们能带来怎样的独特辅助。恢复德鲁伊传统上提供的辅助是\"防御恢复\"，即在犯错时将团队拉回正轨、扛过意外状况的能力。竞争激烈的团队通常更看重进攻型辅助技能组合，并相信玩家自身的实力足以避免陷入这些糟糕的局面。" },
                    } },
                    { key = "sw", flow = {
                        { t = "p", v = "恢复德鲁伊在合适的玩家手中是出色的治疗者，但部分团队可能会寻求比出色治疗更高的要求。" },
